export type TaskLedgerNodeKind =
  | 'goal'
  | 'milestone'
  | 'task'
  | 'check'
  | 'decision'
  | 'risk'
  | 'deviation'
  | 'review';

export type TaskLedgerNodeStatus = 'todo' | 'doing' | 'blocked' | 'review' | 'done' | 'dropped';
export type TaskLedgerActor = 'user' | 'assistant' | 'system';
export type TaskLedgerOwner = 'user' | 'agent' | 'system';
export type TaskLedgerPriority = 'low' | 'normal' | 'high';

export type TaskLedgerEdgeType =
  | 'depends_on'
  | 'blocks'
  | 'relates_to'
  | 'derived_from'
  | 'supersedes'
  | 'needs_review';

export type TaskLedgerEventType =
  | 'node_created'
  | 'node_updated'
  | 'node_deleted'
  | 'status_changed'
  | 'progress_changed'
  | 'edge_added'
  | 'edge_removed'
  | 'dependency_added'
  | 'decision_recorded'
  | 'deviation_logged'
  | 'review_requested'
  | 'review_cleared'
  | 'session_linked'
  | 'working_context_proposed'
  | 'working_context_proposal_accepted'
  | 'working_context_proposal_rejected';

export const TASK_LEDGER_WORKING_CONTEXT_FIELDS = [
  'Objective',
  'Constraints',
  'ConfirmedFacts',
  'Decisions',
  'OpenRisks',
  'ActiveFiles',
  'Evidence',
  'NextAction',
] as const;

export type TaskLedgerWorkingContextField = (typeof TASK_LEDGER_WORKING_CONTEXT_FIELDS)[number];
export type TaskLedgerWorkingContextSensitivity = 'public' | 'workspace' | 'secret-adjacent';
export type TaskLedgerWorkingContextTrust = 'confirmed' | 'proposed' | 'uncertain';

/** Bounded Working Context values. Evidence is refs only; raw payload is forbidden. */
export type TaskLedgerWorkingContextFieldValue = string | string[] | TaskLedgerEvidenceRef[];

export type TaskLedgerWorkingContextProposal = {
  proposalId: string;
  field: TaskLedgerWorkingContextField;
  value: TaskLedgerWorkingContextFieldValue;
  version: number;
  evidenceRefs: TaskLedgerEvidenceRef[];
  ttl: { issuedAt: string; expiresAt: string };
  sensitivity: TaskLedgerWorkingContextSensitivity;
  trust: TaskLedgerWorkingContextTrust;
};

export type TaskLedgerWorkingContextDecision = {
  proposalId: string;
  field: TaskLedgerWorkingContextField;
  version: number;
  decision: 'accepted' | 'rejected';
  policyDigest: string;
  rejectionReason?: string;
};

export type TaskLedgerMemPromotionCandidate = {
  schema: 'MemPromotionCandidate/v1';
  proposalId: string;
  field: TaskLedgerWorkingContextField;
  value: TaskLedgerWorkingContextFieldValue;
  version: number;
  actor: TaskLedgerActor;
  evidenceRefs: TaskLedgerEvidenceRef[];
  sensitivity: TaskLedgerWorkingContextSensitivity;
  trust: TaskLedgerWorkingContextTrust;
  acceptedAt: string;
  policyDigest: string;
};

export type TaskLedgerWorkingContextWarningType =
  | 'invalid_event'
  | 'invalid_value'
  | 'invalid_ttl'
  | 'missing_actor'
  | 'missing_task_id'
  | 'missing_policy_digest'
  | 'missing_proposal'
  | 'version_mismatch'
  | 'duplicate_proposal'
  | 'duplicate_accept'
  | 'expired_accept'
  | 'illegal_actor'
  | 'invalid_decision';

export type TaskLedgerWorkingContextWarning = {
  type: TaskLedgerWorkingContextWarningType;
  message: string;
  eventId?: string;
  proposalId?: string;
  field?: TaskLedgerWorkingContextField;
};

export type TaskLedgerWorkingContextProposalRecord = {
  proposalId: string;
  field: TaskLedgerWorkingContextField;
  value: TaskLedgerWorkingContextFieldValue;
  version: number;
  actor: TaskLedgerActor;
  evidenceRefs: TaskLedgerEvidenceRef[];
  ttl: { issuedAt: string; expiresAt: string };
  sensitivity: TaskLedgerWorkingContextSensitivity;
  trust: TaskLedgerWorkingContextTrust;
  eventId: string;
  taskId: string;
  sessionId?: string | null;
  createdAt: string;
};

export type TaskLedgerWorkingContextAcceptedRecord = TaskLedgerWorkingContextProposalRecord & {
  acceptedEventId: string;
  policyDigest: string;
  acceptedAt: string;
};

export type TaskLedgerWorkingContextRejectedRecord = {
  proposalId: string;
  field: TaskLedgerWorkingContextField;
  version: number;
  actor: TaskLedgerActor;
  policyDigest: string;
  rejectionReason: string;
  eventId: string;
  taskId: string;
  createdAt: string;
};

export type TaskLedgerWorkingContextFieldProjection = {
  current?: TaskLedgerWorkingContextAcceptedRecord;
  history: TaskLedgerWorkingContextAcceptedRecord[];
  pending: TaskLedgerWorkingContextProposalRecord[];
  conflicts: TaskLedgerWorkingContextProposalRecord[];
  rejected: TaskLedgerWorkingContextRejectedRecord[];
  expired: TaskLedgerWorkingContextProposalRecord[];
};

export type TaskLedgerWorkingContextSnapshot = {
  schemaVersion: 1;
  fields: Record<TaskLedgerWorkingContextField, TaskLedgerWorkingContextFieldProjection>;
  promotionCandidates: TaskLedgerMemPromotionCandidate[];
  warnings: TaskLedgerWorkingContextWarning[];
};

export type TaskLedgerEvidenceRef = {
  type: 'session' | 'trace' | 'file' | 'memory' | 'manual' | 'tool' | 'other';
  ref: string;
  label?: string;
};

export type TaskLedgerNode = {
  id: string;
  title: string;
  kind: TaskLedgerNodeKind;
  parentId?: string | null;
  status: TaskLedgerNodeStatus;
  progress?: number;
  owner?: TaskLedgerOwner;
  priority?: TaskLedgerPriority;
  tags?: string[];
  description?: string;
  evidenceRefs?: TaskLedgerEvidenceRef[];
  metadata?: Record<string, unknown>;
  createdAt: string;
  updatedAt: string;
  completedAt?: string | null;
};

export type TaskLedgerEdge = {
  id: string;
  from: string;
  to: string;
  type: TaskLedgerEdgeType;
  label?: string;
  createdAt: string;
  metadata?: Record<string, unknown>;
};

export type TaskLedgerSessionLink = {
  id: string;
  sessionKey: string;
  nodeId?: string | null;
  agentId?: string | null;
  traceId?: string | null;
  relation?: 'related' | 'forked_from' | 'handoff_from';
  sourceSessionKey?: string | null;
  summary?: string;
  /** Relay depth of the linked session (1 is the first relay of a root). */
  handoffDepth?: number;
  parentHandoffId?: string;
  rootHandoffId?: string;
  handoffRootSessionKey?: string;
  createdAt: string;
};

export type TaskLedgerEventPayload = {
  node?: TaskLedgerNode;
  nodeId?: string;
  patch?: Partial<Omit<TaskLedgerNode, 'id' | 'createdAt'>>;
  status?: TaskLedgerNodeStatus;
  progress?: number;
  edge?: TaskLedgerEdge;
  edgeId?: string;
  sessionLink?: TaskLedgerSessionLink;
  reviewReason?: string;
  decision?: string;
  deviation?: string;
  note?: string;
  workingContextProposal?: TaskLedgerWorkingContextProposal;
  workingContextDecision?: TaskLedgerWorkingContextDecision;
};

export type TaskLedgerEvent = {
  id: string;
  workspaceId: string;
  type: TaskLedgerEventType;
  actor: TaskLedgerActor;
  taskId?: string | null;
  sessionId?: string | null;
  idempotencyKey?: string | null;
  payload: TaskLedgerEventPayload;
  createdAt: string;
};

export type TaskLedgerEventInput = Omit<TaskLedgerEvent, 'id' | 'workspaceId' | 'createdAt'> & {
  id?: string;
  workspaceId?: string;
  createdAt?: string;
};

export type TaskLedgerWarning = {
  type: 'invalid_jsonl' | 'invalid_event' | 'projection';
  message: string;
  line?: number;
  eventId?: string;
};

export type TaskLedgerSnapshot = {
  schemaVersion: 1;
  workspaceId: string;
  generatedAt: string;
  nodes: TaskLedgerNode[];
  edges: TaskLedgerEdge[];
  sessionLinks: TaskLedgerSessionLink[];
  rootNodeIds: string[];
  reviewNodeIds: string[];
  activeNodeIds: string[];
  blockedNodeIds: string[];
  currentGoalId?: string | null;
  recentDecisions: TaskLedgerNode[];
  eventsCount: number;
  warnings: TaskLedgerWarning[];
};

import { createHash, randomUUID } from 'node:crypto';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import type {
  TaskLedgerEdge,
  TaskLedgerEvent,
  TaskLedgerEventInput,
  TaskLedgerNode,
  TaskLedgerSessionLink,
  TaskLedgerSnapshot,
  TaskLedgerWarning,
} from '../../shared/types/task-ledger';
import { getOpenClawConfigDir } from '../utils/paths';

const SCHEMA_VERSION = 1 as const;

export type TaskLedgerReadResult = {
  events: TaskLedgerEvent[];
  warnings: TaskLedgerWarning[];
};

export function normalizeTaskLedgerWorkspaceId(workspaceId?: string | null): string {
  const raw = workspaceId?.trim() || 'default';
  const slug = raw
    .normalize('NFKD')
    .replace(/[^\w.-]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 72);
  const hash = createHash('sha1').update(raw).digest('hex').slice(0, 10);
  return `${slug || 'workspace'}-${hash}`;
}

export function getTaskLedgerDir(workspaceId?: string | null): string {
  return getTaskLedgerDirForKey(normalizeTaskLedgerWorkspaceId(workspaceId));
}

function getTaskLedgerDirForKey(workspaceKey: string): string {
  return join(getOpenClawConfigDir(), 'task-ledgers', 'workspaces', workspaceKey);
}

export function getTaskLedgerEventsPath(workspaceId?: string | null): string {
  return join(getTaskLedgerDir(workspaceId), 'events.jsonl');
}

function getTaskLedgerEventsPathForKey(workspaceKey: string): string {
  return join(getTaskLedgerDirForKey(workspaceKey), 'events.jsonl');
}

export function getTaskLedgerSnapshotPath(workspaceId?: string | null): string {
  return join(getTaskLedgerDir(workspaceId), 'snapshot.json');
}

function getTaskLedgerSnapshotPathForKey(workspaceKey: string): string {
  return join(getTaskLedgerDirForKey(workspaceKey), 'snapshot.json');
}

function nowIso(): string {
  return new Date().toISOString();
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function hasValidEventShape(value: unknown): value is TaskLedgerEvent {
  if (!isRecord(value)) return false;
  return typeof value.id === 'string'
    && typeof value.workspaceId === 'string'
    && typeof value.type === 'string'
    && typeof value.actor === 'string'
    && typeof value.createdAt === 'string'
    && isRecord(value.payload);
}

function clampProgress(value: number | undefined): number | undefined {
  if (typeof value !== 'number' || Number.isNaN(value)) return undefined;
  return Math.max(0, Math.min(100, Math.round(value)));
}

function normalizeNode(input: TaskLedgerNode, timestamp: string): TaskLedgerNode {
  const status = input.status ?? 'todo';
  return {
    ...input,
    parentId: input.parentId ?? null,
    status,
    tags: Array.isArray(input.tags) ? input.tags : [],
    progress: clampProgress(input.progress),
    createdAt: input.createdAt || timestamp,
    updatedAt: input.updatedAt || timestamp,
    completedAt: status === 'done' ? (input.completedAt ?? timestamp) : (input.completedAt ?? null),
  };
}

function normalizeEdge(input: TaskLedgerEdge, timestamp: string): TaskLedgerEdge {
  return {
    ...input,
    createdAt: input.createdAt || timestamp,
  };
}

export function createTaskLedgerEvent(
  workspaceId: string,
  input: TaskLedgerEventInput,
  batchIdempotencyKey?: string | null,
): TaskLedgerEvent {
  const createdAt = input.createdAt ?? nowIso();
  return {
    ...input,
    id: input.id ?? randomUUID(),
    workspaceId,
    createdAt,
    idempotencyKey: input.idempotencyKey ?? batchIdempotencyKey ?? null,
    taskId: input.taskId ?? input.payload.nodeId ?? input.payload.node?.id ?? null,
    sessionId: input.sessionId ?? null,
  };
}

export async function readTaskLedgerEvents(workspaceId?: string | null): Promise<TaskLedgerReadResult> {
  const eventsPath = getTaskLedgerEventsPathForKey(normalizeTaskLedgerWorkspaceId(workspaceId));
  let raw;
  try {
    raw = await readFile(eventsPath, 'utf8');
  } catch {
    return { events: [], warnings: [] };
  }
  return parseTaskLedgerEventLog(raw);
}

export function parseTaskLedgerEventLog(raw: string): TaskLedgerReadResult {
  const events: TaskLedgerEvent[] = [];
  const warnings: TaskLedgerWarning[] = [];
  raw.split(/\r?\n/u).forEach((line, index) => {
    if (!line.trim()) return;
    try {
      const parsed = JSON.parse(line) as unknown;
      if (!hasValidEventShape(parsed)) {
        warnings.push({ type: 'invalid_event', line: index + 1, message: 'Task ledger event is missing required fields.' });
        return;
      }
      events.push(parsed);
    } catch (error) {
      warnings.push({
        type: 'invalid_jsonl',
        line: index + 1,
        message: error instanceof Error ? error.message : String(error),
      });
    }
  });
  return { events, warnings };
}

function sortByUpdatedDesc(left: TaskLedgerNode, right: TaskLedgerNode): number {
  return Date.parse(right.updatedAt) - Date.parse(left.updatedAt);
}

export function projectTaskLedgerSnapshot(
  workspaceId: string,
  events: TaskLedgerEvent[],
  readWarnings: TaskLedgerWarning[] = [],
): TaskLedgerSnapshot {
  const nodes = new Map<string, TaskLedgerNode>();
  const edges = new Map<string, TaskLedgerEdge>();
  const sessionLinks = new Map<string, TaskLedgerSessionLink>();
  const warnings: TaskLedgerWarning[] = [...readWarnings];

  for (const event of events) {
    try {
      const timestamp = event.createdAt || nowIso();
      const nodeId = event.payload.nodeId ?? event.taskId ?? event.payload.node?.id;
      switch (event.type) {
        case 'node_created':
        case 'decision_recorded':
        case 'deviation_logged': {
          const node = event.payload.node;
          if (!node) break;
          nodes.set(node.id, normalizeNode(node, timestamp));
          break;
        }
        case 'node_updated': {
          if (!nodeId) break;
          const existing = nodes.get(nodeId);
          if (!existing) break;
          const patch = event.payload.patch ?? {};
          const status = patch.status ?? existing.status;
          nodes.set(nodeId, {
            ...existing,
            ...patch,
            id: existing.id,
            createdAt: existing.createdAt,
            status,
            progress: clampProgress(patch.progress ?? existing.progress),
            updatedAt: patch.updatedAt ?? timestamp,
            completedAt: status === 'done' ? (patch.completedAt ?? existing.completedAt ?? timestamp) : (patch.completedAt ?? existing.completedAt ?? null),
          });
          break;
        }
        case 'node_deleted': {
          if (!nodeId) break;
          nodes.delete(nodeId);
          for (const [edgeId, edge] of edges) {
            if (edge.from === nodeId || edge.to === nodeId) edges.delete(edgeId);
          }
          for (const [linkId, link] of sessionLinks) {
            if (link.nodeId === nodeId) sessionLinks.delete(linkId);
          }
          break;
        }
        case 'status_changed':
        case 'review_requested':
        case 'review_cleared': {
          if (!nodeId) break;
          const existing = nodes.get(nodeId);
          if (!existing) break;
          const status = event.type === 'review_requested'
            ? 'review'
            : event.type === 'review_cleared'
              ? (event.payload.status ?? 'todo')
              : event.payload.status;
          if (!status) break;
          nodes.set(nodeId, {
            ...existing,
            status,
            updatedAt: timestamp,
            completedAt: status === 'done' ? (existing.completedAt ?? timestamp) : existing.completedAt ?? null,
            metadata: event.payload.reviewReason
              ? { ...(existing.metadata ?? {}), reviewReason: event.payload.reviewReason }
              : existing.metadata,
          });
          break;
        }
        case 'progress_changed': {
          if (!nodeId) break;
          const existing = nodes.get(nodeId);
          if (!existing) break;
          nodes.set(nodeId, {
            ...existing,
            progress: clampProgress(event.payload.progress),
            updatedAt: timestamp,
          });
          break;
        }
        case 'edge_added':
        case 'dependency_added': {
          const edge = event.payload.edge;
          if (edge) edges.set(edge.id, normalizeEdge(edge, timestamp));
          break;
        }
        case 'edge_removed': {
          if (event.payload.edgeId) edges.delete(event.payload.edgeId);
          break;
        }
        case 'session_linked': {
          const link = event.payload.sessionLink;
          if (link) sessionLinks.set(link.id, { ...link, createdAt: link.createdAt || timestamp });
          break;
        }
        default:
          break;
      }
    } catch (error) {
      warnings.push({
        type: 'projection',
        eventId: event.id,
        message: error instanceof Error ? error.message : String(error),
      });
    }
  }

  const allNodes = [...nodes.values()].sort((a, b) => Date.parse(a.createdAt) - Date.parse(b.createdAt));
  const existingNodeIds = new Set(allNodes.map((node) => node.id));
  const allEdges = [...edges.values()].filter((edge) => existingNodeIds.has(edge.from) && existingNodeIds.has(edge.to));
  const reviewEdgeNodeIds = allEdges
    .filter((edge) => edge.type === 'needs_review')
    .flatMap((edge) => [edge.from, edge.to]);
  const reviewNodeIds = [...new Set([
    ...allNodes.filter((node) => node.status === 'review' || node.kind === 'review').map((node) => node.id),
    ...reviewEdgeNodeIds,
  ])].filter((id) => existingNodeIds.has(id));
  const rootNodeIds = allNodes.filter((node) => !node.parentId || !existingNodeIds.has(node.parentId)).map((node) => node.id);
  const currentGoal = [...allNodes]
    .filter((node) => node.kind === 'goal' && node.status !== 'done' && node.status !== 'dropped')
    .sort((a, b) => {
      const rank = (status: TaskLedgerNode['status']) => (status === 'doing' ? 0 : status === 'review' ? 1 : status === 'blocked' ? 2 : 3);
      return rank(a.status) - rank(b.status) || Date.parse(b.updatedAt) - Date.parse(a.updatedAt);
    })[0] ?? null;

  return {
    schemaVersion: SCHEMA_VERSION,
    workspaceId,
    generatedAt: nowIso(),
    nodes: allNodes,
    edges: allEdges,
    sessionLinks: [...sessionLinks.values()].sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt)),
    rootNodeIds,
    reviewNodeIds,
    activeNodeIds: allNodes.filter((node) => node.status === 'doing').map((node) => node.id),
    blockedNodeIds: allNodes.filter((node) => node.status === 'blocked').map((node) => node.id),
    currentGoalId: currentGoal?.id ?? null,
    recentDecisions: allNodes.filter((node) => node.kind === 'decision').sort(sortByUpdatedDesc).slice(0, 5),
    eventsCount: events.length,
    warnings,
  };
}

export async function writeTaskLedgerSnapshot(snapshot: TaskLedgerSnapshot): Promise<void> {
  const dir = getTaskLedgerDirForKey(snapshot.workspaceId);
  await mkdir(dir, { recursive: true });
  await writeFile(getTaskLedgerSnapshotPathForKey(snapshot.workspaceId), JSON.stringify(snapshot, null, 2), 'utf8');
}

export async function loadTaskLedgerSnapshot(workspaceId?: string | null): Promise<TaskLedgerSnapshot> {
  const normalizedWorkspaceId = normalizeTaskLedgerWorkspaceId(workspaceId);
  const { events, warnings } = await readTaskLedgerEvents(workspaceId);
  const snapshot = projectTaskLedgerSnapshot(normalizedWorkspaceId, events, warnings);
  await writeTaskLedgerSnapshot(snapshot);
  return snapshot;
}

export async function appendTaskLedgerEvents(
  workspaceId: string | undefined | null,
  inputs: TaskLedgerEventInput[],
  batchIdempotencyKey?: string | null,
): Promise<TaskLedgerSnapshot> {
  const normalizedWorkspaceId = normalizeTaskLedgerWorkspaceId(workspaceId);
  const dir = getTaskLedgerDirForKey(normalizedWorkspaceId);
  await mkdir(dir, { recursive: true });

  const { events } = await readTaskLedgerEvents(workspaceId);
  const existingEventIds = new Set(events.map((event) => event.id));
  const existingIdempotencyKeys = new Set(
    events.map((event) => event.idempotencyKey).filter((key): key is string => typeof key === 'string' && key.length > 0),
  );
  if (batchIdempotencyKey && existingIdempotencyKeys.has(batchIdempotencyKey)) {
    return loadTaskLedgerSnapshot(workspaceId);
  }

  const nextEvents = inputs
    .map((input) => createTaskLedgerEvent(normalizedWorkspaceId, input, batchIdempotencyKey))
    .filter((event) => !existingEventIds.has(event.id) && !(event.idempotencyKey && existingIdempotencyKeys.has(event.idempotencyKey)));
  if (nextEvents.length > 0) {
    const lines = nextEvents.map((event) => JSON.stringify(event)).join('\n');
    await writeFile(getTaskLedgerEventsPathForKey(normalizedWorkspaceId), `${lines}\n`, { encoding: 'utf8', flag: 'a' });
  }
  return loadTaskLedgerSnapshot(workspaceId);
}

// Stage 3 real-evidence runner. Explicit-invoke only and default off. It reuses
// the accepted Stage 2 real DeepSeek -> write -> grant/Tool Guard/EffectReceipt
// chain, then appends real Stage 3 proposal/accept events to the same long-task
// ledger and records redacted evidence. The API key is read from the caller or
// process env and is never persisted or logged.
import {
  runStage2GoldenCodingTurn,
  STAGE2_GOLDEN_MODEL_REF,
  type Stage2GoldenRunOptions,
} from "../stage2-golden-run.js";
import {
  createTaskLedgerWorkingContextDecision,
  createTaskLedgerWorkingContextProposal,
  STAGE3_WORKING_CONTEXT_POLICY_DIGEST,
} from "../../../../shared/task-ledger-working-context.js";
import {
  appendStage3WorkingContextEvents,
  resolveStage3WorkingContextState,
} from "./stage3-working-context.js";
import {
  readLongTaskLedgerRevision,
  stableLongTaskLedgerRootId,
} from "./task-ledger.js";

export type Stage3GoldenRunOptions = Stage2GoldenRunOptions & {
  /** Explicit Stage 3 opt-in; defaults to env flag, which defaults off. */
  stage3WorkingContext?: boolean;
};

export type Stage3GoldenRunResult =
  | {
      ok: true;
      model: string;
      taskLedgerRootId: string;
      proposalId: string;
      revisionBefore?: { eventCount: number; revision: string; contentDigest: string };
      revisionAfter?: { eventCount: number; revision: string; contentDigest: string };
      stage2: {
        toolCallId: string;
        approvalId: string;
        effectReceiptId: string;
        journalRef?: string;
        envelopeDigest?: string;
        envelopeRef?: string;
        wireReceiptId?: string;
        wireDigest?: string;
        preSnapshotDigest: string;
        prePlanDigest: string;
        postSnapshotDigest: string;
        postPlanDigest: string;
        postContextRefKinds: string[];
      };
    }
  | {
      ok: false;
      reason:
        | 'stage3-flag-off'
        | 'api-key-missing'
        | 'invalid-workspace-path'
        | 'stage2-golden-run-failed'
        | 'task-ledger-unavailable'
        | 'stage3-event-build-failed'
        | 'stage3-revision-missing';
      message?: string;
    };

function ledgerEnv(stateDir?: string): NodeJS.ProcessEnv {
  return stateDir?.trim()
    ? { ...process.env, OPENCLAW_STATE_DIR: stateDir.trim() }
    : process.env;
}

export async function runStage3GoldenCodingTurn(
  options: Stage3GoldenRunOptions,
): Promise<Stage3GoldenRunResult> {
  const enabled = options.stage3WorkingContext
    ?? resolveStage3WorkingContextState().enabled;
  if (!enabled) {
    return { ok: false, reason: 'stage3-flag-off' };
  }
  if (!(options.apiKey ?? process.env.DEEPSEEK_API_KEY ?? '').trim()) {
    return { ok: false, reason: 'api-key-missing' };
  }

  const stage2 = await runStage2GoldenCodingTurn({
    ...options,
    stage2Dcs: true,
  });
  if (!stage2.ok) {
    if (stage2.reason === 'api-key-missing') return { ok: false, reason: 'api-key-missing' };
    if (stage2.reason === 'invalid-workspace-path') {
      return { ok: false, reason: 'invalid-workspace-path' };
    }
    return {
      ok: false,
      reason: 'stage2-golden-run-failed',
      message: `${stage2.reason}: ${stage2.message ?? ''}`,
    };
  }

  const taskLedgerRootId = stableLongTaskLedgerRootId({
    workspaceId: options.taskLedgerWorkspaceId,
    sessionKey: options.sessionKey,
    runId: options.runId,
    source: 'task_loop',
  });
  const env = ledgerEnv(options.taskLedgerStateDir);
  const before = readLongTaskLedgerRevision({
    workspaceId: options.taskLedgerWorkspaceId,
    taskLedgerRootId,
    env,
  });
  if (!before) {
    return { ok: false, reason: 'task-ledger-unavailable' };
  }

  const createdAt = new Date().toISOString();
  const proposalId = `wc-stage3-real:${options.runId}`.slice(0, 128);
  const proposal = createTaskLedgerWorkingContextProposal({
    proposalId,
    field: 'Objective',
    value: 'Stage 3 real golden coding turn Working Context objective',
    version: 1,
    actor: 'assistant',
    taskId: taskLedgerRootId,
    sessionId: options.sessionKey,
    evidenceRefs: [{
      type: 'tool',
      ref: stage2.journalRef ?? `run:${options.runId}`,
      label: 'Stage 3 real write evidence',
    }],
    createdAt,
  });
  if (!proposal.ok) {
    return { ok: false, reason: 'stage3-event-build-failed', message: proposal.reason };
  }
  const accept = createTaskLedgerWorkingContextDecision({
    proposalId,
    field: 'Objective',
    version: 1,
    decision: 'accepted',
    actor: 'system',
    taskId: taskLedgerRootId,
    sessionId: options.sessionKey,
    policyDigest: STAGE3_WORKING_CONTEXT_POLICY_DIGEST,
    createdAt,
  });
  if (!accept.ok) {
    return { ok: false, reason: 'stage3-event-build-failed', message: accept.reason };
  }

  appendStage3WorkingContextEvents({
    workspaceId: options.taskLedgerWorkspaceId,
    events: [proposal.event, accept.event],
    env,
    enabled: true,
  });

  const after = readLongTaskLedgerRevision({
    workspaceId: options.taskLedgerWorkspaceId,
    taskLedgerRootId,
    env,
  });
  if (!after || after.eventCount !== before.eventCount + 2) {
    return { ok: false, reason: 'stage3-revision-missing' };
  }

  return {
    ok: true,
    model: STAGE2_GOLDEN_MODEL_REF,
    taskLedgerRootId,
    proposalId,
    revisionBefore: before,
    revisionAfter: after,
    stage2: {
      toolCallId: stage2.toolCallId,
      approvalId: stage2.approvalId,
      effectReceiptId: stage2.effectReceiptId,
      ...(stage2.journalRef ? { journalRef: stage2.journalRef } : {}),
      ...(stage2.envelopeDigest ? { envelopeDigest: stage2.envelopeDigest } : {}),
      ...(stage2.envelopeRef ? { envelopeRef: stage2.envelopeRef } : {}),
      ...(stage2.wireReceiptId ? { wireReceiptId: stage2.wireReceiptId } : {}),
      ...(stage2.wireDigest ? { wireDigest: stage2.wireDigest } : {}),
      preSnapshotDigest: stage2.preSnapshotDigest,
      prePlanDigest: stage2.prePlanDigest,
      postSnapshotDigest: stage2.postSnapshotDigest,
      postPlanDigest: stage2.postPlanDigest,
      postContextRefKinds: stage2.postContextRefKinds,
    },
  };
}

// Stage 3 runtime adapter for the long-task Task Ledger. Default off: with the
// flag off this module performs zero Stage 3 JSONL read/write. With an explicit
// opt-in it delegates to the existing appendLongTaskLedgerEvents appender and
// never creates a table, snapshot cache, store, or daemon.
import type { TaskLedgerEventInput } from "../../../../shared/types/task-ledger.js";
import {
  createTaskLedgerWorkingContextDecision,
  createTaskLedgerWorkingContextProposal,
  emptyTaskLedgerWorkingContextSnapshot,
  mergeTaskLedgerWorkingContext,
  projectTaskLedgerWorkingContext,
  STAGE3_WORKING_CONTEXT_POLICY_DIGEST,
} from "../../../../shared/task-ledger-working-context.js";
import {
  appendLongTaskLedgerEvents,
  readLongTaskLedgerRevision,
} from "./task-ledger.js";

export const STAGE3_TASK_LEDGER_WORKING_CONTEXT_ENV = "OPENCLAW_STAGE3_TASK_LEDGER_WC";

export type Stage3WorkingContextState = {
  enabled: boolean;
};

export function resolveStage3WorkingContextState(
  env: NodeJS.ProcessEnv = process.env,
  explicit?: boolean,
): Stage3WorkingContextState {
  if (explicit !== undefined) return { enabled: explicit };
  const value = env[STAGE3_TASK_LEDGER_WORKING_CONTEXT_ENV];
  return { enabled: value === "1" || value === "true" };
}

export type AppendStage3WorkingContextEventsOptions = {
  workspaceId: string | null | undefined;
  events: TaskLedgerEventInput[];
  env?: NodeJS.ProcessEnv;
  /** Explicit test/runner opt-in. Defaults to env flag, which defaults off. */
  enabled?: boolean;
};

export function appendStage3WorkingContextEvents(
  options: AppendStage3WorkingContextEventsOptions,
): void {
  const state = resolveStage3WorkingContextState(options.env, options.enabled);
  if (!state.enabled || options.events.length === 0) return;
  appendLongTaskLedgerEvents(options.workspaceId, options.events, options.env ?? process.env);
}

export {
  createTaskLedgerWorkingContextDecision,
  createTaskLedgerWorkingContextProposal,
  emptyTaskLedgerWorkingContextSnapshot,
  mergeTaskLedgerWorkingContext,
  projectTaskLedgerWorkingContext,
  readLongTaskLedgerRevision,
  STAGE3_WORKING_CONTEXT_POLICY_DIGEST,
};

