export type OrchestrationTaskNodePhase =
  | "plan"
  | "architecture"
  | "worker"
  | "implementation"
  | "verification"
  | "review"
  | "security"
  | "docs"
  | "verifier"
  | "repair"
  | "redo"
  | "followup";
export type OrchestrationTaskEdgeType = "dependency" | "handoff" | "verification" | "repair_of" | "followup_of";

