type MessageToolDiscoveryParams = {
  cfg: OpenClawConfig;
  currentChannelProvider?: string;
  currentChannelId?: string;
  currentThreadTs?: string;
  currentMessageId?: string | number;
  currentAccountId?: string;
  sessionKey?: string;
  sessionId?: string;
  agentId?: string;
  requesterSenderId?: string;
  senderIsOwner?: boolean;
};

type MessageActionDiscoveryInput = Omit<ChannelMessageActionDiscoveryInput, "cfg" | "channel"> & {
  cfg: OpenClawConfig;
  channel?: string;
};

type InferredSessionDelivery = {
  accountId?: string;
  channel: string;
  threadId?: string;
  to: string;
};

const SESSION_DELIVERY_PEER_KINDS = new Set(["channel", "direct", "dm", "group"]);
const USER_PREFIXED_DIRECT_TARGET_CHANNELS = new Set(["discord", "mattermost", "msteams", "slack"]);

function formatSessionDeliveryTarget(channel: string, peerKind: string, to: string): string {
  return (peerKind === "direct" || peerKind === "dm") &&
    USER_PREFIXED_DIRECT_TARGET_CHANNELS.has(channel)
    ? `user:${to}`
    : to;
}

function inferDeliveryFromSessionKey(
  sessionKey: string | undefined,
): InferredSessionDelivery | null {
  const parsedThread = parseThreadSessionSuffix(sessionKey);
  const baseSessionKey = parsedThread.baseSessionKey ?? sessionKey;
  const parsed = parseAgentSessionKey(baseSessionKey);
  if (!parsed) {
    return null;
  }
  const parts = parsed.rest.split(":").filter(Boolean);
  if (parts.length < 3) {
    return null;
  }
  const channel = normalizeMessageChannel(parts[0]);
  if (!channel) {
    return null;
  }
  if (parts.length >= 4 && (parts[2] === "direct" || parts[2] === "dm")) {
    const accountId = resolveAgentAccountId(parts[1]);
    const to = parts.slice(3).join(":").trim();
    return to
      ? {
          accountId,
          channel,
          threadId: parsedThread.threadId,
          to: formatSessionDeliveryTarget(channel, parts[2], to),
        }
      : null;
  }
  const peerKind = parts[1] ?? "";
  if (SESSION_DELIVERY_PEER_KINDS.has(peerKind)) {
    const to = parts.slice(2).join(":").trim();
    return to
      ? {
          channel,
          threadId: parsedThread.threadId,
          to: formatSessionDeliveryTarget(channel, peerKind, to),
        }
      : null;
  }
  return null;
}

function resolveEffectiveCurrentChannelContext(options?: MessageToolOptions): {
  accountId?: string;
  currentChannelId?: string;
  currentChannelProvider?: string;
  currentThreadTs?: string;
} {
  const currentChannelProvider = options?.currentChannelProvider;
  const currentChannelId = options?.currentChannelId;
  const sessionDelivery = inferDeliveryFromSessionKey(options?.agentSessionKey);
  const sessionDeliveryChannel = normalizeMessageChannel(sessionDelivery?.channel);
  const preferSessionDeliveryContext =
    normalizeMessageChannel(currentChannelProvider) === "webchat" &&
    sessionDeliveryChannel !== undefined &&
    sessionDeliveryChannel !== "webchat" &&
    Boolean(sessionDelivery?.to);

  if (!preferSessionDeliveryContext) {
    return { currentChannelProvider, currentChannelId };
  }
  return {
    accountId: sessionDelivery?.accountId,
    currentChannelProvider: sessionDeliveryChannel,
    currentChannelId: sessionDelivery?.to,
    currentThreadTs: sessionDelivery?.threadId,
  };
}

function buildMessageActionDiscoveryInput(
  params: MessageToolDiscoveryParams,
  channel?: string,
): MessageActionDiscoveryInput {
  return {
    cfg: params.cfg,
    ...(channel ? { channel } : {}),
    currentChannelId: params.currentChannelId,
    currentThreadTs: params.currentThreadTs,
    currentMessageId: params.currentMessageId,
    accountId: params.currentAccountId,
    sessionKey: params.sessionKey,
    sessionId: params.sessionId,
    agentId: params.agentId,
    requesterSenderId: params.requesterSenderId,
    senderIsOwner: params.senderIsOwner,
  };
}

function resolveMessageToolSchemaActions(params: MessageToolDiscoveryParams): string[] {
  const currentChannel = normalizeMessageChannel(params.currentChannelProvider);
  if (currentChannel) {
    const scopedActions = listChannelSupportedActions(
      buildMessageActionDiscoveryInput(params, currentChannel),
    );
    const allActions = new Set<string>(["send", ...scopedActions]);
    // Include actions from other configured channels so isolated/cron agents
    // can invoke cross-channel actions without validation errors.
    for (const plugin of listChannelPlugins()) {
      if (plugin.id === currentChannel) {
        continue;
      }
      for (const action of listCrossChannelSchemaSupportedMessageActions(
        buildMessageActionDiscoveryInput(params, plugin.id),
      )) {
        allActions.add(action);
      }
    }
    return Array.from(allActions);
  }
  return listAllMessageToolActions(params);
}

function resolveMessageToolActionSchemaActions(params: MessageToolDiscoveryParams): string[] {
  const discoveredActions = resolveMessageToolSchemaActions(params);
  const allowedActions = resolveAllowedMessageActions({
    cfg: params.cfg,
    agentId: params.agentId,
  });
  if (!allowedActions) {
    return discoveredActions;
  }
  const allow = new Set(allowedActions);
  const filtered = discoveredActions.filter((action) => allow.has(action));
  return filtered.length > 0 ? filtered : allowedActions;
}

function listAllMessageToolActions(params: MessageToolDiscoveryParams): ChannelMessageActionName[] {
  const pluginActions = listAllChannelSupportedActions(buildMessageActionDiscoveryInput(params));
  return uniqueValues<ChannelMessageActionName>(["send", "broadcast", ...pluginActions]);
}

function resolveIncludeCapability(
  params: MessageToolDiscoveryParams,
  capability: ChannelMessageCapability,
): boolean {
  const currentChannel = normalizeMessageChannel(params.currentChannelProvider);
  if (currentChannel) {
    return channelSupportsMessageCapabilityForChannel(
      buildMessageActionDiscoveryInput(params, currentChannel),
      capability,
    );
  }
  return channelSupportsMessageCapability(params.cfg, capability);
}

function resolveIncludePresentation(params: MessageToolDiscoveryParams): boolean {
  return resolveIncludeCapability(params, "presentation");
}

function resolveIncludeDeliveryPin(params: MessageToolDiscoveryParams): boolean {
  return resolveIncludeCapability(params, "delivery-pin");
}

function resolveIncludeBestEffort(params: MessageToolDiscoveryParams): boolean {
  const currentChannel = normalizeMessageChannel(params.currentChannelProvider);
  if (!currentChannel) {
    return false;
  }
  const adapter =
    listChannelPlugins().find((plugin) => plugin.id === currentChannel)?.message ??
    getLoadedChannelPlugin(currentChannel as Parameters<typeof getLoadedChannelPlugin>[0])
      ?.message ??
    getChannelPlugin(currentChannel as Parameters<typeof getChannelPlugin>[0])?.message;
  return (
    adapter?.durableFinal?.capabilities?.reconcileUnknownSend === true &&
    typeof adapter.durableFinal.reconcileUnknownSend === "function"
  );
}

function buildMessageToolSchema(params: MessageToolDiscoveryParams) {
  const actions = resolveMessageToolActionSchemaActions(params);
  const includePresentation = resolveIncludePresentation(params);
  const includeDeliveryPin = resolveIncludeDeliveryPin(params);
  const includeBestEffort = resolveIncludeBestEffort(params);
  const extraProperties = resolveChannelMessageToolSchemaProperties(
    buildMessageActionDiscoveryInput(
      params,
      normalizeMessageChannel(params.currentChannelProvider) ?? undefined,
    ),
  );
  return buildMessageToolSchemaFromActions(actions.length > 0 ? actions : ["send"], {
    includePresentation,
    includeDeliveryPin,
    includeBestEffort,
    extraProperties,
  });
}

function resolveAgentAccountId(value?: string): string | undefined {
  const trimmed = normalizeOptionalString(value);
  if (!trimmed) {
    return undefined;
  }
  return normalizeAccountId(trimmed);
}

function buildMessageToolDescription(options?: {
  config?: OpenClawConfig;
  currentChannel?: string;
  currentChannelId?: string;
  currentThreadTs?: string;
  currentMessageId?: string | number;
  currentAccountId?: string;
  sessionKey?: string;
  sessionId?: string;
  agentId?: string;
  requireExplicitTarget?: boolean;
  sourceReplyDeliveryMode?: SourceReplyDeliveryMode;
  requesterSenderId?: string;
  senderIsOwner?: boolean;
}): string {
  const baseDescription = "Send/delete/manage channel messages.";
  const resolvedOptions = options ?? {};
  const messageToolDiscoveryParams = resolvedOptions.config
    ? {
        cfg: resolvedOptions.config,
        currentChannelProvider: resolvedOptions.currentChannel,
        currentChannelId: resolvedOptions.currentChannelId,
        currentThreadTs: resolvedOptions.currentThreadTs,
        currentMessageId: resolvedOptions.currentMessageId,
        currentAccountId: resolvedOptions.currentAccountId,
        sessionKey: resolvedOptions.sessionKey,
        sessionId: resolvedOptions.sessionId,
        agentId: resolvedOptions.agentId,
        requesterSenderId: resolvedOptions.requesterSenderId,
        senderIsOwner: resolvedOptions.senderIsOwner,
      }
    : undefined;

  if (messageToolDiscoveryParams) {
    const actions = resolveMessageToolActionSchemaActions(messageToolDiscoveryParams);
    if (actions.length > 0) {
      const sortedActions = sortUniqueStrings(actions) as Array<ChannelMessageActionName | "send">;
      return appendMessageToolReadHint(
        appendMessageToolVisibleReplyHint(
          `${baseDescription} Supports actions: ${sortedActions.join(", ")}.`,
          resolvedOptions.sourceReplyDeliveryMode,
          resolvedOptions.requireExplicitTarget,
        ),
        sortedActions,
      );
    }
  }

  return appendMessageToolVisibleReplyHint(
    `${baseDescription} Supports actions: send, delete, react, poll, pin, threads, and more.`,
    resolvedOptions.sourceReplyDeliveryMode,
    resolvedOptions.requireExplicitTarget,
  );
}

function appendMessageToolVisibleReplyHint(
  description: string,
  sourceReplyDeliveryMode?: SourceReplyDeliveryMode,
  requireExplicitTarget?: boolean,
): string {
  if (sourceReplyDeliveryMode !== "message_tool_only") {
    return description;
  }
  const targetGuidance = requireExplicitTarget
    ? "Include target when sending."
    : "target defaults to the current source conversation; omit unless sending elsewhere.";
  return `${description} This turn: use action="send" with message for visible replies to the current source conversation. ${targetGuidance} Normal final answers stay private.`;
}

function appendMessageToolReadHint(
  description: string,
  actions: Iterable<ChannelMessageActionName | "send">,
): string {
  for (const action of actions) {
    if (action === "read") {
      return `${description}${MESSAGE_TOOL_THREAD_READ_HINT}`;
    }
  }
  return description;
}

export function createMessageTool(options?: MessageToolOptions): AnyAgentTool {
  const loadConfigForTool = options?.getRuntimeConfig ?? getRuntimeConfig;
  const getScopedSecretTargetsForTool =
    options?.getScopedChannelsCommandSecretTargets ?? getScopedChannelsCommandSecretTargets;
  const resolveSecretRefsForTool =
    options?.resolveCommandSecretRefsViaGateway ?? resolveCommandSecretRefsViaGateway;
  const runMessageActionForTool = options?.runMessageAction ?? runMessageAction;
  let generatedIdempotencyCounter = 0;
  const failedAutogeneratedIdempotencyKeys = new Map<string, string>();
  const effectiveCurrentChannel = resolveEffectiveCurrentChannelContext(options);
  const currentThreadTs =
    options?.currentThreadTs ??
    (options?.agentThreadId != null
      ? stringifyRouteThreadId(options.agentThreadId)
      : effectiveCurrentChannel.currentThreadTs);
  const replyToMode = options?.replyToMode ?? (currentThreadTs ? "all" : undefined);
  const agentAccountId =
    resolveAgentAccountId(options?.agentAccountId) ?? effectiveCurrentChannel.accountId;
  const resolvedAgentId =
    options?.agentId ??
    (options?.agentSessionKey
      ? resolveSessionAgentId({
          sessionKey: options.agentSessionKey,
          config: options?.config,
        })
      : undefined);
  const schema = options?.config
    ? buildMessageToolSchema({
        cfg: options.config,
        currentChannelProvider: effectiveCurrentChannel.currentChannelProvider,
        currentChannelId: effectiveCurrentChannel.currentChannelId,
        currentThreadTs,
        currentMessageId: options.currentMessageId,
        currentAccountId: agentAccountId,
        sessionKey: options.agentSessionKey,
        sessionId: options.sessionId,
        agentId: resolvedAgentId,
        requesterSenderId: options.requesterSenderId,
        senderIsOwner: options.senderIsOwner,
      })
    : MessageToolSchema;
  const description = buildMessageToolDescription({
    config: options?.config,
    currentChannel: effectiveCurrentChannel.currentChannelProvider,
    currentChannelId: effectiveCurrentChannel.currentChannelId,
    currentThreadTs,
    currentMessageId: options?.currentMessageId,
    currentAccountId: agentAccountId,
    sessionKey: options?.agentSessionKey,
    sessionId: options?.sessionId,
    agentId: resolvedAgentId,
    requireExplicitTarget: options?.requireExplicitTarget,
    sourceReplyDeliveryMode: options?.sourceReplyDeliveryMode,
    requesterSenderId: options?.requesterSenderId,
    senderIsOwner: options?.senderIsOwner,
  });

  return {
    label: "Message",
    name: "message",
    displaySummary: "Send and manage messages across configured channels.",
    description,
    parameters: schema,
    execute: async (toolCallId, args, signal) => {
      if (signal?.aborted) {
        const err = new Error("Message send aborted");
        err.name = "AbortError";
        throw err;
      }
      // Shallow-copy so we don't mutate the original event args (used for logging/dedup).
      const params = { ...(args as Record<string, unknown>) };

      // Sanitize outbound text fields in three layers:
      //
      // 1. `stripFormattedReasoningMessage` — drops reasoning blocks
      //    that some models emit into tool arguments.
      // 2. `stripInternalRuntimeContext` — removes internal-runtime-context
      //    delimited blocks (the same strip applied to final replies via
      //    `sanitizeUserFacingText`). Catches wrapped BOOT.md or webchat
      //    runtime-context echoes that preserve the marker lines.
      // 3. `stripBootEchoFromOutboundText` — defense-in-depth check against
      //    the active boot prompt for this session. Catches verbatim echoes
      //    that paraphrase out the wrapper markers but reproduce a
      //    substantial chunk of the boot prompt content. Refs #53732.
      const bootPromptForSession = getBootEchoContextForSession(options?.agentSessionKey);
      let suppressedVisiblePayloadReason: VisibleTextSuppressionReason | undefined;
      parseJsonMessageParam(params, "presentation");
      parseInteractiveParam(params);
      for (const field of [
        "text",
        "content",
        "message",
        "caption",
        "SendMessage",
        "quoteText",
        "quote_text",
      ]) {
        const suppressionReason = sanitizeStringParam(params, field, bootPromptForSession);
        suppressedVisiblePayloadReason ??= suppressionReason;
      }
      for (const field of ["pollQuestion", "poll_question"]) {
        const suppressionReason = sanitizeStringParam(params, field, bootPromptForSession);
        suppressedVisiblePayloadReason ??= suppressionReason;
      }
      for (const field of ["pollOption", "poll_option"]) {
        const suppressionReason = sanitizeStringArrayParam(params, field, bootPromptForSession);
        suppressedVisiblePayloadReason ??= suppressionReason;
      }
      const sanitizedPresentation = sanitizePresentationTextFieldsResult(
        params.presentation,
        bootPromptForSession,
      );
      params.presentation = sanitizedPresentation.value;
      suppressedVisiblePayloadReason ??= sanitizedPresentation.suppressionReason;
      const sanitizedInteractive = sanitizePresentationTextFieldsResult(
        params.interactive,
        bootPromptForSession,
      );
      params.interactive = sanitizedInteractive.value;
      suppressedVisiblePayloadReason ??= sanitizedInteractive.suppressionReason;

      const action = readStringParam(params, "action", {
        required: true,
      }) as ChannelMessageActionName;
      if (
        suppressedVisiblePayloadReason &&
        action === "send" &&
        !hasSanitizedSendPayloadContent(params)
      ) {
        return jsonResult({
          status: "suppressed",
          reason: suppressedVisiblePayloadReason,
          message:
            suppressedVisiblePayloadReason === "inbound_metadata_echo"
              ? "Suppressed outbound message text because it matched inbound runtime metadata."
              : "Suppressed outbound message text because it matched internal runtime context.",
        });
      }
      const requireExplicitTarget = options?.requireExplicitTarget === true;
      if (requireExplicitTarget && actionNeedsExplicitTarget(action)) {
        const explicitTarget =
          (typeof params.target === "string" && params.target.trim().length > 0) ||
          (typeof params.to === "string" && params.to.trim().length > 0) ||
          (typeof params.channelId === "string" && params.channelId.trim().length > 0) ||
          (Array.isArray(params.targets) &&
            params.targets.some((value) => typeof value === "string" && value.trim().length > 0));
        if (!explicitTarget) {
          throw new Error(
            "Explicit message target required for this run. Provide target/targets (and channel when needed).",
          );
        }
      }

      const rawConfig = options?.config ?? loadConfigForTool();
      const scope = resolveMessageSecretScope({
        channel: params.channel,
        target: params.target,
        targets: params.targets,
        fallbackChannel: effectiveCurrentChannel.currentChannelProvider,
        accountId: params.accountId,
        fallbackAccountId: agentAccountId,
      });
      const scopedTargets = getScopedSecretTargetsForTool({
        config: rawConfig,
        channel: scope.channel,
        accountId: scope.accountId,
      });
      const cfg = (
        await resolveSecretRefsForTool({
          config: rawConfig,
          commandName: "tools.message",
          targetIds: scopedTargets.targetIds,
          ...(scopedTargets.allowedPaths ? { allowedPaths: scopedTargets.allowedPaths } : {}),
          mode: "enforce_resolved",
          authorizeSecretRead: ({ selectedTargets }) =>
            assertMessageSecretReadAllowed({
              provenanceContext: options?.contentProvenanceContext,
              currentChannel: effectiveCurrentChannel.currentChannelProvider,
              currentAccountId: agentAccountId,
              requestedChannel: scope.channel,
              requestedAccountId: scope.accountId,
              selectedTargets,
              cfg: rawConfig,
              agentId: resolvedAgentId,
            }),
        })
      ).resolvedConfig;

      const accountId = readStringParam(params, "accountId") ?? agentAccountId;
      if (accountId) {
        params.accountId = accountId;
      }

      const gatewayResolved = resolveGatewayOptions(readGatewayCallOptions(params));
      const gateway = {
        url: gatewayResolved.url,
        token: gatewayResolved.token,
        timeoutMs: gatewayResolved.timeoutMs,
        clientName: GATEWAY_CLIENT_IDS.GATEWAY_CLIENT,
        clientDisplayName: "agent",
        mode: GATEWAY_CLIENT_MODES.BACKEND,
      };
      const hasCurrentMessageId =
        typeof options?.currentMessageId === "number" ||
        (typeof options?.currentMessageId === "string" &&
          options.currentMessageId.trim().length > 0);

      const toolContext =
        effectiveCurrentChannel.currentChannelId ||
        effectiveCurrentChannel.currentChannelProvider ||
        currentThreadTs ||
        hasCurrentMessageId ||
        replyToMode ||
        options?.hasRepliedRef ||
        options?.sameChannelThreadRequired
          ? {
              currentChannelId: effectiveCurrentChannel.currentChannelId,
              currentChannelProvider: effectiveCurrentChannel.currentChannelProvider,
              currentThreadTs,
              currentMessageId: options?.currentMessageId,
              replyToMode,
              hasRepliedRef: options?.hasRepliedRef,
              sameChannelThreadRequired: options?.sameChannelThreadRequired,
              // Direct tool invocations should not add cross-context decoration.
              // The agent is composing a message, not forwarding from another chat.
              skipCrossContextDecoration: true,
            }
          : undefined;

      let autogeneratedDeliveryFingerprint: string | undefined;
      let actionIdempotencyKey = normalizeOptionalString(params.idempotencyKey);
      if (!actionIdempotencyKey && options?.runId) {
        autogeneratedDeliveryFingerprint = buildMessageToolDeliveryFingerprint({ action, params });
        actionIdempotencyKey = failedAutogeneratedIdempotencyKeys.get(
          autogeneratedDeliveryFingerprint,
        );
        if (!actionIdempotencyKey) {
          const operationId =
            normalizeMessageToolIdempotencyKeyPart(toolCallId) ??
            String(++generatedIdempotencyCounter);
          actionIdempotencyKey = buildMessageToolAutogeneratedIdempotencyKey({
            runId: normalizeMessageToolIdempotencyKeyPart(options.runId) ?? options.runId,
            deliveryFingerprint: autogeneratedDeliveryFingerprint,
            operationId,
          });
        }
      }
      const actionParams = actionIdempotencyKey
        ? { ...params, idempotencyKey: actionIdempotencyKey }
        : params;

      let result: MessageActionRunResult;
      try {
        result = await runMessageActionForTool({
          cfg,
          action,
          params: actionParams,
          provenanceContext: options?.contentProvenanceContext,
          defaultAccountId: accountId ?? undefined,
          requesterSenderId: options?.requesterSenderId,
          senderIsOwner: options?.senderIsOwner,
          gateway,
          toolContext,
          sessionKey: options?.agentSessionKey,
          sessionId: options?.sessionId,
          agentId: resolvedAgentId,
          sandboxRoot: options?.sandboxRoot,
          sourceReplyDeliveryMode: options?.sourceReplyDeliveryMode,
          inboundEventKind: options?.inboundEventKind,
          inboundAudio: options?.currentInboundAudio,
          abortSignal: signal,
        });
      } catch (error) {
        if (autogeneratedDeliveryFingerprint && actionIdempotencyKey) {
          failedAutogeneratedIdempotencyKeys.set(
            autogeneratedDeliveryFingerprint,
            actionIdempotencyKey,
          );
        }
        throw error;
      }
      if (
        autogeneratedDeliveryFingerprint &&
        failedAutogeneratedIdempotencyKeys.get(autogeneratedDeliveryFingerprint) ===
          actionIdempotencyKey
      ) {
        failedAutogeneratedIdempotencyKeys.delete(autogeneratedDeliveryFingerprint);
      }

      const toolResult = getToolResult(result);
      if (toolResult) {
        return toolResult;
      }
      return jsonResult(result.payload);
    },
  };
}

// Outbound policy enforces message-tool allowlists and cross-context delivery
// markers/decorations before channel dispatch.
import { normalizeUniqueStringEntries } from "@openclaw/normalization-core/string-normalization";
import { getChannelPlugin } from "../../channels/plugins/index.js";
import type {
  ChannelId,
  ChannelMessageActionName,
  ChannelThreadingToolContext,
} from "../../channels/plugins/types.public.js";
import type { OpenClawConfig } from "../../config/types.openclaw.js";
import type { MessageToolsConfig } from "../../config/types.tools.js";
import type { MessagePresentation } from "../../interactive/payload.js";
import {
  isExternalOrUnknownProvenance,
  provenanceStatus,
  type ContentProvenanceContext,
} from "../../../../shared/security/content-provenance.js";
import { normalizeTargetForProvider } from "./target-normalization.js";
import { formatTargetDisplay, lookupDirectoryDisplay } from "./target-resolver.js";

/**
 * Builds a channel-native presentation for forwarded cross-context text.
 */
export type CrossContextPresentationBuilder = (message: string) => MessagePresentation;

/**
 * Text and optional rich-presentation wrapper for cross-context outbound sends.
 */
export type CrossContextDecoration = {
  prefix: string;
  suffix: string;
  presentationBuilder?: CrossContextPresentationBuilder;
};

const CONTEXT_GUARDED_ACTIONS = new Set<ChannelMessageActionName>([
  "send",
  "poll",
  "reply",
  "sendWithEffect",
  "sendAttachment",
  "upload-file",
  "thread-create",
  "thread-reply",
  "sticker",
]);

const CONTEXT_MARKER_ACTIONS = new Set<ChannelMessageActionName>([
  "send",
  "poll",
  "reply",
  "sendWithEffect",
  "sendAttachment",
  "upload-file",
  "thread-reply",
  "sticker",
]);

function resolveContextGuardTarget(
  action: ChannelMessageActionName,
  params: Record<string, unknown>,
): string | undefined {
  if (!CONTEXT_GUARDED_ACTIONS.has(action)) {
    return undefined;
  }

  if (action === "thread-reply" || action === "thread-create") {
    if (typeof params.channelId === "string") {
      return params.channelId;
    }
    if (typeof params.to === "string") {
      return params.to;
    }
    return undefined;
  }

  if (typeof params.to === "string") {
    return params.to;
  }
  if (typeof params.channelId === "string") {
    return params.channelId;
  }
  return undefined;
}

function normalizeTarget(channel: ChannelId, raw: string): string | undefined {
  return normalizeTargetForProvider(channel, raw) ?? raw.trim();
}

function isCrossContextTarget(params: {
  channel: ChannelId;
  target: string;
  toolContext?: ChannelThreadingToolContext;
}): boolean {
  const currentTarget = params.toolContext?.currentChannelId?.trim();
  if (!currentTarget) {
    return false;
  }
  const normalizedTarget = normalizeTarget(params.channel, params.target);
  const normalizedCurrent = normalizeTarget(params.channel, currentTarget);
  if (!normalizedTarget || !normalizedCurrent) {
    return false;
  }
  return normalizedTarget !== normalizedCurrent;
}

function resolveAgentMessageToolsConfig(
  cfg: OpenClawConfig,
  agentId?: string | null,
): MessageToolsConfig | undefined {
  const trimmedAgentId = agentId?.trim();
  const globalConfig = cfg.tools?.message;
  if (!trimmedAgentId) {
    return globalConfig;
  }
  const agentConfig = cfg.agents?.list?.find((entry) => entry.id === trimmedAgentId)?.tools
    ?.message;
  if (!agentConfig) {
    return globalConfig;
  }
  // Agent message-tool policy is an override layer; nested policy groups must merge independently.
  return {
    ...globalConfig,
    ...agentConfig,
    crossContext:
      globalConfig?.crossContext || agentConfig.crossContext
        ? {
            ...globalConfig?.crossContext,
            ...agentConfig.crossContext,
            marker:
              globalConfig?.crossContext?.marker || agentConfig.crossContext?.marker
                ? {
                    ...globalConfig?.crossContext?.marker,
                    ...agentConfig.crossContext?.marker,
                  }
                : undefined,
          }
        : undefined,
    broadcast:
      globalConfig?.broadcast || agentConfig.broadcast
        ? {
            ...globalConfig?.broadcast,
            ...agentConfig.broadcast,
          }
        : undefined,
    actions:
      globalConfig?.actions || agentConfig.actions
        ? {
            ...globalConfig?.actions,
            ...agentConfig.actions,
          }
        : undefined,
  };
}

/**
 * Resolves the message-tool policy after applying any agent-specific overrides.
 */
export function resolveEffectiveMessageToolsConfig(params: {
  cfg: OpenClawConfig;
  agentId?: string | null;
}): MessageToolsConfig | undefined {
  return resolveAgentMessageToolsConfig(params.cfg, params.agentId);
}

/**
 * Returns the normalized allowed message actions for an agent or the global policy.
 */
export function resolveAllowedMessageActions(params: {
  cfg: OpenClawConfig;
  agentId?: string | null;
}): string[] | undefined {
  const allow = resolveEffectiveMessageToolsConfig(params)?.actions?.allow;
  if (!allow) {
    return undefined;
  }
  const normalized = normalizeUniqueStringEntries(allow);
  return normalized.length > 0 ? normalized : undefined;
}

/**
 * Rejects disabled message actions before channel-specific send handling runs.
 */
export function enforceMessageActionAllowlist(params: {
  cfg: OpenClawConfig;
  agentId?: string | null;
  action: ChannelMessageActionName;
}): void {
  const allowed = resolveAllowedMessageActions(params);
  if (!allowed || allowed.includes(params.action)) {
    return;
  }
  throw new Error(`Message action "${params.action}" is disabled for this agent.`);
}

/**
 * Enforces cross-context message-send policy for a bound channel/thread context.
 */
export function enforceCrossContextPolicy(params: {
  channel: ChannelId;
  action: ChannelMessageActionName;
  args: Record<string, unknown>;
  toolContext?: ChannelThreadingToolContext;
  cfg: OpenClawConfig;
  agentId?: string | null;
  provenanceContext?: ContentProvenanceContext;
  dryRun?: boolean;
}): void {
  const currentTarget = params.toolContext?.currentChannelId?.trim();
  if (!currentTarget) {
    return;
  }
  if (!CONTEXT_GUARDED_ACTIONS.has(params.action)) {
    return;
  }

  const messageConfig = resolveEffectiveMessageToolsConfig({
    cfg: params.cfg,
    agentId: params.agentId,
  });
  if (messageConfig?.allowCrossContextSend) {
    return;
  }

  const currentProvider = params.toolContext?.currentChannelProvider;
  const configuredWithinProvider = messageConfig?.crossContext?.allowWithinProvider;
  const allowAcrossProviders = messageConfig?.crossContext?.allowAcrossProviders === true;

  // Provider mismatch is stronger than target mismatch; normalize targets only within one provider.
  if (currentProvider && currentProvider !== params.channel) {
    if (!allowAcrossProviders) {
      throw new Error(
        `Cross-context messaging denied: action=${params.action} target provider "${params.channel}" while bound to "${currentProvider}".`,
      );
    }
    return;
  }

  const target = resolveContextGuardTarget(params.action, params.args);
  if (!target) {
    return;
  }
  if (!isCrossContextTarget({ channel: params.channel, target, toolContext: params.toolContext })) {
    return;
  }

  if (configuredWithinProvider === false) {
    throw new Error(
      `Cross-context messaging denied: action=${params.action} target="${target}" while bound to "${currentTarget}" (channel=${params.channel}).`,
    );
  }

  // Only the agent message-tool caller supplies this wrapper. Other delivery
  // callers retain their existing implicit same-provider policy.
  const provenanceRestricted =
    !params.dryRun &&
    params.provenanceContext !== undefined &&
    isExternalOrUnknownProvenance(provenanceStatus(params.provenanceContext.provenance));
  if (!provenanceRestricted || configuredWithinProvider === true) {
    return;
  }

  throw new Error(
    `Cross-context messaging denied: external or unknown provenance requires explicit tools.message.crossContext.allowWithinProvider=true for target="${target}" while bound to "${currentTarget}" (channel=${params.channel}).`,
  );
}

/**
 * Builds cross-context marker text or a channel-native presentation for forwarded sends.
 */
export async function buildCrossContextDecoration(params: {
  cfg: OpenClawConfig;
  channel: ChannelId;
  target: string;
  toolContext?: ChannelThreadingToolContext;
  accountId?: string | null;
  agentId?: string | null;
}): Promise<CrossContextDecoration | null> {
  if (!params.toolContext?.currentChannelId) {
    return null;
  }
  // Direct tool sends are authored for their destination, not forwarded from a bound context.
  if (params.toolContext.skipCrossContextDecoration) {
    return null;
  }
  if (!isCrossContextTarget(params)) {
    return null;
  }

  const markerConfig = resolveEffectiveMessageToolsConfig({
    cfg: params.cfg,
    agentId: params.agentId,
  })?.crossContext?.marker;
  if (markerConfig?.enabled === false) {
    return null;
  }

  const currentName =
    (await lookupDirectoryDisplay({
      cfg: params.cfg,
      channel: params.channel,
      targetId: params.toolContext.currentChannelId,
      accountId: params.accountId ?? undefined,
    })) ?? params.toolContext.currentChannelId;
  // Don't force group formatting here; currentChannelId can be a DM or a group.
  const originLabel = formatTargetDisplay({
    channel: params.channel,
    target: params.toolContext.currentChannelId,
    display: currentName,
  });
  const prefixTemplate = markerConfig?.prefix ?? "[from {channel}] ";
  const suffixTemplate = markerConfig?.suffix ?? "";
  const prefix = prefixTemplate.replaceAll("{channel}", originLabel);
  const suffix = suffixTemplate.replaceAll("{channel}", originLabel);

  const buildPresentation = getChannelPlugin(params.channel)?.messaging
    ?.buildCrossContextPresentation;
  const presentationBuilder = buildPresentation
    ? (message: string) =>
        buildPresentation({
          originLabel,
          message,
          cfg: params.cfg,
          accountId: params.accountId ?? undefined,
        })
    : undefined;

  return { prefix, suffix, presentationBuilder };
}

/**
 * Reports whether an action can carry a cross-context marker in outbound payloads.
 */
export function shouldApplyCrossContextMarker(action: ChannelMessageActionName): boolean {
  return CONTEXT_MARKER_ACTIONS.has(action);
}

/**
 * Applies text markers or a preferred rich presentation to a cross-context message.
 */
export function applyCrossContextDecoration(params: {
  message: string;
  decoration: CrossContextDecoration;
  preferPresentation: boolean;
}): {
  message: string;
  presentation?: MessagePresentation;
  usedPresentation: boolean;
} {
  const usePresentation = params.preferPresentation && params.decoration.presentationBuilder;
  if (usePresentation) {
    return {
      message: params.message,
      presentation: params.decoration.presentationBuilder?.(params.message),
      usedPresentation: true,
    };
  }
  const message = `${params.decoration.prefix}${params.message}${params.decoration.suffix}`;
  return { message, usedPresentation: false };
}

import fs from "node:fs/promises";
import path from "node:path";
import {
  isExternalOrUnknownProvenance,
  provenanceStatus,
  type ContentProvenanceContext,
  type ProvenanceStatus,
} from "../../../shared/security/content-provenance.js";
import { canonicalPathFromExistingAncestor } from "../infra/fs-safe.js";
import type { AnyAgentTool } from "./agent-tools.types.js";
import { assertSandboxPath } from "./sandbox-paths.js";

export type WorkspaceExternalWriteAction = "write" | "edit" | "apply_patch";

export type WorkspaceExternalWriteTargetScope = {
  workspaceRoot?: string;
  targetPaths: readonly string[];
  /** False means the caller could not safely determine every mutation target. */
  scopeKnown: boolean;
};

export type WorkspaceExternalWritePolicyInput = {
  action: WorkspaceExternalWriteAction;
  provenanceContext?: ContentProvenanceContext;
  workspaceRoot: string;
  targetPaths: readonly string[];
  scopeKnown: boolean;
};

export type WorkspaceExternalWritePolicyResult = {
  status: ProvenanceStatus;
  allowed: boolean;
  restricted: boolean;
  externalTarget: boolean;
  reason?: string;
};

function isPathInsideRoot(root: string, candidate: string): boolean {
  const rootPath = path.resolve(root);
  const candidatePath = path.resolve(candidate);
  const relative = path.relative(rootPath, candidatePath);
  return (
    relative === "" ||
    (relative !== ".." && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative))
  );
}

export function resolveWorkspaceExternalWritePolicy(
  input: WorkspaceExternalWritePolicyInput,
): WorkspaceExternalWritePolicyResult {
  const status = provenanceStatus(input.provenanceContext?.provenance);
  const externalTarget = input.targetPaths.some(
    (targetPath) => !isPathInsideRoot(input.workspaceRoot, targetPath),
  );
  const restricted = isExternalOrUnknownProvenance(status);
  const targetScopeKnown = input.scopeKnown && input.targetPaths.length > 0;

  if (!restricted || (!externalTarget && targetScopeKnown)) {
    return { status, allowed: true, restricted, externalTarget };
  }

  return {
    status,
    allowed: false,
    restricted: true,
    externalTarget,
    reason: input.scopeKnown
      ? `Workspace external ${input.action} denied: external or unknown provenance cannot write outside the active workspace.`
      : `Workspace external ${input.action} denied: the mutation target could not be established for external or unknown provenance.`,
  };
}

export type WorkspaceExternalWriteWrapperOptions = {
  action: WorkspaceExternalWriteAction;
  provenanceContext?: ContentProvenanceContext;
  workspaceRoot: string;
  resolveTargets: (params: unknown) =>
    | (WorkspaceExternalWriteTargetScope & {
        /** Skip policy when normal tool validation should own a missing argument. */
        check: boolean;
      })
    | Promise<
        WorkspaceExternalWriteTargetScope & {
          check: boolean;
        }
      >;
};

/** Resolve aliases with the same fs-safe boundary used by workspace writes. */
export async function resolveCanonicalWorkspaceWriteScope(input: {
  workspaceRoot: string;
  targetPaths: readonly string[];
}): Promise<Pick<WorkspaceExternalWriteTargetScope, "workspaceRoot" | "targetPaths">> {
  const workspaceRoot = await fs
    .realpath(input.workspaceRoot)
    .catch(() => canonicalPathFromExistingAncestor(path.resolve(input.workspaceRoot)));
  const targetPaths: string[] = [];
  for (const targetPath of input.targetPaths) {
    const canonicalTarget = await canonicalPathFromExistingAncestor(path.resolve(targetPath));
    if (isPathInsideRoot(workspaceRoot, canonicalTarget)) {
      await assertSandboxPath({
        filePath: canonicalTarget,
        cwd: workspaceRoot,
        root: workspaceRoot,
      });
    }
    targetPaths.push(canonicalTarget);
  }
  return { workspaceRoot, targetPaths };
}

/** Run the source-dependent check before any existing write/journal wrapper. */
export function wrapToolWithWorkspaceExternalWriteProvenance(
  tool: AnyAgentTool,
  options: WorkspaceExternalWriteWrapperOptions,
): AnyAgentTool {
  return {
    ...tool,
    execute: async (toolCallId, params, signal, onUpdate) => {
      const status = provenanceStatus(options.provenanceContext?.provenance);
      if (!isExternalOrUnknownProvenance(status)) {
        return tool.execute(toolCallId, params, signal, onUpdate);
      }
      const scope = await options.resolveTargets(params);
      if (scope.check) {
        const decision = resolveWorkspaceExternalWritePolicy({
          action: options.action,
          provenanceContext: options.provenanceContext,
          workspaceRoot: scope.workspaceRoot ?? options.workspaceRoot,
          targetPaths: scope.targetPaths,
          scopeKnown: scope.scopeKnown,
        });
        if (!decision.allowed) {
          throw new Error(decision.reason ?? `Workspace external ${options.action} denied.`);
        }
      }
      return tool.execute(toolCallId, params, signal, onUpdate);
    },
  };
}

