import { type EvidenceVerifierInput, type EvidenceVerifierPolicy } from "./evidence-verifier.js";
export type VerifierCompletionVerdict = "approved" | "rejected" | "insufficient-evidence" | "out-of-scope";
export type VerifierCompletionScope = {
    taskIds: readonly string[];
};
export type VerifierCompletionRecord = {
    taskId: string;
    verdict: VerifierCompletionVerdict;
    evidenceDigest: string;
    findingCodes: string[];
    priorStatus: string;
    grantsPublish: false;
    grantsProductLock: false;
};
export type VerifierCompletionTransition = {
    nodeId: string;
    from: string;
    to: "done";
} | null;
export declare function resolveVerifierCompletionVerdict(params: {
    input: EvidenceVerifierInput;
    policy?: EvidenceVerifierPolicy;
    scope: VerifierCompletionScope;
    priorStatus: string;
}): VerifierCompletionRecord;
export declare function verifierCompletionTransition(record: VerifierCompletionRecord): VerifierCompletionTransition;
export declare function revokeVerifierCompletionVerdict(record: VerifierCompletionRecord): {
    nodeId: string;
    from: "done";
    to: string;
} | null;

