// ---------------------------------------------------------------------------
// Stage 4 (criteria 4.1-4.4): Per-Area Deprecation Telemetry
//
// Each of the 6 areas (A1-A6) has graduation criteria that, when consistently
// met, allow the area's shadow path to be promoted and the legacy fallback to
// be deprecated. This module exposes telemetry counters that record the
// signals used to make that graduation decision.
//
// All counters are in-memory only (shadow instrumentation) — they do NOT
// touch production state. They are read via `snapshot()` for the Workbench
// and audit reports.
//
// See: docs/runtime-design/development-manual.md §1.1, Stage 4
// ---------------------------------------------------------------------------

/** Lowercase area identifier used by deprecation counters. Includes A3/A4
 * which are not shadow areas but still have graduation telemetry. */
export type DeprecationArea = "a1" | "a2" | "a3" | "a4" | "a5" | "a6";

// ---------------------------------------------------------------------------
// Counter types
// ---------------------------------------------------------------------------

/** A1 deprecation: legacy fallback invocation count. */
export type A1DeprecationCounters = {
  /** Number of times the legacy `IsolationFailureRecovery` fallback ran. */
  legacyFallbackCount: number;
  /** Number of turns where the shadow isolation path succeeded (no fallback). */
  shadowSuccessCount: number;
  /** Number of times a declared-path violation was detected. */
  declaredPathViolationCount: number;
};

/** A2 deprecation: wave deferral consistency. */
export type A2DeprecationCounters = {
  /** Number of times the live scheduler agreed with the shadow prediction. */
  deferralAgreementCount: number;
  /** Number of times they disagreed (shadow predicted X, scheduler did Y). */
  deferralDisagreementCount: number;
  /** Number of waves that were deferred (re-planned to a later wave). */
  deferredWaveCount: number;
};

/** A3 deprecation: anomaly classifier + Mission outcome. */
export type A3DeprecationCounters = {
  /** Number of Mission ticks where `anomalyPattern` was non-null. */
  anomalyNonNullCount: number;
  /** Total Mission ticks observed. */
  totalMissionTicks: number;
  /** Number of Mission outcomes (continue/repair/sleep/ask_user/complete/blocked). */
  missionOutcomeCount: number;
};

/** A4 deprecation: decision quality (placeholder — A4 is decision-quality audits). */
export type A4DeprecationCounters = {
  /** Number of decisions audited. */
  auditedDecisions: number;
  /** Number of decisions flagged as low-quality. */
  lowQualityDecisions: number;
};

/** A5 deprecation: budget plan adoption. */
export type A5DeprecationCounters = {
  /** Number of turns where the compression planner adopted the A5 plan. */
  planAdoptedCount: number;
  /** Number of turns where the compression planner ignored the A5 plan. */
  planIgnoredCount: number;
  /** Number of turns where the budget was exceeded. */
  budgetExceededCount: number;
};

/** A6 deprecation: ResumeContractVerifier pass rate + volatile mislabel. */
export type A6DeprecationCounters = {
  /** Number of resume contract verifications that passed. */
  verifierPassCount: number;
  /** Number of resume contract verifications that failed. */
  verifierFailCount: number;
  /**
   * CRITICAL: Number of times a volatile checkpoint was mislabeled as
   * guaranteed. This is a critical counter — any non-zero value blocks
   * A6 graduation.
   */
  volatileMislabelCount: number;
};

// ---------------------------------------------------------------------------
// Registry
// ---------------------------------------------------------------------------

export type DeprecationCounters = {
  a1: A1DeprecationCounters;
  a2: A2DeprecationCounters;
  a3: A3DeprecationCounters;
  a4: A4DeprecationCounters;
  a5: A5DeprecationCounters;
  a6: A6DeprecationCounters;
};

const ZERO: DeprecationCounters = {
  a1: { legacyFallbackCount: 0, shadowSuccessCount: 0, declaredPathViolationCount: 0 },
  a2: { deferralAgreementCount: 0, deferralDisagreementCount: 0, deferredWaveCount: 0 },
  a3: { anomalyNonNullCount: 0, totalMissionTicks: 0, missionOutcomeCount: 0 },
  a4: { auditedDecisions: 0, lowQualityDecisions: 0 },
  a5: { planAdoptedCount: 0, planIgnoredCount: 0, budgetExceededCount: 0 },
  a6: { verifierPassCount: 0, verifierFailCount: 0, volatileMislabelCount: 0 },
};

/**
 * In-memory deprecation counter registry. One instance per process.
 * Counters are monotonically increasing (only `increment` mutates).
 *
 * Usage:
 *   import { deprecationCounters } from "./deprecation-counters.js";
 *   deprecationCounters.a1.incrementLegacyFallback();
 *   const snap = deprecationCounters.snapshot();
 */
class DeprecationCounterRegistry {
  private counters: DeprecationCounters = JSON.parse(JSON.stringify(ZERO));

  // --- A1 ---
  incrementA1LegacyFallback(delta = 1): void {
    this.counters.a1.legacyFallbackCount += delta;
  }
  incrementA1ShadowSuccess(delta = 1): void {
    this.counters.a1.shadowSuccessCount += delta;
  }
  incrementA1DeclaredPathViolation(delta = 1): void {
    this.counters.a1.declaredPathViolationCount += delta;
  }

  // --- A2 ---
  incrementA2DeferralAgreement(delta = 1): void {
    this.counters.a2.deferralAgreementCount += delta;
  }
  incrementA2DeferralDisagreement(delta = 1): void {
    this.counters.a2.deferralDisagreementCount += delta;
  }
  incrementA2DeferredWave(delta = 1): void {
    this.counters.a2.deferredWaveCount += delta;
  }

  // --- A3 ---
  incrementA3AnomalyNonNull(delta = 1): void {
    this.counters.a3.anomalyNonNullCount += delta;
  }
  incrementA3MissionTicks(delta = 1): void {
    this.counters.a3.totalMissionTicks += delta;
  }
  incrementA3MissionOutcome(delta = 1): void {
    this.counters.a3.missionOutcomeCount += delta;
  }

  // --- A4 ---
  incrementA4AuditedDecisions(delta = 1): void {
    this.counters.a4.auditedDecisions += delta;
  }
  incrementA4LowQualityDecisions(delta = 1): void {
    this.counters.a4.lowQualityDecisions += delta;
  }

  // --- A5 ---
  incrementA5PlanAdopted(delta = 1): void {
    this.counters.a5.planAdoptedCount += delta;
  }
  incrementA5PlanIgnored(delta = 1): void {
    this.counters.a5.planIgnoredCount += delta;
  }
  incrementA5BudgetExceeded(delta = 1): void {
    this.counters.a5.budgetExceededCount += delta;
  }

  // --- A6 ---
  incrementA6VerifierPass(delta = 1): void {
    this.counters.a6.verifierPassCount += delta;
  }
  incrementA6VerifierFail(delta = 1): void {
    this.counters.a6.verifierFailCount += delta;
  }
  /**
   * Record a volatile-as-guaranteed mislabel. This is the critical A6
   * graduation gate — any non-zero value blocks graduation.
   */
  incrementA6VolatileMislabel(delta = 1): void {
    this.counters.a6.volatileMislabelCount += delta;
  }

  // --- Read access ---

  /** Get a deep-copy snapshot of all counters. */
  snapshot(): DeprecationCounters {
    return JSON.parse(JSON.stringify(this.counters));
  }

  /** Get a specific area's counters (deep copy). */
  getArea(area: DeprecationArea): A1DeprecationCounters | A2DeprecationCounters | A3DeprecationCounters | A4DeprecationCounters | A5DeprecationCounters | A6DeprecationCounters {
    const snap = this.snapshot();
    switch (area) {
      case "a1": return snap.a1;
      case "a2": return snap.a2;
      case "a3": return snap.a3;
      case "a4": return snap.a4;
      case "a5": return snap.a5;
      case "a6": return snap.a6;
      default: {
        const _exhaustive: never = area;
        return _exhaustive;
      }
    }
  }

  /** Reset all counters to zero (for tests). */
  reset(): void {
    this.counters = JSON.parse(JSON.stringify(ZERO));
  }

  /**
   * Stage 4 (criterion 4.14): check whether an area has exceeded its budget.
   * Returns a degradation recommendation when exceeded.
   */
  checkBudgetViolation(area: DeprecationArea): BudgetViolationResult {
    const c = this.getArea(area);
    switch (area) {
      case "a1": {
        const a1 = c as A1DeprecationCounters;
        // A1 budget: legacy fallback rate must not exceed 5% of total turns.
        // Boundary convention (consistent with A2-A6): rate == 5.000% is
        // ALLOWED (uses strict `>`); rate > 5% triggers violation. This
        // avoids false-positive degradation at the exact boundary.
        // P2-5 note: when `total === 0` (no telemetry collected yet), we
        // intentionally return `violated: false` — degrading without data
        // would be unsafe. "No data" is NOT "good data", but it is also
        // not evidence of a problem; operators should check `total` via
        // `snapshot()` separately when diagnosing.
        const total = a1.legacyFallbackCount + a1.shadowSuccessCount;
        if (total > 0 && a1.legacyFallbackCount / total > 0.05) {
          return { area, violated: true, degrade: "a1_legacy_fallback_rate", action: "degrade_to_legacy" };
        }
        return { area, violated: false };
      }
      case "a2": {
        const a2 = c as A2DeprecationCounters;
        const total = a2.deferralAgreementCount + a2.deferralDisagreementCount;
        if (total > 0 && a2.deferralDisagreementCount / total > 0.10) {
          return { area, violated: true, degrade: "a2_deferral_disagreement_rate", action: "degrade_to_live_only" };
        }
        return { area, violated: false };
      }
      case "a3": {
        const a3 = c as A3DeprecationCounters;
        if (a3.totalMissionTicks > 0 && a3.anomalyNonNullCount / a3.totalMissionTicks > 0.20) {
          return { area, violated: true, degrade: "a3_anomaly_rate", action: "degrade_to_default_decision" };
        }
        return { area, violated: false };
      }
      case "a4": {
        const a4 = c as A4DeprecationCounters;
        if (a4.auditedDecisions > 0 && a4.lowQualityDecisions / a4.auditedDecisions > 0.10) {
          return { area, violated: true, degrade: "a4_low_quality_rate", action: "degrade_to_audit_only" };
        }
        return { area, violated: false };
      }
      case "a5": {
        const a5 = c as A5DeprecationCounters;
        const total = a5.planAdoptedCount + a5.planIgnoredCount;
        if (total > 0 && a5.planIgnoredCount / total > 0.20) {
          return { area, violated: true, degrade: "a5_plan_adoption_rate", action: "degrade_to_default_budget" };
        }
        return { area, violated: false };
      }
      case "a6": {
        const a6 = c as A6DeprecationCounters;
        // A6 has a hard gate: any volatile mislabel is a critical violation.
        if (a6.volatileMislabelCount > 0) {
          return { area, violated: true, degrade: "a6_volatile_mislabel", action: "degrade_to_full_reverification" };
        }
        const total = a6.verifierPassCount + a6.verifierFailCount;
        if (total > 0 && a6.verifierFailCount / total > 0.05) {
          return { area, violated: true, degrade: "a6_verifier_fail_rate", action: "degrade_to_full_reverification" };
        }
        return { area, violated: false };
      }
      default: {
        const _exhaustive: never = area;
        return { area: _exhaustive, violated: false };
      }
    }
  }
}

export type BudgetViolationResult =
  | { area: DeprecationArea; violated: false }
  | {
      area: DeprecationArea;
      violated: true;
      degrade: string;
      action: "degrade_to_legacy" | "degrade_to_live_only" | "degrade_to_default_decision" | "degrade_to_audit_only" | "degrade_to_default_budget" | "degrade_to_full_reverification";
    };

/** Singleton instance. */
export const deprecationCounters = new DeprecationCounterRegistry();

/**
 * A1 Layered Execution Isolation — PolicyLightSnapshotter (Stage 2 Stream 2A-3).
 *
 * Context: Round 2 design. Replaces A1's runtime path tracking with static
 * tool declarations. Snapshots `declaredWritePaths ∩ actual_fs_diff` and
 * integrates with A6 file fingerprints (single source of truth, §9.1).
 *
 * Modes:
 * - "git-diff": uses `git diff` against HEAD (or a baseline commit) to detect
 *   file changes. Behaviorally equivalent to today's snapshotter when A6 is off.
 * - "copy-on-write": copies declared write paths to a checkpoint directory
 *   before the turn; restores them on rollback.
 *
 * Integration:
 * - Reads fingerprints from A6 (`getFileFingerprint` / `fingerprintFromRecord`)
 *   READ-ONLY. Only A6 writes fingerprints.
 * - Git-diff fallback when A6 flag is off (acceptance 2.5, 2.6).
 * - For `dynamic_writes` tools, performs full fs-diff (acceptance 2.3).
 *
 * Flag-off parity (acceptance 2.11): when A1 flag is off, the snapshotter
 * returns a no-op handle — `begin()` / `commit()` / `rollback()` are no-ops.
 *
 * See: docs/runtime-design/development-manual.md §1.1 (A1), Stage 2 Stream 2A
 *      docs/runtime-design/area-1-layered-execution-isolation.md §9.1, §9.2
 */

import { execFile } from "node:child_process";
import { mkdir, copyFile, rm, stat } from "node:fs/promises";
import { join, dirname } from "node:path";
import { promisify } from "node:util";

import {
  type DirectoryFingerprint,
  type FileFingerprintDiff,
  computeFileFingerprintsForDirectory,
  diffFileFingerprints,
  fingerprintFromRecord,
} from "../../long-task-control/file-fingerprint.js";
import type { WriteRiskProfile } from "../../../shared/tool-registration.js";

const execFileAsync = promisify(execFile);

/** Snapshot mode — determines how the diff is computed. */
export type SnapshotMode = "git-diff" | "copy-on-write";

/**
 * Plan for a snapshot — what mode to use and which paths to track.
 *
 * - When `dynamicWriteTools` is non-empty, falls back to full fs-diff
 *   (git-diff mode over the whole workspace).
 * - When `declaredWritePaths` is non-empty AND all tools declare paths,
 *   uses copy-on-write mode (only snapshots the declared paths).
 */
export type SnapshotPlan = {
  mode: SnapshotMode;
  /** Paths explicitly declared by write tools (from writeRiskProfile). */
  declaredWritePaths: string[];
  /** Tools with `dynamic_writes` profile (forces full fs-diff). */
  dynamicWriteTools: string[];
  /** Workspace root for resolving relative paths. */
  workspaceRoot: string;
  /** Whether A6 fingerprint integration is enabled (flag-gated). */
  a6FingerprintEnabled: boolean;
  /** Baseline fingerprint from A6 (when enabled, for copy-on-write mode). */
  baselineFingerprint?: DirectoryFingerprint;
};

/** Handle to an active snapshot — supports commit / rollback / discard. */
export type SnapshotHandle = {
  /** Unique ID for this snapshot. */
  id: string;
  /** The plan that produced this snapshot. */
  plan: SnapshotPlan;
  /** Timestamp when the snapshot was begun. */
  begunAt: number;
  /**
   * Commit the snapshot — records the post-turn state and releases resources.
   * Called after a successful turn.
   */
  commit: () => Promise<void>;
  /**
   * Rollback the snapshot — restores the pre-turn state.
   * Called when the turn fails or is cancelled.
   */
  rollback: () => Promise<void>;
  /**
   * Discard the snapshot without committing or rolling back.
   * Called when the snapshot is no longer needed (e.g., turn was a no-op).
   */
  discard: () => Promise<void>;
  /** Diff computed after the turn (available after `commit`). */
  diff?: FileFingerprintDiff;
};

/**
 * Result of `beginSnapshot` — either a handle (success) or an error.
 */
export type SnapshotResult =
  | { ok: true; handle: SnapshotHandle }
  | { ok: false; reason: string; detail?: string };

/**
 * Configuration for the PolicyLightSnapshotter.
 */
export type PolicyLightSnapshotterConfig = {
  /** Workspace root path (for git-diff and path resolution). */
  workspaceRoot: string;
  /** Whether A1 is enabled (flag-gated). Default: false (no-op). */
  a1Enabled?: boolean;
  /** Whether A6 fingerprint integration is enabled. Default: false (git-diff fallback). */
  a6FingerprintEnabled?: boolean;
  /** Baseline fingerprint record from A6 checkpoint (when enabled). */
  baselineFingerprintRecord?: Record<string, string>;
  /** Max files to snapshot in copy-on-write mode. Default: 1000. */
  maxFilesForCopyOnWrite?: number;
  /** Timeout for git commands in ms. Default: 5000. */
  gitTimeoutMs?: number;
};

// -------------------------------------------------------------------------
// Helpers
// -------------------------------------------------------------------------

/**
 * S1 fix (P1): Remove the snapshot directory with retry.
 *
 * Windows (and some network filesystems) may have a brief delay between a
 * file handle closing and the OS releasing the directory entry for deletion.
 * This helper retries the removal up to `maxRetries` times with a small
 * backoff, ensuring the snapshot directory is reliably cleaned up before
 * `commit()` / `rollback()` / `discard()` returns.
 */
async function removeSnapshotDirWithRetry(
  snapshotDir: string,
  maxRetries = 3,
  backoffMs = 50,
): Promise<void> {
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      await rm(snapshotDir, { recursive: true, force: true });
      // Verify removal — if the directory no longer exists, we're done.
      try {
        await stat(snapshotDir);
        // Directory still exists after rm — wait and retry.
      } catch {
        return; // ENOENT — successfully removed.
      }
    } catch {
      // rm itself threw — wait and retry.
    }
    if (attempt < maxRetries) {
      await new Promise((resolve) => setTimeout(resolve, backoffMs * (attempt + 1)));
    }
  }
  // P2 fix: log when best-effort cleanup gives up after all retries, instead
  // of silently swallowing the failure. The snapshot directory may leak on
  // disk — this is not fatal (next session will overwrite) but should be
  // observable for diagnostics.
  try {
    await stat(snapshotDir);
    console.warn(
      `[PolicyLightSnapshotter] failed to remove snapshot directory after ${maxRetries + 1} attempts: ${snapshotDir}`,
    );
  } catch {
    // Directory was actually removed — no warning needed.
  }
}

/**
 * Collect declared write paths from a set of tool write-risk profiles.
 * Returns the union of all `declared_paths` and `pattern_writes` patterns
 * (patterns are returned as-is for git-diff to interpret).
 */
export function collectDeclaredWritePaths(
  toolProfiles: Array<{ name: string; profile: WriteRiskProfile }>,
): { declaredPaths: string[]; dynamicTools: string[] } {
  const declaredPaths: string[] = [];
  const dynamicTools: string[] = [];

  for (const { name, profile } of toolProfiles) {
    if (profile.kind === "declared_paths") {
      declaredPaths.push(...profile.writePaths);
    } else if (profile.kind === "pattern_writes") {
      // Patterns are added to the path list — git-diff will interpret them.
      declaredPaths.push(profile.writePattern);
    } else if (profile.kind === "dynamic_writes") {
      dynamicTools.push(name);
    }
    // no_writes tools contribute nothing.
  }

  return {
    declaredPaths: [...new Set(declaredPaths)], // dedupe
    dynamicTools,
  };
}

/**
 * Execute a git command in the workspace root.
 */
async function git(
  workspaceRoot: string,
  args: string[],
  timeoutMs: number,
): Promise<{ stdout: string; stderr: string }> {
  return execFileAsync("git", args, {
    cwd: workspaceRoot,
    timeout: timeoutMs,
    maxBuffer: 10 * 1024 * 1024, // 10 MB
  });
}

/**
 * Get the set of changed files in the working tree.
 *
 * Uses `git ls-files --modified --others --exclude-standard` to detect both
 * modified tracked files AND untracked files (respecting .gitignore). This is
 * more comprehensive than `git diff --name-only HEAD`, which only shows tracked
 * file modifications and misses newly-created untracked files.
 *
 * Returns a list of changed file paths (relative to workspace root).
 */
async function gitDiffChangedFiles(
  workspaceRoot: string,
  timeoutMs: number,
): Promise<string[]> {
  try {
    const { stdout } = await git(
      workspaceRoot,
      ["ls-files", "--modified", "--others", "--exclude-standard"],
      timeoutMs,
    );
    return stdout.split("\n").filter(Boolean);
  } catch {
    // Not a git repo, or git unavailable — fall back to empty diff.
    return [];
  }
}

// -------------------------------------------------------------------------
// No-op handle (flag-off parity)
// -------------------------------------------------------------------------

function createNoOpHandle(plan: SnapshotPlan): SnapshotHandle {
  return {
    id: `noop-${Date.now()}`,
    plan,
    begunAt: Date.now(),
    commit: async () => {},
    rollback: async () => {},
    discard: async () => {},
  };
}

// -------------------------------------------------------------------------
// Copy-on-write snapshot
// -------------------------------------------------------------------------

async function beginCopyOnWriteSnapshot(
  plan: SnapshotPlan,
  _config: PolicyLightSnapshotterConfig,
): Promise<SnapshotResult> {
  const snapshotDir = join(
    plan.workspaceRoot,
    ".openclaw",
    "snapshots",
    `snap-${Date.now()}`,
  );

  try {
    await mkdir(snapshotDir, { recursive: true });
  } catch (err) {
    return {
      ok: false,
      reason: "mkdir_failed",
      detail: String((err as Error).message),
    };
  }

  // Copy the declared write paths to the snapshot directory.
  const copiedPaths: string[] = [];
  for (const relPath of plan.declaredWritePaths) {
    const src = join(plan.workspaceRoot, relPath);
    const dst = join(snapshotDir, relPath);
    try {
      const stats = await stat(src);
      if (stats.isFile()) {
        await mkdir(dirname(dst), { recursive: true });
        await copyFile(src, dst);
        copiedPaths.push(relPath);
      }
    } catch {
      // File doesn't exist yet — it will be created during the turn.
      // No need to snapshot a non-existent file.
    }
  }

  const handle: SnapshotHandle = {
    id: `cow-${Date.now()}`,
    plan,
    begunAt: Date.now(),
    commit: async () => {
      // Compute diff if A6 fingerprint is available.
      if (plan.a6FingerprintEnabled && plan.baselineFingerprint) {
        const after = await computeFileFingerprintsForDirectory(plan.workspaceRoot, {
          include: (relPath) => copiedPaths.includes(relPath),
        });
        handle.diff = diffFileFingerprints(plan.baselineFingerprint, after);
      }
      // S1 fix (P1): retry snapshot directory cleanup to handle Windows
      // filesystem async delete delay. Retry up to 3 times with 50ms backoff.
      await removeSnapshotDirWithRetry(snapshotDir);
    },
    rollback: async () => {
      // Restore copied files from snapshot.
      for (const relPath of copiedPaths) {
        const src = join(snapshotDir, relPath);
        const dst = join(plan.workspaceRoot, relPath);
        try {
          await copyFile(src, dst);
        } catch {
          // File may have been deleted during the turn — ignore.
        }
      }
      await removeSnapshotDirWithRetry(snapshotDir);
    },
    discard: async () => {
      await removeSnapshotDirWithRetry(snapshotDir);
    },
  };

  return { ok: true, handle };
}

// -------------------------------------------------------------------------
// Git-diff snapshot
// -------------------------------------------------------------------------

async function beginGitDiffSnapshot(
  plan: SnapshotPlan,
  config: PolicyLightSnapshotterConfig,
): Promise<SnapshotResult> {
  const timeoutMs = config.gitTimeoutMs ?? 5000;

  // Record the pre-turn changed files (for diff computation).
  const preTurnChanged = await gitDiffChangedFiles(plan.workspaceRoot, timeoutMs);

  const handle: SnapshotHandle = {
    id: `git-${Date.now()}`,
    plan,
    begunAt: Date.now(),
    commit: async () => {
      // Compute the post-turn changed files.
      const postTurnChanged = await gitDiffChangedFiles(plan.workspaceRoot, timeoutMs);
      // The diff is the set of files that changed DURING the turn.
      const changedDuringTurn = postTurnChanged.filter(
        (p) => !preTurnChanged.includes(p),
      );
      // Build a simple diff (we don't have full fingerprints here, but we
      // record the changed files for diagnostics).
      handle.diff = {
        added: changedDuringTurn.map((p) => ({
          path: p,
          sha256: "",
          mtimeMs: 0,
          size: 0,
        })),
        removed: [],
        modified: [],
        touched: [],
        summary: {
          addedCount: changedDuringTurn.length,
          removedCount: 0,
          modifiedCount: 0,
          touchedCount: 0,
          isClean: changedDuringTurn.length === 0,
        },
      };
    },
    rollback: async () => {
      // Git-diff rollback: restore changed files to HEAD.
      try {
        await git(plan.workspaceRoot, ["checkout", "--", ...preTurnChanged], timeoutMs);
      } catch (err) {
        // P2 fix: log the rollback failure instead of silently swallowing it.
        // Git checkout may fail if files don't exist in HEAD — this is
        // expected for newly-created files, but should be observable.
        const message = err instanceof Error ? err.message : String(err);
        console.warn(
          `[PolicyLightSnapshotter] git checkout rollback failed for ${preTurnChanged.length} files: ${message}`,
        );
      }
    },
    discard: async () => {
      // No resources to release for git-diff mode.
    },
  };

  return { ok: true, handle };
}

// -------------------------------------------------------------------------
// Main entry point
// -------------------------------------------------------------------------

/**
 * Begin a snapshot for the current turn.
 *
 * - When A1 is disabled (flag-off parity), returns a no-op handle.
 * - When `dynamicWriteTools` is non-empty, uses git-diff mode (full fs-diff).
 * - When `declaredWritePaths` is non-empty AND no dynamic tools, uses
 *   copy-on-write mode.
 * - When A6 fingerprint is enabled, uses it as the baseline for diff.
 *
 * @param toolProfiles Write-risk profiles from registered tools.
 * @param config Snapshotter configuration.
 */
export async function beginSnapshot(
  toolProfiles: Array<{ name: string; profile: WriteRiskProfile }>,
  config: PolicyLightSnapshotterConfig,
): Promise<SnapshotResult> {
  const { declaredPaths, dynamicTools } = collectDeclaredWritePaths(toolProfiles);

  // Load A6 baseline fingerprint if available.
  let baselineFingerprint: DirectoryFingerprint | undefined;
  if (config.a6FingerprintEnabled && config.baselineFingerprintRecord) {
    baselineFingerprint = fingerprintFromRecord(
      config.baselineFingerprintRecord,
      config.workspaceRoot,
    );
  }

  const plan: SnapshotPlan = {
    mode: dynamicTools.length > 0 ? "git-diff" : "copy-on-write",
    declaredWritePaths: declaredPaths,
    dynamicWriteTools: dynamicTools,
    workspaceRoot: config.workspaceRoot,
    a6FingerprintEnabled: config.a6FingerprintEnabled ?? false,
    baselineFingerprint,
  };

  // Flag-off parity: when A1 is disabled, return no-op handle.
  if (!config.a1Enabled) {
    return { ok: true, handle: createNoOpHandle(plan) };
  }

  // No write paths and no dynamic tools → no-op (nothing to snapshot).
  if (declaredPaths.length === 0 && dynamicTools.length === 0) {
    return { ok: true, handle: createNoOpHandle(plan) };
  }

  // dynamic_writes tools → full fs-diff (git-diff mode).
  if (dynamicTools.length > 0) {
    return beginGitDiffSnapshot(plan, config);
  }

  // Otherwise → copy-on-write mode (snapshots only declared paths).
  const maxFiles = config.maxFilesForCopyOnWrite ?? 1000;
  if (declaredPaths.length > maxFiles) {
    // Too many files to copy — fall back to git-diff.
    return beginGitDiffSnapshot({ ...plan, mode: "git-diff" }, config);
  }

  return beginCopyOnWriteSnapshot(plan, config);
}

/**
 * A1 Layered Execution Isolation — Shadow write-event recorder (Stage 2 Stream 2C).
 *
 * Context: Round 2 design. During the "shadow" phase (before A1 is fully active),
 * we observe tool writes and check whether they match the declared
 * `writeRiskProfile.declaredWritePaths`. Writes to paths NOT in the declared set
 * are recorded as `undeclared_write_event` for later analysis.
 *
 * This is observe-only (shadow) — it does NOT block or modify writes. It only
 * records mismatches so we can measure declaration quality before promoting A1
 * to advisory/active modes.
 *
 * Acceptance criteria:
 * - 2.7: Shadow records `undeclared_write_event` when a tool writes to a path
 *   not in `declaredWritePaths`.
 * - 2.8: 0 `undeclared_write_event` when all tools declare correctly.
 *
 * See: docs/runtime-design/development-manual.md §Stage 2, Stream 2C
 *      docs/runtime-design/area-1-layered-execution-isolation.md §9.2
 */

import type { WriteRiskProfile } from "../../../shared/tool-registration.js";

/**
 * A single undeclared write event — recorded when a tool writes to a path
 * that is not in its declared `writeRiskProfile.declaredWritePaths`.
 */
export type UndeclaredWriteEvent = {
  /** Name of the tool that performed the write. */
  toolName: string;
  /** The path that was written to (was not declared). */
  path: string;
  /** The declared write paths for the tool (for context). */
  declaredPaths: string[];
  /** Timestamp of the event. */
  timestamp: number;
};

/**
 * Result of comparing actual writes against declared paths.
 */
export type UndeclaredWriteResult = {
  /** Paths that were written but not declared. */
  undeclaredPaths: string[];
  /** Whether any undeclared writes were detected. */
  hasUndeclared: boolean;
};

/**
 * Pure function: detect undeclared writes by comparing actual write paths
 * against declared paths.
 *
 * Uses path-prefix matching: a write to `dir/file.txt` is considered declared
 * if `dir/file.txt` is in the declared set, OR if `dir/` is a declared prefix
 * (for `pattern_writes` / `declared_paths` that point to directories).
 *
 * @param declaredPaths Paths declared by the tool's `writeRiskProfile`.
 * @param actualPaths Paths actually written to during the turn.
 * @returns The set of undeclared paths.
 */
export function detectUndeclaredWrites(
  declaredPaths: readonly string[],
  actualPaths: readonly string[],
): UndeclaredWriteResult {
  const declaredSet = new Set(declaredPaths.map(normalizePath));
  const undeclaredPaths: string[] = [];

  for (const actualPath of actualPaths) {
    const normalized = normalizePath(actualPath);
    if (!isPathDeclared(normalized, declaredSet)) {
      undeclaredPaths.push(actualPath);
    }
  }

  return {
    undeclaredPaths,
    hasUndeclared: undeclaredPaths.length > 0,
  };
}

/**
 * Shadow write-event recorder — collects `undeclared_write_event` records
 * across one or more turns.
 *
 * Usage:
 * 1. Create with tool profiles (declared write paths per tool).
 * 2. After each turn, call `recordActualWrites(toolName, actualPaths)` with
 *    the paths that were actually written (from the snapshotter's fs-diff).
 * 3. Call `getEvents()` to retrieve all recorded events.
 * 4. Call `clear()` between sessions.
 */
export class ShadowWriteEventRecorder {
  private events: UndeclaredWriteEvent[] = [];
  private declaredPathsByTool: Map<string, string[]> = new Map();
  private dynamicWriteTools: Set<string> = new Set();
  private patternWriteTools: Set<string> = new Set();

  constructor(toolProfiles: Array<{ name: string; profile: WriteRiskProfile }>) {
    for (const { name, profile } of toolProfiles) {
      if (profile.kind === "declared_paths") {
        this.declaredPathsByTool.set(name, profile.writePaths.map(normalizePath));
      } else if (profile.kind === "pattern_writes") {
        // Pattern-matching tools use glob patterns (e.g., "*.log") that can't
        // be verified by exact/path-prefix matching without a glob matcher.
        // For shadow measurement, pattern_writes tools are NOT flagged —
        // they declared their behavior, and verifying glob matches is out of
        // scope for Stage 2 shadow measurement.
        this.patternWriteTools.add(name);
      } else if (profile.kind === "dynamic_writes") {
        // dynamic_writes tools declare that they write to arbitrary paths.
        // These are NOT flagged as undeclared — the tool explicitly declared
        // that it uses dynamic_writes.
        this.dynamicWriteTools.add(name);
      }
      // no_writes tools have no declared paths — any write is undeclared.
    }
  }

  /**
   * Record actual writes for a tool. If the tool wrote to paths not in its
   * declared `writeRiskProfile`, `undeclared_write_event` records are created.
   *
   * - `dynamic_writes` tools: never flagged (they declared dynamic behavior).
   * - `pattern_writes` tools: never flagged (glob matching out of scope).
   * - `declared_paths` tools: writes outside declared paths are flagged.
   * - `no_writes` tools: ANY write is flagged as undeclared.
   *
   * @param toolName Name of the tool.
   * @param actualPaths Paths actually written to during the turn.
   */
  recordActualWrites(toolName: string, actualPaths: readonly string[]): void {
    // dynamic_writes and pattern_writes tools are never flagged.
    if (this.dynamicWriteTools.has(toolName) || this.patternWriteTools.has(toolName)) {
      return;
    }

    const declaredPaths = this.declaredPathsByTool.get(toolName) ?? [];
    const { undeclaredPaths } = detectUndeclaredWrites(declaredPaths, actualPaths);

    for (const path of undeclaredPaths) {
      this.events.push({
        toolName,
        path,
        declaredPaths,
        timestamp: Date.now(),
      });
    }
  }

  /**
   * Get all recorded `undeclared_write_event` records.
   */
  getEvents(): readonly UndeclaredWriteEvent[] {
    return this.events;
  }

  /**
   * Get the count of recorded events.
   */
  getEventCount(): number {
    return this.events.length;
  }

  /**
   * Check if any undeclared writes were recorded.
   */
  hasEvents(): boolean {
    return this.events.length > 0;
  }

  /**
   * Clear all recorded events (e.g., between sessions).
   */
  clear(): void {
    this.events = [];
  }
}

// -------------------------------------------------------------------------
// Helpers
// -------------------------------------------------------------------------

/**
 * Normalize a path for comparison: forward slashes, no trailing slash,
 * lowercase (for case-insensitive matching on Windows).
 */
function normalizePath(p: string): string {
  return p.replace(/\\/g, "/").replace(/\/+$/, "").toLowerCase();
}

/**
 * Check if a (normalized) actual path is declared.
 *
 * A path is considered declared if:
 * - It exactly matches a declared path, OR
 * - A declared path is a prefix of it (directory match): e.g., declared
 *   `output/` covers `output/file.txt`.
 */
function isPathDeclared(normalizedPath: string, declaredSet: Set<string>): boolean {
  // Exact match.
  if (declaredSet.has(normalizedPath)) {
    return true;
  }
  // Prefix match: declared `dir/` covers `dir/file.txt`.
  for (const declared of declaredSet) {
    if (declared.endsWith("/") && normalizedPath.startsWith(declared)) {
      return true;
    }
    // Also handle the case where declared is `dir` (no trailing slash)
    // and actual is `dir/file.txt`.
    if (normalizedPath.startsWith(declared + "/")) {
      return true;
    }
  }
  return false;
}

/**
 * Static write-risk declaration for tool registration — runtime-local.
 *
 * Context: Round 2 design (A1 Layered Execution Isolation). Replaces the
 * unenforceable runtime `recordPathTouch` hook with a static declaration
 * enforced at tool registration time. The snapshotter trusts
 * `declaredWritePaths ∩ actual_fs_diff` instead of runtime path tracking.
 *
 * See: docs/runtime-design/area-1-layered-execution-isolation.md §9.2
 *      docs/runtime-design/development-manual.md §1.1, Stage 2
 */

export type WriteRiskProfile =
  | { kind: 'no_writes' }
  | { kind: 'declared_paths'; writePaths: string[] }
  | { kind: 'pattern_writes'; writePattern: string }
  | { kind: 'dynamic_writes'; requiresApproval: true };

export const DEFAULT_WRITE_RISK_PROFILE: WriteRiskProfile = {
  kind: 'dynamic_writes',
  requiresApproval: true,
};

export function requiresFullFsDiff(profile: WriteRiskProfile): boolean {
  return profile.kind === 'dynamic_writes';
}

export function requiresApproval(profile: WriteRiskProfile): boolean {
  return profile.kind === 'dynamic_writes' && profile.requiresApproval;
}

export function validateWriteRiskProfile(profile: unknown): string | null {
  if (typeof profile !== 'object' || profile === null) {
    return 'writeRiskProfile is required for write-capable tools';
  }
  const p = profile as Record<string, unknown>;
  if (p.kind === 'no_writes') return null;
  if (p.kind === 'declared_paths') {
    if (!Array.isArray(p.writePaths) || p.writePaths.length === 0) {
      return 'writeRiskProfile.kind="declared_paths" requires non-empty writePaths array';
    }
    return null;
  }
  if (p.kind === 'pattern_writes') {
    if (typeof p.writePattern !== 'string' || p.writePattern.length === 0) {
      return 'writeRiskProfile.kind="pattern_writes" requires non-empty writePattern string';
    }
    // P1 fix: A pattern that matches everything is semantically equivalent to
    // `dynamic_writes` but bypasses `requiresApproval`. Reject catch-all patterns
    // so callers must use `dynamic_writes` (which requires approval) instead.
    const pattern = (p.writePattern as string).trim();
    if (pattern === '*' || pattern === '**' || pattern === '**/*' || pattern === '*/*') {
      return `writeRiskProfile.kind="pattern_writes" with writePattern="${pattern}" matches all paths; use kind="dynamic_writes" (with requiresApproval=true) instead`;
    }
    return null;
  }
  if (p.kind === 'dynamic_writes') {
    if (p.requiresApproval !== true) {
      return 'writeRiskProfile.kind="dynamic_writes" requires requiresApproval=true';
    }
    return null;
  }
  return `writeRiskProfile.kind must be one of: no_writes, declared_paths, pattern_writes, dynamic_writes (got: ${String(p.kind)})`;
}

/**
 * Tool risk level. Used by `assertWriteRiskProfileForTool` to decide whether
 * a `writeRiskProfile` is required at registration time.
 *
 * This is a filesystem-risk classification. `readonly` does not prove that a
 * tool performs no durable state transition in an existing owner store; those
 * transitions require an owning API contract and focused behavioral tests.
 *
 * - `readonly`: tool does not write to the filesystem; profile optional.
 * - `write`: tool writes to the filesystem; `writeRiskProfile` is REQUIRED.
 * - `destructive`: tool performs irreversible operations; `writeRiskProfile`
 *   is REQUIRED and must be `dynamic_writes` (full fs-diff) for safety.
 */
export type ToolRiskLevel = 'readonly' | 'write' | 'destructive';

/**
 * Error thrown by `assertWriteRiskProfileForTool` when a write-capable tool is
 * registered without a valid `writeRiskProfile`. The `field` property lets the
 * tool registry surface a named-field error to the caller (acceptance 0.4).
 */
export class MissingWriteRiskProfileError extends Error {
  readonly field = 'writeRiskProfile';
  constructor(message: string) {
    super(message);
    this.name = 'MissingWriteRiskProfileError';
  }
}

/**
 * Stage 0 enforcement seam: assert that a tool with the given risk level has a
 * valid `writeRiskProfile`. This is the minimal enforcement required by
 * acceptance criterion 0.4. The full tool-registry integration happens in
 * Stage 2; this function is the pure validation core that the registry will
 * call.
 *
 * Rules:
 * - `readonly` tools: profile is optional (may be omitted or `no_writes`).
 * - `write` tools: profile is REQUIRED; must pass `validateWriteRiskProfile`.
 * - `destructive` tools: profile is REQUIRED and must be `dynamic_writes`
 *   (destructive operations cannot declare static paths — they need full
 *   fs-diff for safety review).
 *
 * Throws `MissingWriteRiskProfileError` (with `field: 'writeRiskProfile'`)
 * when the rule is violated.
 */
export function assertWriteRiskProfileForTool(
  riskLevel: ToolRiskLevel,
  profile: unknown,
): void {
  if (riskLevel === 'readonly') {
    return; // profile optional
  }

  // write or destructive: profile required
  const validationError = validateWriteRiskProfile(profile);
  if (validationError) {
    throw new MissingWriteRiskProfileError(validationError);
  }

  const p = profile as WriteRiskProfile;

  // S2 fix (P0): semantic consistency — a write-capable tool declaring
  // `no_writes` is contradictory and would bypass all write detection.
  // Reject this combination at registration time.
  if (riskLevel === 'write' || riskLevel === 'destructive') {
    if (p.kind === 'no_writes') {
      throw new MissingWriteRiskProfileError(
        `risk="${riskLevel}" is semantically incompatible with writeRiskProfile.kind="no_writes"; ` +
          `write-capable tools must declare declared_paths, pattern_writes, or dynamic_writes`,
      );
    }
  }

  // For destructive tools, require dynamic_writes (full fs-diff).
  if (riskLevel === 'destructive') {
    if (p.kind !== 'dynamic_writes') {
      throw new MissingWriteRiskProfileError(
        `risk="destructive" requires writeRiskProfile.kind="dynamic_writes" (got "${p.kind}"); ` +
          `destructive operations must go through full fs-diff for safety review`,
      );
    }
  }
}

import type {
  ObservabilityRuntimeEvent,
  ObservabilitySpan,
  ObservabilitySpanKind,
  ObservabilitySpanStatus,
  ObservabilityTokenUsage,
  ObservabilityTrace,
  ObservabilityTraceEvent,
  ObservabilityTraceStatus,
} from "./types.js";
import { randomUUID } from "node:crypto";
import { EMPTY_OBSERVABILITY_TOKEN_USAGE, addObservabilityTokenUsage } from "./metrics.js";
import {
  TRACE_SPAN_TRUNCATION_THRESHOLD,
  type ObservabilityAreaPrefix,
  spanDropPriority,
  validateEventNamespace,
} from "./namespace-governance.js";

export type ObservabilityTraceRecorderOptions = {
  idFactory?: (prefix: string) => string;
  now?: () => number;
  /**
   * Stage 3 (criterion 3.10): caller area for namespace governance.
   * When set, event names passed to `recordEvent` must be fully-qualified
   * (`claw.{area}.{...}`) and match this area. Out-of-namespace events are
   * rejected and a `claw.core.trace.namespace_rejected` diagnostic is emitted.
   */
  callerArea?: ObservabilityAreaPrefix;
  /**
   * Stage 3 (criterion 3.13): truncation threshold for span aggregation.
   * When span count exceeds this, low-priority spans (by `spanDropPriority`)
   * are dropped and a `claw.core.trace.truncated` event is emitted.
   * Defaults to `TRACE_SPAN_TRUNCATION_THRESHOLD` (200).
   */
  truncationThreshold?: number;
};

export type StartTraceInput = {
  name: string;
  runId?: string;
  sessionKey?: string;
  task?: string;
  mode?: string;
  tags?: string[];
  metrics?: Record<string, number>;
};

export type StartSpanInput = {
  name: string;
  kind: ObservabilitySpanKind;
  parentSpanId?: string;
  roleName?: string;
  modelRef?: string;
  input?: string;
  tokenUsage?: ObservabilityTokenUsage;
  metrics?: Record<string, number>;
  attributes?: Record<string, unknown>;
  /**
   * Stage 3: area this span belongs to. Used by truncation to decide
   * which spans to drop first. Defaults to the recorder's `callerArea`,
   * or `core` if neither is set.
   */
  area?: ObservabilityAreaPrefix;
};

export type EndSpanInput = {
  status?: ObservabilitySpanStatus;
  output?: string;
  tokenUsage?: ObservabilityTokenUsage;
  metrics?: Record<string, number>;
  attributes?: Record<string, unknown>;
  error?: string;
};

export type ObservabilityTraceListener = (event: ObservabilityRuntimeEvent) => void;

const cloneTrace = (trace: ObservabilityTrace): ObservabilityTrace => ({
  ...trace,
  spans: trace.spans.map((span) => ({ ...span, metrics: { ...span.metrics }, attributes: { ...span.attributes } })),
  events: trace.events.map((event) => ({ ...event, attributes: { ...event.attributes } })),
  tokenUsage: { ...trace.tokenUsage },
  metrics: { ...trace.metrics },
  tags: [...trace.tags],
});

function defaultIdFactory(prefix: string): string {
  return `${prefix}_${randomUUID()}`;
}

export class ObservabilityTraceRecorder {
  private trace: ObservabilityTrace;
  private readonly idFactory: (prefix: string) => string;
  private readonly now: () => number;
  private readonly listeners = new Set<ObservabilityTraceListener>();
  private readonly callerArea?: ObservabilityAreaPrefix;
  private readonly truncationThreshold: number;
  /** Cumulative count of spans ever added (before truncation). */
  private totalSpansAdded = 0;

  constructor(input: StartTraceInput, options: ObservabilityTraceRecorderOptions = {}) {
    this.idFactory = options.idFactory ?? defaultIdFactory;
    this.now = options.now ?? Date.now;
    this.callerArea = options.callerArea;
    this.truncationThreshold = options.truncationThreshold ?? TRACE_SPAN_TRUNCATION_THRESHOLD;
    this.trace = {
      id: this.idFactory("trace"),
      name: input.name,
      runId: input.runId,
      sessionKey: input.sessionKey,
      task: input.task,
      mode: input.mode,
      status: "running",
      startedAt: this.now(),
      spans: [],
      events: [],
      tokenUsage: { ...EMPTY_OBSERVABILITY_TOKEN_USAGE },
      metrics: { ...input.metrics },
      tags: [...(input.tags ?? [])],
    };
  }

  subscribe(listener: ObservabilityTraceListener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  start(): ObservabilityTrace {
    this.emit({ type: "trace.started", trace: this.snapshot() });
    return this.snapshot();
  }

  snapshot(): ObservabilityTrace {
    return cloneTrace(this.trace);
  }

  startSpan(input: StartSpanInput): ObservabilitySpan {
    const span: ObservabilitySpan = {
      id: this.idFactory("span"),
      traceId: this.trace.id,
      parentSpanId: input.parentSpanId,
      name: input.name,
      kind: input.kind,
      roleName: input.roleName,
      modelRef: input.modelRef,
      status: "running",
      startedAt: this.now(),
      input: input.input,
      tokenUsage: input.tokenUsage,
      metrics: { ...input.metrics },
      attributes: { ...input.attributes, ...(input.area ? { __area: input.area } : {}) },
    };
    this.trace.spans.push(span);
    this.totalSpansAdded++;
    if (input.tokenUsage) {
      this.trace.tokenUsage = addObservabilityTokenUsage(this.trace.tokenUsage, input.tokenUsage);
    }
    this.emit({ type: "span.started", traceId: this.trace.id, span: { ...span } });
    // Stage 3 (criterion 3.13): truncate if over threshold.
    this.maybeTruncate();
    return { ...span };
  }

  endSpan(spanId: string, input: EndSpanInput = {}): ObservabilitySpan {
    const span = this.trace.spans.find((candidate) => candidate.id === spanId);
    if (!span) {
      throw new Error(`Unknown observability span: ${spanId}`);
    }
    const endedAt = this.now();
    span.status = input.status ?? (input.error ? "error" : "completed");
    span.endedAt = endedAt;
    span.durationMs = Math.max(0, endedAt - span.startedAt);
    span.output = input.output ?? span.output;
    span.error = input.error ?? span.error;
    span.metrics = { ...span.metrics, ...input.metrics };
    span.attributes = { ...span.attributes, ...input.attributes };
    if (input.tokenUsage) {
      span.tokenUsage = span.tokenUsage
        ? addObservabilityTokenUsage(span.tokenUsage, input.tokenUsage)
        : input.tokenUsage;
      this.trace.tokenUsage = addObservabilityTokenUsage(this.trace.tokenUsage, input.tokenUsage);
    }
    this.emit({ type: "span.completed", traceId: this.trace.id, span: { ...span } });
    this.emit({ type: "trace.updated", trace: this.snapshot() });
    return { ...span };
  }

  /**
   * Record a trace event.
   *
   * Stage 3 (criterion 3.10): when `callerArea` is set on the recorder, the
   * `type` parameter MUST be a fully-qualified event name
   * (`claw.{area}.{category}.{event}`). Out-of-namespace events are rejected:
   * they are not added to `trace.events`, and a `claw.core.trace.namespace_rejected`
   * diagnostic event is emitted in their place.
   *
   * @returns the recorded event, or the rejection diagnostic if rejected.
   */
  recordEvent(
    type: string,
    name: string,
    attrs?: { spanId?: string; attributes?: Record<string, unknown> },
  ): ObservabilityTraceEvent {
    // Stage 3 (criterion 3.10): namespace enforcement.
    if (this.callerArea) {
      const error = validateEventNamespace(type, this.callerArea);
      if (error) {
        const rejected: ObservabilityTraceEvent = {
          id: this.idFactory("event"),
          traceId: this.trace.id,
          spanId: attrs?.spanId,
          type: "claw.core.trace.namespace_rejected",
          name: "Namespace Rejected",
          timestamp: this.now(),
          attributes: {
            reason: error,
            rejectedType: type,
            rejectedName: name,
          },
        };
        this.trace.events.push(rejected);
        this.emit({ type: "event.recorded", traceId: this.trace.id, event: { ...rejected } });
        return { ...rejected };
      }
    }
    const event: ObservabilityTraceEvent = {
      id: this.idFactory("event"),
      traceId: this.trace.id,
      spanId: attrs?.spanId,
      type,
      name,
      timestamp: this.now(),
      attributes: { ...attrs?.attributes },
    };
    this.trace.events.push(event);
    this.emit({ type: "event.recorded", traceId: this.trace.id, event: { ...event } });
    return { ...event };
  }

  complete(status: Exclude<ObservabilityTraceStatus, "running"> = "completed", error?: string): ObservabilityTrace {
    const endedAt = this.now();
    this.trace.status = status;
    this.trace.endedAt = endedAt;
    this.trace.durationMs = Math.max(0, endedAt - this.trace.startedAt);
    this.trace.error = error;
    for (const span of this.trace.spans) {
      if (span.status === "running") {
        span.status = status;
        span.endedAt = endedAt;
        span.durationMs = Math.max(0, endedAt - span.startedAt);
        span.error = error ?? span.error;
      }
    }
    this.emit({ type: "trace.completed", trace: this.snapshot() });
    return this.snapshot();
  }

  async withSpan<T>(input: StartSpanInput, fn: (span: ObservabilitySpan) => Promise<T> | T): Promise<T> {
    const span = this.startSpan(input);
    try {
      const result = await fn(span);
      this.endSpan(span.id, { status: "completed" });
      return result;
    } catch (error) {
      this.endSpan(span.id, { status: "error", error: error instanceof Error ? error.message : String(error) });
      throw error;
    }
  }

  /**
   * Stage 3 (criterion 3.13): when the span count exceeds the truncation
   * threshold, drop the lowest-priority spans (highest `spanDropPriority`
   * value first: a4 > a3 > a5 > a2 > a1 > a6 > core) and emit a single
   * `claw.core.trace.truncated` event recording what was dropped.
   *
   * The truncation event is emitted once on first truncation, then its
   * cumulative attributes are updated on subsequent truncations (so the
   * final event reflects the total spans added/dropped across the trace).
   */
  private maybeTruncate(): void {
    if (this.trace.spans.length <= this.truncationThreshold) return;
    const dropped = this.dropExcessSpans();
    if (dropped.length === 0) return;

    // Find the existing truncation event (at most one per trace).
    let truncationEvent = this.trace.events.find(
      (e) => e.type === "claw.core.trace.truncated",
    );
    if (!truncationEvent) {
      truncationEvent = {
        id: this.idFactory("event"),
        traceId: this.trace.id,
        type: "claw.core.trace.truncated",
        name: "Trace Truncated",
        timestamp: this.now(),
        attributes: {
          originalSpanCount: this.totalSpansAdded,
          retainedSpanCount: this.trace.spans.length,
          droppedSpanCount: 0,
          droppedAreas: [] as string[],
          threshold: this.truncationThreshold,
        },
      };
      this.trace.events.push(truncationEvent);
      this.emit({ type: "event.recorded", traceId: this.trace.id, event: { ...truncationEvent } });
    }
    // Update cumulative stats (covers both first and subsequent truncations).
    const attrs = truncationEvent.attributes!;
    attrs.originalSpanCount = this.totalSpansAdded;
    attrs.retainedSpanCount = this.trace.spans.length;
    attrs.droppedSpanCount = (attrs.droppedSpanCount as number) + dropped.length;
    (attrs.droppedAreas as string[]).push(...dropped.map((d) => d.area));
  }

  private dropExcessSpans(): Array<{ id: string; area: string }> {
    const excess = this.trace.spans.length - this.truncationThreshold;
    if (excess <= 0) return [];
    // Sort spans by drop priority descending (a4=6 first to drop, core=0 last).
    const indexed = this.trace.spans.map((span, index) => ({
      index,
      area: this.extractArea(span),
      priority: spanDropPriority(this.extractArea(span)),
    }));
    // Stable sort: highest priority value dropped first; ties broken by
    // recency (later spans dropped first to preserve early history).
    indexed.sort((a, b) => {
      if (a.priority !== b.priority) return b.priority - a.priority;
      return b.index - a.index;
    });
    const droppedIndices = new Set(indexed.slice(0, excess).map((d) => d.index));
    const dropped: Array<{ id: string; area: string }> = [];
    const kept: ObservabilitySpan[] = [];
    for (let i = 0; i < this.trace.spans.length; i++) {
      if (droppedIndices.has(i)) {
        const span = this.trace.spans[i];
        dropped.push({ id: span.id, area: this.extractArea(span) });
      } else {
        kept.push(this.trace.spans[i]);
      }
    }
    this.trace.spans = kept;
    return dropped;
  }

  private extractArea(span: ObservabilitySpan): ObservabilityAreaPrefix {
    const fromAttr = span.attributes?.__area;
    if (
      typeof fromAttr === "string" &&
      (fromAttr === "a1" || fromAttr === "a2" || fromAttr === "a3" ||
        fromAttr === "a4" || fromAttr === "a5" || fromAttr === "a6" || fromAttr === "core")
    ) {
      return fromAttr;
    }
    return this.callerArea ?? "core";
  }

  private emit(event: ObservabilityRuntimeEvent): void {
    for (const listener of this.listeners) {
      listener(event);
    }
  }
}

export function createObservabilityTraceRecorder(
  input: StartTraceInput,
  options?: ObservabilityTraceRecorderOptions,
): ObservabilityTraceRecorder {
  return new ObservabilityTraceRecorder(input, options);
}

// ---------------------------------------------------------------------------
// Round 2 / Stage 3: Observability Event Namespace Governance
//
// Each area owns a namespace (`claw.{area}.`). Events outside an area's
// namespace are rejected at recording time. This prevents cross-area event
// pollution and makes traces human-readable.
//
// See: docs/runtime-design/development-manual.md §1.1, Stage 3 (criterion 3.10/3.13)
// Mirrors: shared/types/observability.ts (renderer-side copy)
// ---------------------------------------------------------------------------

/** The area prefix of the observability namespace. */
export type ObservabilityAreaPrefix = "a1" | "a2" | "a3" | "a4" | "a5" | "a6" | "core";

/** A fully-qualified event name in the `claw.{area}.{category}.{event}` format. */
export type ObservabilityEventName = `claw.${ObservabilityAreaPrefix}.${string}`;

/** Retention/decay policy for an event category. */
export type ObservabilityRetentionPolicy = {
  /** How long to retain spans of this category, in milliseconds. */
  retentionMs: number;
  /** Sampling rate when throughput exceeds `thresholdPerMinute`. */
  highThroughputSamplingRate: number;
  /** Spans per minute above which sampling kicks in. */
  thresholdPerMinute: number;
};

/** Default retention policies by event category. */
export const OBSERVABILITY_RETENTION_POLICIES = {
  decision: { retentionMs: 7 * 24 * 60 * 60 * 1000, highThroughputSamplingRate: 1.0, thresholdPerMinute: Infinity },
  diagnostic: { retentionMs: 3 * 24 * 60 * 60 * 1000, highThroughputSamplingRate: 0.1, thresholdPerMinute: 100 },
  error: { retentionMs: 30 * 24 * 60 * 60 * 1000, highThroughputSamplingRate: 1.0, thresholdPerMinute: Infinity },
  shadow: { retentionMs: 7 * 24 * 60 * 60 * 1000, highThroughputSamplingRate: 0.01, thresholdPerMinute: 50 },
} as const satisfies Record<string, ObservabilityRetentionPolicy>;

/** Trace truncation threshold. Above this, low-priority spans are dropped. */
export const TRACE_SPAN_TRUNCATION_THRESHOLD = 200;

/**
 * Validate that an event name is within the caller's area namespace.
 * Returns `null` if valid, or an error message.
 *
 * @param eventName fully-qualified event name like `claw.a1.tool.choice`
 * @param callerArea the area the recorder belongs to
 */
export function validateEventNamespace(
  eventName: string,
  callerArea: ObservabilityAreaPrefix,
): string | null {
  const prefix = `claw.${callerArea}.`;
  if (eventName.startsWith(prefix)) return null;
  // `core.` namespace is reserved for Mission Control and infrastructure diagnostics
  // (e.g. `claw.core.trace.truncated`, `claw.core.trace.namespace_rejected`).
  if (callerArea === "core" && eventName.startsWith("claw.core.")) return null;
  return `Event name "${eventName}" does not match caller area "${callerArea}" (expected prefix "claw.${callerArea}.")`;
}

/**
 * Determine the drop priority for a span during trace truncation.
 * Lower number = higher importance = kept longer.
 * Priority order (highest first): core > a6 > a1 > a2 > a5 > a3 > a4.
 * A4 spans are dropped first; A6 spans are dropped last (after core).
 */
export function spanDropPriority(area: ObservabilityAreaPrefix): number {
  const priority: Record<ObservabilityAreaPrefix, number> = {
    core: 0,
    a6: 1,
    a1: 2,
    a2: 3,
    a5: 4,
    a3: 5,
    a4: 6,
  };
  return priority[area];
}

