// ---------------------------------------------------------------------------
// Stage 3 (criterion 3.9): A5 Wave Immutability
//
// `ResourceAwareWaveScheduler` is a thin facade over `buildExecutionWaves` that
// enforces wave immutability: once a wave has been started, re-planning that
// wave (via `appliesToWave`) is ignored. This prevents A5 budget changes from
// disrupting in-flight execution waves.
//
// See: docs/runtime-design/development-manual.md §1.1, Stage 3
// See: docs/runtime-design/area-composition-spec.md (A5 wave immutability)
// ---------------------------------------------------------------------------

import {
  buildExecutionWaves,
  type OrchestrationExecutionWave,
  type OrchestrationTaskGraph,
} from "./orchestration-protocol.js";

export type WaveStatus = "planned" | "started" | "completed";

export type WavePlan = OrchestrationExecutionWave & {
  status: WaveStatus;
  maxWorkers: number;
};

export type RePlanRequest = {
  /** The wave the re-plan applies to. If the wave is already started, the
   * request is ignored (wave immutability). */
  appliesToWave: number;
  /** New worker cap for subsequent waves. */
  maxWorkers?: number;
  /** Revised task graph (optional). When omitted, only the worker cap changes. */
  graph?: OrchestrationTaskGraph;
};

export type RePlanResult =
  | { accepted: true; replannedWaves: number[] }
  | { accepted: false; reason: "wave_started" | "wave_not_found" | "no_change"; waveNumber: number };

/**
 * P2 fix: Default worker cap when none is specified. Previously this was
 * `Number.MAX_SAFE_INTEGER` (effectively unlimited), which provided no
 * real concurrency cap. 64 is a conservative default that still allows
 * high parallelism for large graphs while preventing pathological cases.
 */
const DEFAULT_MAX_WORKERS = 64;

/**
 * A5-aware wave scheduler. Wraps `buildExecutionWaves` and enforces that
 * started waves cannot be re-planned.
 *
 * Usage:
 *   const scheduler = new ResourceAwareWaveScheduler(graph, { maxWorkers: 4 });
 *   const waves = scheduler.plan();          // initial plan
 *   scheduler.startWave(1);                  // mark wave 1 as started
 *   scheduler.rePlan({ appliesToWave: 1 });   // ignored — wave 1 is started
 *   scheduler.rePlan({ appliesToWave: 2, maxWorkers: 2 }); // accepted
 */
export class ResourceAwareWaveScheduler {
  private readonly waves = new Map<number, WavePlan>();
  private currentGraph: OrchestrationTaskGraph;
  private currentMaxWorkers: number;

  constructor(graph: OrchestrationTaskGraph, options: { maxWorkers?: number } = {}) {
    this.currentGraph = graph;
    // P2 fix: use a sane default cap instead of MAX_SAFE_INTEGER.
    this.currentMaxWorkers = options.maxWorkers ?? DEFAULT_MAX_WORKERS;
  }

  /** Compute the initial wave plan. Returns the waves in execution order. */
  plan(): WavePlan[] {
    const raw = buildExecutionWaves(this.currentGraph, this.currentMaxWorkers);
    this.waves.clear();
    for (const wave of raw) {
      this.waves.set(wave.wave, {
        ...wave,
        status: "planned",
        maxWorkers: this.currentMaxWorkers,
      });
    }
    return this.getWaves();
  }

  /** Mark a wave as started. Once started, the wave cannot be re-planned. */
  startWave(waveNumber: number): void {
    const wave = this.waves.get(waveNumber);
    if (!wave) {
      throw new Error(`Cannot start unknown wave: ${waveNumber}`);
    }
    wave.status = "started";
  }

  /** Mark a wave as completed. */
  completeWave(waveNumber: number): void {
    const wave = this.waves.get(waveNumber);
    if (!wave) {
      throw new Error(`Cannot complete unknown wave: ${waveNumber}`);
    }
    wave.status = "completed";
  }

  /**
   * Attempt to re-plan waves. If `appliesToWave` refers to a wave that is
   * already started or completed, the request is rejected (wave immutability).
   * Only waves still in "planned" status can be re-planned.
   *
   * When accepted, all waves from `appliesToWave` onward are re-computed
   * using the new graph/worker cap.
   */
  rePlan(request: RePlanRequest): RePlanResult {
    const target = this.waves.get(request.appliesToWave);
    if (!target) {
      return { accepted: false, reason: "wave_not_found", waveNumber: request.appliesToWave };
    }
    if (target.status === "started" || target.status === "completed") {
      return { accepted: false, reason: "wave_started", waveNumber: request.appliesToWave };
    }
    const newMaxWorkers = request.maxWorkers ?? this.currentMaxWorkers;
    const newGraph = request.graph ?? this.currentGraph;
    if (newMaxWorkers === this.currentMaxWorkers && newGraph === this.currentGraph) {
      return { accepted: false, reason: "no_change", waveNumber: request.appliesToWave };
    }
    // Re-compute waves from the target onward.
    this.currentGraph = newGraph;
    this.currentMaxWorkers = newMaxWorkers;
    const allWaves = buildExecutionWaves(newGraph, newMaxWorkers);
    const replanned: number[] = [];
    for (const wave of allWaves) {
      if (wave.wave < request.appliesToWave) continue;
      const existing = this.waves.get(wave.wave);
      // Only update waves that are still planned.
      if (existing && existing.status !== "planned") continue;
      this.waves.set(wave.wave, {
        ...wave,
        status: "planned",
        maxWorkers: newMaxWorkers,
      });
      replanned.push(wave.wave);
    }
    return { accepted: true, replannedWaves: replanned };
  }

  /** Get the current wave plan (snapshot). */
  getWaves(): WavePlan[] {
    return [...this.waves.values()].sort((a, b) => a.wave - b.wave);
  }

  /** Get a specific wave by number. */
  getWave(waveNumber: number): WavePlan | undefined {
    return this.waves.get(waveNumber);
  }

  /** Get the status of a specific wave. */
  getWaveStatus(waveNumber: number): WaveStatus | undefined {
    return this.waves.get(waveNumber)?.status;
  }
}

// ---------------------------------------------------------------------------
// Stage 4 (criteria 4.1-4.4): Per-Area Deprecation Telemetry
//
// Each of the 6 areas (A1-A6) has graduation criteria that, when consistently
// met, allow the area's shadow path to be promoted and the legacy fallback to
// be deprecated. This module exposes telemetry counters that record the
// signals used to make that graduation decision.
//
// All counters are in-memory only (shadow instrumentation) — they do NOT
// touch production state. They are read via `snapshot()` for the Workbench
// and audit reports.
//
// See: docs/runtime-design/development-manual.md §1.1, Stage 4
// ---------------------------------------------------------------------------

/** Lowercase area identifier used by deprecation counters. Includes A3/A4
 * which are not shadow areas but still have graduation telemetry. */
export type DeprecationArea = "a1" | "a2" | "a3" | "a4" | "a5" | "a6";

// ---------------------------------------------------------------------------
// Counter types
// ---------------------------------------------------------------------------

/** A1 deprecation: legacy fallback invocation count. */
export type A1DeprecationCounters = {
  /** Number of times the legacy `IsolationFailureRecovery` fallback ran. */
  legacyFallbackCount: number;
  /** Number of turns where the shadow isolation path succeeded (no fallback). */
  shadowSuccessCount: number;
  /** Number of times a declared-path violation was detected. */
  declaredPathViolationCount: number;
};

/** A2 deprecation: wave deferral consistency. */
export type A2DeprecationCounters = {
  /** Number of times the live scheduler agreed with the shadow prediction. */
  deferralAgreementCount: number;
  /** Number of times they disagreed (shadow predicted X, scheduler did Y). */
  deferralDisagreementCount: number;
  /** Number of waves that were deferred (re-planned to a later wave). */
  deferredWaveCount: number;
};

/** A3 deprecation: anomaly classifier + Mission outcome. */
export type A3DeprecationCounters = {
  /** Number of Mission ticks where `anomalyPattern` was non-null. */
  anomalyNonNullCount: number;
  /** Total Mission ticks observed. */
  totalMissionTicks: number;
  /** Number of Mission outcomes (continue/repair/sleep/ask_user/complete/blocked). */
  missionOutcomeCount: number;
};

/** A4 deprecation: decision quality (placeholder — A4 is decision-quality audits). */
export type A4DeprecationCounters = {
  /** Number of decisions audited. */
  auditedDecisions: number;
  /** Number of decisions flagged as low-quality. */
  lowQualityDecisions: number;
};

/** A5 deprecation: budget plan adoption. */
export type A5DeprecationCounters = {
  /** Number of turns where the compression planner adopted the A5 plan. */
  planAdoptedCount: number;
  /** Number of turns where the compression planner ignored the A5 plan. */
  planIgnoredCount: number;
  /** Number of turns where the budget was exceeded. */
  budgetExceededCount: number;
};

/** A6 deprecation: ResumeContractVerifier pass rate + volatile mislabel. */
export type A6DeprecationCounters = {
  /** Number of resume contract verifications that passed. */
  verifierPassCount: number;
  /** Number of resume contract verifications that failed. */
  verifierFailCount: number;
  /**
   * CRITICAL: Number of times a volatile checkpoint was mislabeled as
   * guaranteed. This is a critical counter — any non-zero value blocks
   * A6 graduation.
   */
  volatileMislabelCount: number;
};

// ---------------------------------------------------------------------------
// Registry
// ---------------------------------------------------------------------------

export type DeprecationCounters = {
  a1: A1DeprecationCounters;
  a2: A2DeprecationCounters;
  a3: A3DeprecationCounters;
  a4: A4DeprecationCounters;
  a5: A5DeprecationCounters;
  a6: A6DeprecationCounters;
};

const ZERO: DeprecationCounters = {
  a1: { legacyFallbackCount: 0, shadowSuccessCount: 0, declaredPathViolationCount: 0 },
  a2: { deferralAgreementCount: 0, deferralDisagreementCount: 0, deferredWaveCount: 0 },
  a3: { anomalyNonNullCount: 0, totalMissionTicks: 0, missionOutcomeCount: 0 },
  a4: { auditedDecisions: 0, lowQualityDecisions: 0 },
  a5: { planAdoptedCount: 0, planIgnoredCount: 0, budgetExceededCount: 0 },
  a6: { verifierPassCount: 0, verifierFailCount: 0, volatileMislabelCount: 0 },
};

/**
 * In-memory deprecation counter registry. One instance per process.
 * Counters are monotonically increasing (only `increment` mutates).
 *
 * Usage:
 *   import { deprecationCounters } from "./deprecation-counters.js";
 *   deprecationCounters.a1.incrementLegacyFallback();
 *   const snap = deprecationCounters.snapshot();
 */
class DeprecationCounterRegistry {
  private counters: DeprecationCounters = JSON.parse(JSON.stringify(ZERO));

  // --- A1 ---
  incrementA1LegacyFallback(delta = 1): void {
    this.counters.a1.legacyFallbackCount += delta;
  }
  incrementA1ShadowSuccess(delta = 1): void {
    this.counters.a1.shadowSuccessCount += delta;
  }
  incrementA1DeclaredPathViolation(delta = 1): void {
    this.counters.a1.declaredPathViolationCount += delta;
  }

  // --- A2 ---
  incrementA2DeferralAgreement(delta = 1): void {
    this.counters.a2.deferralAgreementCount += delta;
  }
  incrementA2DeferralDisagreement(delta = 1): void {
    this.counters.a2.deferralDisagreementCount += delta;
  }
  incrementA2DeferredWave(delta = 1): void {
    this.counters.a2.deferredWaveCount += delta;
  }

  // --- A3 ---
  incrementA3AnomalyNonNull(delta = 1): void {
    this.counters.a3.anomalyNonNullCount += delta;
  }
  incrementA3MissionTicks(delta = 1): void {
    this.counters.a3.totalMissionTicks += delta;
  }
  incrementA3MissionOutcome(delta = 1): void {
    this.counters.a3.missionOutcomeCount += delta;
  }

  // --- A4 ---
  incrementA4AuditedDecisions(delta = 1): void {
    this.counters.a4.auditedDecisions += delta;
  }
  incrementA4LowQualityDecisions(delta = 1): void {
    this.counters.a4.lowQualityDecisions += delta;
  }

  // --- A5 ---
  incrementA5PlanAdopted(delta = 1): void {
    this.counters.a5.planAdoptedCount += delta;
  }
  incrementA5PlanIgnored(delta = 1): void {
    this.counters.a5.planIgnoredCount += delta;
  }
  incrementA5BudgetExceeded(delta = 1): void {
    this.counters.a5.budgetExceededCount += delta;
  }

  // --- A6 ---
  incrementA6VerifierPass(delta = 1): void {
    this.counters.a6.verifierPassCount += delta;
  }
  incrementA6VerifierFail(delta = 1): void {
    this.counters.a6.verifierFailCount += delta;
  }
  /**
   * Record a volatile-as-guaranteed mislabel. This is the critical A6
   * graduation gate — any non-zero value blocks graduation.
   */
  incrementA6VolatileMislabel(delta = 1): void {
    this.counters.a6.volatileMislabelCount += delta;
  }

  // --- Read access ---

  /** Get a deep-copy snapshot of all counters. */
  snapshot(): DeprecationCounters {
    return JSON.parse(JSON.stringify(this.counters));
  }

  /** Get a specific area's counters (deep copy). */
  getArea(area: DeprecationArea): A1DeprecationCounters | A2DeprecationCounters | A3DeprecationCounters | A4DeprecationCounters | A5DeprecationCounters | A6DeprecationCounters {
    const snap = this.snapshot();
    switch (area) {
      case "a1": return snap.a1;
      case "a2": return snap.a2;
      case "a3": return snap.a3;
      case "a4": return snap.a4;
      case "a5": return snap.a5;
      case "a6": return snap.a6;
      default: {
        const _exhaustive: never = area;
        return _exhaustive;
      }
    }
  }

  /** Reset all counters to zero (for tests). */
  reset(): void {
    this.counters = JSON.parse(JSON.stringify(ZERO));
  }

  /**
   * Stage 4 (criterion 4.14): check whether an area has exceeded its budget.
   * Returns a degradation recommendation when exceeded.
   */
  checkBudgetViolation(area: DeprecationArea): BudgetViolationResult {
    const c = this.getArea(area);
    switch (area) {
      case "a1": {
        const a1 = c as A1DeprecationCounters;
        // A1 budget: legacy fallback rate must not exceed 5% of total turns.
        // Boundary convention (consistent with A2-A6): rate == 5.000% is
        // ALLOWED (uses strict `>`); rate > 5% triggers violation. This
        // avoids false-positive degradation at the exact boundary.
        // P2-5 note: when `total === 0` (no telemetry collected yet), we
        // intentionally return `violated: false` — degrading without data
        // would be unsafe. "No data" is NOT "good data", but it is also
        // not evidence of a problem; operators should check `total` via
        // `snapshot()` separately when diagnosing.
        const total = a1.legacyFallbackCount + a1.shadowSuccessCount;
        if (total > 0 && a1.legacyFallbackCount / total > 0.05) {
          return { area, violated: true, degrade: "a1_legacy_fallback_rate", action: "degrade_to_legacy" };
        }
        return { area, violated: false };
      }
      case "a2": {
        const a2 = c as A2DeprecationCounters;
        const total = a2.deferralAgreementCount + a2.deferralDisagreementCount;
        if (total > 0 && a2.deferralDisagreementCount / total > 0.10) {
          return { area, violated: true, degrade: "a2_deferral_disagreement_rate", action: "degrade_to_live_only" };
        }
        return { area, violated: false };
      }
      case "a3": {
        const a3 = c as A3DeprecationCounters;
        if (a3.totalMissionTicks > 0 && a3.anomalyNonNullCount / a3.totalMissionTicks > 0.20) {
          return { area, violated: true, degrade: "a3_anomaly_rate", action: "degrade_to_default_decision" };
        }
        return { area, violated: false };
      }
      case "a4": {
        const a4 = c as A4DeprecationCounters;
        if (a4.auditedDecisions > 0 && a4.lowQualityDecisions / a4.auditedDecisions > 0.10) {
          return { area, violated: true, degrade: "a4_low_quality_rate", action: "degrade_to_audit_only" };
        }
        return { area, violated: false };
      }
      case "a5": {
        const a5 = c as A5DeprecationCounters;
        const total = a5.planAdoptedCount + a5.planIgnoredCount;
        if (total > 0 && a5.planIgnoredCount / total > 0.20) {
          return { area, violated: true, degrade: "a5_plan_adoption_rate", action: "degrade_to_default_budget" };
        }
        return { area, violated: false };
      }
      case "a6": {
        const a6 = c as A6DeprecationCounters;
        // A6 has a hard gate: any volatile mislabel is a critical violation.
        if (a6.volatileMislabelCount > 0) {
          return { area, violated: true, degrade: "a6_volatile_mislabel", action: "degrade_to_full_reverification" };
        }
        const total = a6.verifierPassCount + a6.verifierFailCount;
        if (total > 0 && a6.verifierFailCount / total > 0.05) {
          return { area, violated: true, degrade: "a6_verifier_fail_rate", action: "degrade_to_full_reverification" };
        }
        return { area, violated: false };
      }
      default: {
        const _exhaustive: never = area;
        return { area: _exhaustive, violated: false };
      }
    }
  }
}

export type BudgetViolationResult =
  | { area: DeprecationArea; violated: false }
  | {
      area: DeprecationArea;
      violated: true;
      degrade: string;
      action: "degrade_to_legacy" | "degrade_to_live_only" | "degrade_to_default_decision" | "degrade_to_audit_only" | "degrade_to_default_budget" | "degrade_to_full_reverification";
    };

/** Singleton instance. */
export const deprecationCounters = new DeprecationCounterRegistry();

import type { AgentMessage } from "../../types.js";
import type { CompactionSettings } from "./compaction.js";
import type { CompressionSemanticAtom } from "./compression-artifact.js";

export type CompressionTier = "tier0" | "tier1" | "tier2" | "tier3" | "tier4";

export type CompressionStrategy =
  | "hot-context"
  | "micro-compact"
  | "token-pruning"
  | "semantic-handoff"
  | "emergency-collapse";

export type CompressionPlan = {
  tier: CompressionTier;
  strategy: CompressionStrategy;
  pressure: number;
};

/** Optional per-task-class thresholds. P5 only allows earlier (lower) values. */
export type TierThresholds = {
  tier1?: number;
  tier2?: number;
  tier3?: number;
  tier4?: number;
};

export type TierSchedule = {
  taskClass?: string;
  thresholds: TierThresholds;
  budgetTokens?: number;
  reason?: string;
};

/** The production reactive ladder; unchanged absent overrides. */
export const DEFAULT_TIER_THRESHOLDS = {
  tier1: 0.6,
  tier2: 0.75,
  tier3: 0.85,
  tier4: 0.95,
} as const;

export type ResolvedTierThresholds = {
  tier1: number;
  tier2: number;
  tier3: number;
  tier4: number;
};

export type CompressionTelemetry = {
  tier: CompressionTier;
  strategy: CompressionStrategy;
  pressure: number;
  tokensBefore: number;
  tokensAfter?: number;
  compressionRatio?: number;
  warnings: string[];
  staleExcludedCount: number;
  causalAnchorCount: number;
  rehydratedFiles: string[];
  /** Optional P5 shadow metadata; absent unless a tierSchedule was supplied. */
  taskClass?: string;
  budgetTokens?: number;
};

export type TokenPruningAdapter = (input: {
  text: string;
  targetRatio: number;
  causalAnchors: readonly string[];
}) => { text: string; causalAnchorCount: number; warnings?: string[] };

export type CompressionPlannerInput = {
  tokensBefore: number;
  settings: CompactionSettings;
  messages: AgentMessage[];
  staleExcludedCount?: number;
  readFiles?: string[];
  modifiedFiles?: string[];
  tokenPruningAdapter?: TokenPruningAdapter;
  /** P5 optional task-class schedule. It only changes plan.tier. */
  tierSchedule?: TierSchedule;
};

export type CompressionPlannerResult = {
  plan: CompressionPlan;
  messages: AgentMessage[];
  telemetry: CompressionTelemetry;
};

const CAUSAL_ANCHORS = [
  "because",
  "since",
  "due to",
  "caused by",
  "so that",
  "failed",
  "error",
  "broke",
  "regression",
  "bug",
  "decided",
  "switched",
  "chose",
  "instead",
  "constraint",
  "blocked",
  "however",
  "although",
  "rather",
  "因为",
  "由于",
  "导致",
  "所以",
  "失败",
  "错误",
  "回归",
  "决定",
  "切换",
  "选择",
  "约束",
  "但是",
  "然而",
  "不过",
  "反而",
] as const;

function round(value: number): number {
  return Math.round(value * 10000) / 10000;
}

function thresholdValue(value: unknown, fallback: number): number {
  return typeof value === "number" && Number.isFinite(value) ? value : fallback;
}

/**
 * Resolve P5 thresholds. Every user threshold is clamped into
 * [0, DEFAULT_TIER_THRESHOLDS.x], so the production ladder can only be made
 * earlier, never later. Non-monotonic schedules fall back to production
 * defaults (the safe hard backstop).
 */
export function resolveTierThresholds(input?: TierThresholds): ResolvedTierThresholds {
  const tier1 = Math.max(
    0,
    Math.min(
      thresholdValue(input?.tier1, DEFAULT_TIER_THRESHOLDS.tier1),
      DEFAULT_TIER_THRESHOLDS.tier1,
    ),
  );
  const tier2 = Math.max(
    0,
    Math.min(
      thresholdValue(input?.tier2, DEFAULT_TIER_THRESHOLDS.tier2),
      DEFAULT_TIER_THRESHOLDS.tier2,
    ),
  );
  const tier3 = Math.max(
    0,
    Math.min(
      thresholdValue(input?.tier3, DEFAULT_TIER_THRESHOLDS.tier3),
      DEFAULT_TIER_THRESHOLDS.tier3,
    ),
  );
  const tier4 = Math.max(
    0,
    Math.min(
      thresholdValue(input?.tier4, DEFAULT_TIER_THRESHOLDS.tier4),
      DEFAULT_TIER_THRESHOLDS.tier4,
    ),
  );
  if (!(tier1 < tier2 && tier2 < tier3 && tier3 < tier4)) {
    return { ...DEFAULT_TIER_THRESHOLDS };
  }
  return { tier1, tier2, tier3, tier4 };
}

export function selectCompressionPlan(input: {
  tokensBefore: number;
  settings: CompactionSettings;
  contextWindow?: number;
  thresholds?: TierThresholds;
}): CompressionPlan {
  const budget = Math.max(
    1,
    input.contextWindow ??
      input.settings.contextWindow ??
      input.settings.reserveTokens + input.settings.keepRecentTokens,
  );
  const pressure = Math.max(0, input.tokensBefore / budget);
  const thresholds = resolveTierThresholds(input.thresholds);
  if (pressure < thresholds.tier1) return { tier: "tier0", strategy: "hot-context", pressure: round(pressure) };
  if (pressure < thresholds.tier2) return { tier: "tier1", strategy: "micro-compact", pressure: round(pressure) };
  if (pressure < thresholds.tier3) return { tier: "tier2", strategy: "token-pruning", pressure: round(pressure) };
  if (pressure < thresholds.tier4) return { tier: "tier3", strategy: "semantic-handoff", pressure: round(pressure) };
  return { tier: "tier4", strategy: "emergency-collapse", pressure: round(pressure) };
}

export type CriticalFirstBudgetField =
  | "criticalLedger"
  | "latestUserAsk"
  | "unfinishedActions"
  | "failureChainValidation"
  | "exactIdentifiers"
  | "importantFacts"
  | "niceToHaveProse";

export type CriticalFirstBudgetInput = {
  criticalLedger?: CompressionSemanticAtom[];
  latestUserAsk?: string;
  unfinishedActions?: string[];
  failureChainValidation?: string[];
  exactIdentifiers?: string[];
  importantFacts?: string[];
  niceToHaveProse?: string[];
  budgetTokens: number;
};

export type CriticalFirstBudgetPlan = {
  allowedTokens: Partial<Record<CriticalFirstBudgetField, number>>;
  order: CriticalFirstBudgetField[];
  truncated: CriticalFirstBudgetField[];
};

export const CRITICAL_FIRST_BUDGET_ORDER: CriticalFirstBudgetField[] = [
  "criticalLedger",
  "latestUserAsk",
  "unfinishedActions",
  "failureChainValidation",
  "exactIdentifiers",
  "importantFacts",
  "niceToHaveProse",
];

function estimateTextTokens(text: string): number {
  return Math.ceil(text.length / 4);
}

function estimateStringListTokens(items: string[] | undefined): number {
  if (!items) return 0;
  return items.reduce((total, item) => total + estimateTextTokens(item), 0);
}

function estimateCriticalLedgerTokens(atoms: CompressionSemanticAtom[] | undefined): number {
  if (!atoms) return 0;
  return atoms.reduce((total, item) => total + estimateTextTokens(item.text), 0);
}

/**
 * P5 deterministic shadow budget. The order is fixed and the function only
 * estimates tokens (chars/4, matching estimateTokens) and marks bounded
 * truncation. It never calls a model and never changes summary/artifact paths.
 */
export function planCriticalFirstBudget(input: CriticalFirstBudgetInput): CriticalFirstBudgetPlan {
  const remainingBudget =
    typeof input.budgetTokens === "number" && Number.isFinite(input.budgetTokens)
      ? Math.max(0, input.budgetTokens)
      : 0;
  const estimates: Record<CriticalFirstBudgetField, number> = {
    criticalLedger: estimateCriticalLedgerTokens(input.criticalLedger),
    latestUserAsk: estimateTextTokens(input.latestUserAsk ?? ""),
    unfinishedActions: estimateStringListTokens(input.unfinishedActions),
    failureChainValidation: estimateStringListTokens(input.failureChainValidation),
    exactIdentifiers: estimateStringListTokens(input.exactIdentifiers),
    importantFacts: estimateStringListTokens(input.importantFacts),
    niceToHaveProse: estimateStringListTokens(input.niceToHaveProse),
  };
  const order = [...CRITICAL_FIRST_BUDGET_ORDER];
  const allowedTokens: CriticalFirstBudgetPlan["allowedTokens"] = {};
  const truncated: CriticalFirstBudgetField[] = [];
  let remaining = remainingBudget;
  for (const field of order) {
    const estimated = estimates[field];
    const supplied =
      field === "criticalLedger"
        ? input.criticalLedger !== undefined
        : field === "latestUserAsk"
          ? input.latestUserAsk !== undefined
          : input[field] !== undefined;
    const allowed = Math.min(remaining, estimated);
    if (supplied) allowedTokens[field] = allowed;
    remaining -= allowed;
    if (supplied && allowed < estimated) truncated.push(field);
  }
  return { allowedTokens, order, truncated };
}

function textFromContent(content: unknown): string {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";
  return content
    .flatMap((block) => {
      if (!block || typeof block !== "object") return [];
      const record = block as Record<string, unknown>;
      if (typeof record.text === "string") return [record.text];
      if (typeof record.content === "string") return [record.content];
      return [];
    })
    .join("\n");
}

function textFromMessage(message: AgentMessage): string {
  const record = message as unknown as Record<string, unknown>;
  if (record.role === "bashExecution") {
    const command = typeof record.command === "string" ? record.command : "";
    const output = typeof record.output === "string" ? record.output : "";
    const exitCode = typeof record.exitCode === "number" ? `exit code: ${record.exitCode}` : "";
    return [command ? `$ ${command}` : "", exitCode, output].filter(Boolean).join("\n");
  }
  return textFromContent(record.content);
}

function replaceMessageText(message: AgentMessage, text: string): AgentMessage {
  const record = message as unknown as Record<string, unknown>;
  if (record.role === "bashExecution" && typeof record.output === "string") {
    return { ...(message as object), output: text } as AgentMessage;
  }
  if (typeof record.content === "string") {
    return { ...(message as object), content: text } as AgentMessage;
  }
  if (Array.isArray(record.content)) {
    let replaced = false;
    const content = record.content.map((block) => {
      if (!block || typeof block !== "object") return block;
      const blockRecord = block as Record<string, unknown>;
      if (!replaced && typeof blockRecord.text === "string") {
        replaced = true;
        return { ...blockRecord, text };
      }
      return block;
    });
    return { ...(message as object), content } as AgentMessage;
  }
  return message;
}

function compactLines(text: string, head = 24, tail = 24, label = "micro-compacted"): string {
  const lines = text.split(/\r?\n/);
  if (lines.length <= head + tail + 4) return text;
  return [
    ...lines.slice(0, head),
    `[... ${lines.length - head - tail} lines ${label} ...]`,
    ...lines.slice(-tail),
  ].join("\n");
}

function compactStackFrames(text: string): string {
  const lines = text.split(/\r?\n/);
  let omitted = 0;
  const kept: string[] = [];
  let stackRun = 0;
  for (const line of lines) {
    const isFrame = /^\s*at\s+|\s+File ".*", line \d+/u.test(line);
    if (isFrame) {
      stackRun += 1;
      if (stackRun > 4 && stackRun < lines.length - 2) {
        omitted += 1;
        continue;
      }
    } else {
      stackRun = 0;
    }
    kept.push(line);
  }
  return omitted > 0 ? `${kept.join("\n")}\n[... ${omitted} repeated stack frames omitted ...]` : text;
}

function compactToolOutput(text: string): string {
  const lines = text.split(/\r?\n/);
  if (lines.length <= 56) return text;
  const commandLine = lines.find((line) => /^\s*(?:[$>]|command:)/iu.test(line));
  const exitLine = lines.find((line) => /\b(?:exit code|exitCode|status)\b\s*[:=]\s*-?\d+/iu.test(line));
  const errorLines = lines
    .filter((line) => /\b(error|failed|exception|denied|enoent|traceback|fatal)\b/iu.test(line))
    .slice(0, 8);
  return [
    commandLine ? `command: ${commandLine.replace(/^\s*(?:[$>]\s*)?/u, "").trim()}` : "",
    exitLine ? `exit: ${exitLine.trim()}` : "",
    errorLines.length ? `error summary:\n${errorLines.map((line) => `- ${line.trim()}`).join("\n")}` : "",
    "head:",
    ...lines.slice(0, 18),
    `[... ${Math.max(0, lines.length - 36)} tool output lines micro-compacted ...]`,
    "tail:",
    ...lines.slice(-18),
  ].filter(Boolean).join("\n");
}

function compactFileBody(text: string): string {
  const lines = text.split(/\r?\n/);
  if (lines.length <= 64) return text;
  const selected = new Map<number, string>();
  const keepWindow = (index: number, radius: number) => {
    for (let i = Math.max(0, index - radius); i <= Math.min(lines.length - 1, index + radius); i++) {
      selected.set(i, lines[i]);
    }
  };
  lines.forEach((line, index) => {
    if (/^@@\s/u.test(line)) keepWindow(index, 4);
    if (/\b(?:[A-Za-z]:)?[./\\\w -]+\.(?:ts|tsx|js|jsx|mjs|cjs|json|md|py|rs|go|java|css|scss|html)\b/u.test(line)) {
      keepWindow(index, 1);
    }
    if (/^\s*(?:(?:export\s+)?(?:async\s+)?(?:function|class|interface|type)\s+\w+|export\s+const\s+\w+)/u.test(line)) {
      keepWindow(index, 1);
    }
    if (/\b(?:TODO|FIXME|failed|error|regression|because|decision|constraint)\b/iu.test(line)) {
      keepWindow(index, 2);
    }
  });
  for (let i = 0; i < Math.min(10, lines.length); i++) selected.set(i, lines[i]);
  for (let i = Math.max(0, lines.length - 10); i < lines.length; i++) selected.set(i, lines[i]);
  const ordered = [...selected.entries()].sort((a, b) => a[0] - b[0]);
  const output: string[] = [];
  let previous = -1;
  for (const [index, line] of ordered) {
    if (previous >= 0 && index > previous + 1) {
      output.push(`[... ${index - previous - 1} file body lines omitted ...]`);
    }
    output.push(line);
    previous = index;
  }
  return output.join("\n");
}

function looksLikeStackTrace(text: string): boolean {
  return /(?:\bTraceback \(most recent call last\):|\n\s*at\s+\S+|Exception\b|Error:)/u.test(text);
}

function looksLikeToolOutput(text: string): boolean {
  return /^\s*(?:[$>]|command:)/imu.test(text) || /\b(?:exit code|exitCode|status)\b\s*[:=]\s*-?\d+/iu.test(text);
}

function looksLikeFileBody(text: string): boolean {
  const lines = text.split(/\r?\n/);
  if (lines.length < 64) return false;
  const codeLike = lines.filter((line) => (
    /^\s*(?:import|export|function|class|interface|type)\b/u.test(line)
    || /^\s*[{}()[\],;]+$/u.test(line)
    || /^@@\s/u.test(line)
  )).length;
  return codeLike >= 8 || /\b(?:Get-Content|cat|sed -n|src\/|src\\|tests\/|tests\\)\b/iu.test(text);
}

export function microCompactText(text: string): string {
  if (looksLikeStackTrace(text)) {
    return compactLines(compactStackFrames(text), 18, 18, "stack trace micro-compacted");
  }
  if (looksLikeToolOutput(text)) {
    return compactToolOutput(text);
  }
  if (looksLikeFileBody(text)) {
    return compactFileBody(text);
  }
  return compactLines(text);
}

function anchorPositions(words: string[], anchors: readonly string[]): number[] {
  const lowerAnchors = anchors.map((item) => item.toLowerCase());
  const positions: number[] = [];
  for (let i = 0; i < words.length; i++) {
    const lower = words[i].toLowerCase();
    if (lowerAnchors.some((anchor) => lower.includes(anchor))) {
      positions.push(i);
    }
  }
  return positions;
}

export function defaultTokenPruningAdapter(input: {
  text: string;
  targetRatio: number;
  causalAnchors: readonly string[];
}): { text: string; causalAnchorCount: number; warnings?: string[] } {
  const words = input.text.match(/\S+/gu) ?? [];
  if (words.length <= 80) return { text: input.text, causalAnchorCount: 0 };
  const target = Math.max(40, Math.floor(words.length * input.targetRatio));
  const keep = new Set<number>();
  const head = Math.min(48, Math.floor(target * 0.3));
  const tail = Math.min(48, Math.floor(target * 0.25));
  for (let i = 0; i < head; i++) keep.add(i);
  for (let i = Math.max(0, words.length - tail); i < words.length; i++) keep.add(i);

  const anchors = anchorPositions(words, input.causalAnchors);
  for (const pos of anchors) {
    for (let i = Math.max(0, pos - 5); i <= Math.min(words.length - 1, pos + 5); i++) {
      keep.add(i);
    }
  }

  for (let i = head; i < words.length - tail && keep.size < target; i += 3) {
    keep.add(i);
  }

  const sorted = [...keep].sort((a, b) => a - b);
  const output: string[] = [];
  let previous = -1;
  for (const index of sorted) {
    if (previous >= 0 && index > previous + 1) {
      output.push(`[... ${index - previous - 1} tokens pruned ...]`);
    }
    output.push(words[index]);
    previous = index;
  }
  return {
    text: output.join(" "),
    causalAnchorCount: anchors.length,
    warnings: anchors.length === 0 ? ["no_causal_anchors_found"] : undefined,
  };
}

function pruneMessageText(
  text: string,
  adapter: TokenPruningAdapter,
): { text: string; causalAnchorCount: number; warnings: string[] } {
  const result = adapter({ text, targetRatio: 0.45, causalAnchors: CAUSAL_ANCHORS });
  return {
    text: result.text,
    causalAnchorCount: result.causalAnchorCount,
    warnings: result.warnings ?? [],
  };
}

function uniqueFiles(readFiles: string[], modifiedFiles: string[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const file of [...modifiedFiles, ...readFiles]) {
    const normalized = file.trim();
    if (!normalized || seen.has(normalized)) continue;
    seen.add(normalized);
    out.push(normalized);
    if (out.length >= 5) break;
  }
  return out;
}

function emergencyCollapseMessages(messages: AgentMessage[]): AgentMessage[] {
  if (messages.length <= 4) return messages;
  const retained = new Map<number, AgentMessage>();
  const firstObjectiveIndex = messages.findIndex((message) => {
    const role = (message as { role?: unknown }).role;
    return role === "user" && textFromMessage(message).trim().length > 0;
  });
  if (firstObjectiveIndex >= 0) retained.set(firstObjectiveIndex, messages[firstObjectiveIndex]);

  for (let i = messages.length - 1; i >= 0; i--) {
    const text = textFromMessage(messages[i]);
    if (/\b(?:next action|next step|todo|continue|constraint|blocked)\b|下一步|继续|约束|阻塞/iu.test(text)) {
      retained.set(i, messages[i]);
      break;
    }
  }

  for (let i = Math.max(0, messages.length - 4); i < messages.length; i++) {
    retained.set(i, messages[i]);
  }
  return [...retained.entries()].sort((a, b) => a[0] - b[0]).map(([, message]) => message);
}

export function planCompression(input: CompressionPlannerInput): CompressionPlannerResult {
  const plan = selectCompressionPlan({
    tokensBefore: input.tokensBefore,
    settings: input.settings,
    ...(input.tierSchedule ? { thresholds: input.tierSchedule.thresholds } : {}),
  });
  const warnings: string[] = [];
  let causalAnchorCount = 0;
  let messages = input.messages;

  if (plan.tier === "tier1" || plan.tier === "tier2" || plan.tier === "tier3" || plan.tier === "tier4") {
    messages = messages.map((message) => {
      const text = textFromMessage(message);
      if (!text || text.length < 1200) return message;
      return replaceMessageText(message, microCompactText(text));
    });
  }

  if (plan.tier === "tier2" || plan.tier === "tier3" || plan.tier === "tier4") {
    const adapter = input.tokenPruningAdapter ?? defaultTokenPruningAdapter;
    messages = messages.map((message, index) => {
      const isHot = index >= messages.length - 4;
      if (isHot) return message;
      const text = textFromMessage(message);
      if (!text || text.length < 600) return message;
      const pruned = pruneMessageText(text, adapter);
      causalAnchorCount += pruned.causalAnchorCount;
      warnings.push(...pruned.warnings);
      return replaceMessageText(message, pruned.text);
    });
  }

  if (plan.tier === "tier4" && messages.length > 4) {
    warnings.push("emergency_collapse_retained_objective_next_action_and_recent_tail");
    messages = emergencyCollapseMessages(messages);
  }

  const telemetry: CompressionTelemetry = {
    tier: plan.tier,
    strategy: plan.strategy,
    pressure: plan.pressure,
    tokensBefore: input.tokensBefore,
    warnings: [...new Set(warnings)],
    staleExcludedCount: input.staleExcludedCount ?? 0,
    causalAnchorCount,
    rehydratedFiles: uniqueFiles(input.readFiles ?? [], input.modifiedFiles ?? []),
    ...(input.tierSchedule?.taskClass ? { taskClass: input.tierSchedule.taskClass } : {}),
    ...(typeof input.tierSchedule?.budgetTokens === "number" &&
    Number.isFinite(input.tierSchedule.budgetTokens)
      ? { budgetTokens: input.tierSchedule.budgetTokens }
      : {}),
  };
  return { plan, messages, telemetry };
}

export function finalizeCompressionTelemetry(
  telemetry: CompressionTelemetry,
  tokensAfter: number | undefined,
): CompressionTelemetry {
  if (typeof tokensAfter !== "number" || !Number.isFinite(tokensAfter)) return telemetry;
  return {
    ...telemetry,
    tokensAfter,
    compressionRatio: telemetry.tokensBefore > 0 ? round(tokensAfter / telemetry.tokensBefore) : undefined,
  };
}

/**
 * JSON-serializable P5 diagnostics. This lives on CompactionDetails only and
 * must never be written into CompressionArtifact.
 */
export type CompactionBudgetShadow = {
  taskClass?: string;
  plannedTier: CompressionTier;
  actualTier: CompressionTier;
  ignored: boolean;
  budgetExceeded: boolean;
  budgetTokens?: number;
  tokensBefore: number;
  generatedAt: string;
};

export function buildCompactionBudgetShadow(input: {
  schedule: TierSchedule | undefined;
  settings: CompactionSettings;
  tokensBefore: number;
  actualTier?: CompressionTier;
  ignored?: boolean;
  generatedAt?: string;
}): CompactionBudgetShadow | undefined {
  if (!input.schedule) return undefined;
  const plannedTier = selectCompressionPlan({
    tokensBefore: input.tokensBefore,
    settings: input.settings,
    thresholds: input.schedule.thresholds,
  }).tier;
  const actualTier = input.actualTier ?? plannedTier;
  const budgetTokens =
    typeof input.schedule.budgetTokens === "number" && Number.isFinite(input.schedule.budgetTokens)
      ? input.schedule.budgetTokens
      : undefined;
  return {
    ...(input.schedule.taskClass ? { taskClass: input.schedule.taskClass } : {}),
    plannedTier,
    actualTier,
    ignored: input.ignored ?? actualTier !== plannedTier,
    budgetExceeded: budgetTokens !== undefined && input.tokensBefore > budgetTokens,
    ...(budgetTokens !== undefined ? { budgetTokens } : {}),
    tokensBefore: input.tokensBefore,
    generatedAt: input.generatedAt ?? new Date().toISOString(),
  };
}

