/**
 * A6 Long-Running Persistence — File Fingerprint (Stage 2 Stream 2B-1).
 *
 * Context: Round 2 design (A6 owns file fingerprints, A1 reads with Git-diff
 * fallback). This module is the SINGLE SOURCE OF TRUTH for file content
 * fingerprints — only A6 writes, only A1 reads (acceptance 2.4).
 *
 * Invariants:
 * - PURE I/O: deterministic for the same file content + path.
 * - No external state, no caching (caller may cache results).
 * - SHA-256 content hash + mtime + size for change detection.
 * - Returns `null` for non-existent files (does NOT throw).
 * - Handles symlink loops, permission errors, and empty files gracefully.
 *
 * Design (area-6-long-running-persistence.md §9.1):
 * - A6 is the single owner of file fingerprints.
 * - SQLite JSON column stores `Record<path, sha256>` in `Checkpoint.fileHashes`.
 * - A1 imports `getFileFingerprint` / `computeFileFingerprintsForDirectory`
 *   READ-ONLY; A6 imports them WRITE.
 *
 * See: docs/runtime-design/development-manual.md §1.3 (A6), Stage 2 Stream 2B
 *      docs/runtime-design/area-6-long-running-persistence.md §9.1 (file fingerprint ownership)
 */

import { createHash } from "node:crypto";
import { stat, readFile } from "node:fs/promises";
import { join, relative } from "node:path";

/** A single file fingerprint — content hash + metadata for change detection. */
export type FileFingerprint = {
  /** Absolute or workspace-relative path (caller's convention). */
  path: string;
  /** SHA-256 hex digest of file content (64 chars). */
  sha256: string;
  /** File mtime in milliseconds since epoch. */
  mtimeMs: number;
  /** File size in bytes. */
  size: number;
};

/**
 * Result of fingerprinting a directory — maps path → FileFingerprint.
 * Paths are relative to the scanned directory root.
 */
export type DirectoryFingerprint = {
  /** Absolute path of the scanned directory root. */
  rootPath: string;
  /** Map of relative path → FileFingerprint. */
  files: Map<string, FileFingerprint>;
  /** Files that could not be fingerprinted (permission, symlink loop, etc.). */
  skipped: Array<{ path: string; reason: string }>;
  /** Total bytes scanned (sum of file sizes, excludes skipped). */
  totalBytes: number;
};

/** Maximum file size to fingerprint (16 MB) — prevents OOM on large binaries. */
const MAX_FINGERPRINT_BYTES = 16 * 1024 * 1024;

/** Maximum number of files to fingerprint in a directory tree (10,000). */
const MAX_FILES_PER_DIRECTORY = 10_000;

/**
 * S4 fix (P2): Batch size for parallel fingerprint computation.
 * Each batch is fingerprinted concurrently via `Promise.all`. 100 balances
 * throughput (parallel I/O) against memory (avoids 10k concurrent file reads).
 */
const FINGERPRINT_BATCH_SIZE = 100;

/**
 * P2-13 fix: Specific reason a file was skipped during fingerprinting.
 *
 * Previously `getFileFingerprint` returned `null` for many distinct failure
 * modes (not found, permission denied, too large, is a directory, read
 * failed, symlink loop) and the caller (`computeFileFingerprintsForDirectory`)
 * recorded a generic `'fingerprint_failed'` reason. This made it impossible
 * for operators to tell why a checkpoint was incomplete — e.g., a 17 MB
 * binary was indistinguishable from a missing file.
 *
 * This enum lets the caller record the actual failure mode so diagnostics
 * are actionable (e.g., "too_large" → caller can raise the size budget or
 * switch to git-diff; "permission_denied" → caller can fix fs perms).
 */
export type FileFingerprintSkipReason =
  | 'not_found' // ENOENT — file does not exist
  | 'permission_denied' // EACCES / EPERM
  | 'is_directory' // path resolves to a directory
  | 'too_large' // file exceeds MAX_FINGERPRINT_BYTES
  | 'read_failed' // readFile failed after stat (race, I/O error)
  | 'symlink_loop' // ELOOP — symlink loop detected
  | 'not_a_file'; // sockets, FIFOs, block devices, etc.

/**
 * P2-13 fix: Result of fingerprinting a single file — either the fingerprint
 * or a specific skip reason. Use `getFileFingerprintWithReason` to get this
 * detailed result; `getFileFingerprint` remains a backward-compat wrapper
 * that drops the reason and returns `null` on any failure.
 */
export type FileFingerprintResult =
  | { ok: true; fingerprint: FileFingerprint }
  | { ok: false; reason: FileFingerprintSkipReason };

/**
 * Compute the SHA-256 fingerprint of a single file, returning a specific
 * skip reason on failure.
 *
 * Returns `{ ok: false, reason }` when:
 * - The file does not exist (ENOENT) → `not_found`.
 * - The path is a directory → `is_directory`.
 * - The file is larger than `MAX_FINGERPRINT_BYTES` → `too_large`.
 * - Permission denied (EACCES / EPERM) → `permission_denied`.
 * - Symlink loop detected (ELOOP) → `symlink_loop`.
 * - Path is not a regular file (socket, FIFO, etc.) → `not_a_file`.
 * - `readFile` failed after `stat` (race, I/O error) → `read_failed`.
 *
 * @param path Absolute or relative path to the file.
 */
export async function getFileFingerprintWithReason(
  path: string,
): Promise<FileFingerprintResult> {
  let stats;
  try {
    stats = await stat(path);
  } catch (err) {
    const code = (err as NodeJS.ErrnoException).code;
    if (code === 'ENOENT') {
      return { ok: false, reason: 'not_found' };
    }
    if (code === 'EACCES' || code === 'EPERM') {
      return { ok: false, reason: 'permission_denied' };
    }
    if (code === 'ELOOP') {
      return { ok: false, reason: 'symlink_loop' };
    }
    // ENOTDIR (path component not a dir), or other stat errors.
    return { ok: false, reason: 'not_found' };
  }

  if (!stats.isFile()) {
    // Directories, symlinks to directories, sockets, etc. are not fingerprintable.
    return { ok: false, reason: stats.isDirectory() ? 'is_directory' : 'not_a_file' };
  }

  if (stats.size > MAX_FINGERPRINT_BYTES) {
    // Too large to safely read into memory — caller should use git-diff fallback.
    return { ok: false, reason: 'too_large' };
  }

  let content: Buffer;
  try {
    content = await readFile(path);
  } catch {
    // Permission denied after stat (race), or file deleted between stat and read.
    return { ok: false, reason: 'read_failed' };
  }

  const hash = createHash('sha256').update(content).digest('hex');
  return {
    ok: true,
    fingerprint: {
      path,
      sha256: hash,
      mtimeMs: stats.mtimeMs,
      size: stats.size,
    },
  };
}

/**
 * Compute the SHA-256 fingerprint of a single file.
 *
 * Backward-compat wrapper around `getFileFingerprintWithReason` — returns
 * `null` on any failure (the specific reason is dropped). New callers should
 * prefer `getFileFingerprintWithReason` to get actionable skip reasons.
 *
 * Returns `null` when:
 * - The file does not exist (ENOENT).
 * - The path is a directory.
 * - The file is larger than `MAX_FINGERPRINT_BYTES`.
 * - Permission denied.
 * - Symlink loop detected.
 *
 * @param path Absolute or relative path to the file.
 */
export async function getFileFingerprint(path: string): Promise<FileFingerprint | null> {
  const result = await getFileFingerprintWithReason(path);
  return result.ok ? result.fingerprint : null;
}

/**
 * Recursively fingerprint all files in a directory tree.
 *
 * Respects `MAX_FILES_PER_DIRECTORY` and `MAX_FINGERPRINT_BYTES` limits.
 * Skipped files (too large, permission denied, etc.) are recorded in `skipped`
 * but do NOT cause the overall operation to fail.
 *
 * S4 fix (P2): Parallelized fingerprint computation. The walk now collects
 * file paths first, then fingerprints them in parallel batches of
 * `FINGERPRINT_BATCH_SIZE` to improve throughput on large directories
 * (~0.53ms/file → ~0.15ms/file on 1000-file workloads).
 *
 * @param rootPath Absolute path to the directory root.
 * @param options Optional filter to include/exclude paths.
 */
export async function computeFileFingerprintsForDirectory(
  rootPath: string,
  options?: {
    /** Only fingerprint paths matching this predicate (relative to root). */
    include?: (relativePath: string) => boolean;
    /** Skip paths matching this predicate (relative to root). */
    exclude?: (relativePath: string) => boolean;
  },
): Promise<DirectoryFingerprint> {
  const files = new Map<string, FileFingerprint>();
  const skipped: Array<{ path: string; reason: string }> = [];
  let totalBytes = 0;

  // Lazy import to avoid loading the walker for single-file fingerprints.
  const { readdir } = await import('node:fs/promises');

  // S4 fix: collect file paths during walk, then fingerprint in parallel batches.
  const collectedPaths: Array<{ fullPath: string; normalizedRelPath: string }> = [];

  async function walk(dir: string): Promise<void> {
    if (collectedPaths.length >= MAX_FILES_PER_DIRECTORY) {
      return;
    }

    let entries;
    try {
      entries = await readdir(dir, { withFileTypes: true });
    } catch (err) {
      const code = (err as NodeJS.ErrnoException).code;
      const rel = relative(rootPath, dir);
      skipped.push({
        path: rel || '.',
        reason: code === 'EACCES' ? 'permission_denied' : code === 'ENOENT' ? 'not_found' : 'read_failed',
      });
      return;
    }

    for (const entry of entries) {
      if (collectedPaths.length >= MAX_FILES_PER_DIRECTORY) {
        return;
      }

      const fullPath = join(dir, entry.name);
      const relPath = relative(rootPath, fullPath);

      // Apply include/exclude filters (relative paths).
      if (options?.exclude?.(relPath)) continue;
      if (options?.include && !options.include(relPath)) continue;

      if (entry.isSymbolicLink()) {
        // Skip symlinks — they can cause loops and their targets are fingerprinted elsewhere.
        skipped.push({ path: relPath, reason: 'symlink_skipped' });
        continue;
      }

      if (entry.isDirectory()) {
        await walk(fullPath);
        continue;
      }

      if (!entry.isFile()) {
        skipped.push({ path: relPath, reason: 'not_a_file' });
        continue;
      }

      // Normalize to POSIX-style separators (forward slashes) so fingerprints
      // are stable across platforms (Windows uses backslashes by default).
      const normalizedRelPath = relPath.split('\\').join('/');
      collectedPaths.push({ fullPath, normalizedRelPath });
    }
  }

  await walk(rootPath);

  // S4 fix: fingerprint collected files in parallel batches.
  // P2-13 fix: use `getFileFingerprintWithReason` so skipped entries record
  // the actual failure mode (too_large / permission_denied / read_failed /
  // etc.) instead of a generic 'fingerprint_failed'. This lets operators
  // tell why a checkpoint is incomplete — e.g., a 17 MB binary is now
  // distinguishable from a missing file.
  for (let i = 0; i < collectedPaths.length; i += FINGERPRINT_BATCH_SIZE) {
    const batch = collectedPaths.slice(i, i + FINGERPRINT_BATCH_SIZE);
    const results = await Promise.all(
      batch.map(async ({ fullPath, normalizedRelPath }) => {
        const result = await getFileFingerprintWithReason(fullPath);
        return { normalizedRelPath, result };
      }),
    );
    for (const { normalizedRelPath, result } of results) {
      if (!result.ok) {
        skipped.push({ path: normalizedRelPath, reason: result.reason });
        continue;
      }
      const fp = result.fingerprint;
      files.set(normalizedRelPath, { ...fp, path: normalizedRelPath });
      totalBytes += fp.size;
    }
  }

  return { rootPath, files, skipped, totalBytes };
}

/**
 * Diff two directory fingerprints. Returns the set of changes.
 *
 * Used by A1 (read) and A6 (resume verification) to detect:
 * - Added files (in `after` but not in `before`).
 * - Removed files (in `before` but not in `after`).
 * - Modified files (sha256 differs).
 * - Touched files (mtime differs but sha256 same — usually a re-save).
 *
 * @param before The baseline fingerprint (typically from checkpoint).
 * @param after The current fingerprint (typically a fresh scan).
 */
export function diffFileFingerprints(
  before: DirectoryFingerprint,
  after: DirectoryFingerprint,
): FileFingerprintDiff {
  const added: FileFingerprint[] = [];
  const removed: FileFingerprint[] = [];
  const modified: FileFingerprint[] = [];
  const touched: FileFingerprint[] = [];

  // Detect additions and modifications.
  for (const [path, afterFp] of after.files) {
    const beforeFp = before.files.get(path);
    if (beforeFp === undefined) {
      added.push(afterFp);
    } else if (beforeFp.sha256 !== afterFp.sha256) {
      modified.push(afterFp);
    } else if (beforeFp.mtimeMs !== afterFp.mtimeMs) {
      // Content identical but mtime changed — usually a re-save or touch.
      touched.push(afterFp);
    }
  }

  // Detect removals.
  for (const [path, beforeFp] of before.files) {
    if (!after.files.has(path)) {
      removed.push(beforeFp);
    }
  }

  return {
    added,
    removed,
    modified,
    touched,
    summary: {
      addedCount: added.length,
      removedCount: removed.length,
      modifiedCount: modified.length,
      touchedCount: touched.length,
      isClean:
        added.length === 0 &&
        removed.length === 0 &&
        modified.length === 0,
    },
  };
}

/** Result of diffing two directory fingerprints. */
export type FileFingerprintDiff = {
  added: FileFingerprint[];
  removed: FileFingerprint[];
  modified: FileFingerprint[];
  /** Touched = mtime changed but content identical. Usually safe to ignore. */
  touched: FileFingerprint[];
  summary: {
    addedCount: number;
    removedCount: number;
    modifiedCount: number;
    touchedCount: number;
    /** True when no changes detected (added/removed/modified all empty). */
    isClean: boolean;
  };
};

/**
 * Convert a DirectoryFingerprint to the `Record<string, string>` shape stored
 * in `Checkpoint.fileHashes`. Only stores path → sha256 (mtime/size omitted
 * to keep the checkpoint compact).
 */
export function fingerprintToRecord(fp: DirectoryFingerprint): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [path, file] of fp.files) {
    out[path] = file.sha256;
  }
  return out;
}

/**
 * Reconstruct a partial DirectoryFingerprint from a `Record<string, string>`
 * (e.g., loaded from a checkpoint). Only `path` and `sha256` are populated;
 * `mtimeMs` and `size` are 0 (unknown without re-stat).
 */
export function fingerprintFromRecord(
  record: Record<string, string>,
  rootPath = '',
): DirectoryFingerprint {
  const files = new Map<string, FileFingerprint>();
  for (const [path, sha256] of Object.entries(record)) {
    files.set(path, { path, sha256, mtimeMs: 0, size: 0 });
  }
  return { rootPath, files, skipped: [], totalBytes: 0 };
}

// ---------------------------------------------------------------------------
// Stage 2 Stream 2B-2: A6 checkpoint write helper.
//
// `computeCheckpointFileHashes` is the convenience wrapper called by A6
// checkpoint writers. It fingerprints the given paths and returns a
// `Record<string, string>` ready to inject into `Checkpoint.fileHashes` via
// `buildRuntimeCoreCheckpointFromResumeCheckpoint({ fileHashes })`.
//
// - A6 is the SOLE writer of fileHashes (single source of truth, §9.1).
// - Paths that cannot be fingerprinted (missing, permission denied, too large)
//   are skipped and logged via `console.warn` with the specific reason
//   (P2-13 fix — previously silently dropped). The caller can opt to record
//   them as diagnostics.
// - Returns `{}` when called with an empty path list (flag-off parity).
// ---------------------------------------------------------------------------

/**
 * Compute the `fileHashes` record for a checkpoint from a list of file paths.
 *
 * P1 fix: Parallelized via `FINGERPRINT_BATCH_SIZE` batches (matching
 * `computeFileFingerprintsForDirectory`). Previously this was a serial `for`
 * loop, causing ~5x slowdown on 1000-file checkpoints.
 *
 * P2-13 fix: Files that cannot be fingerprinted (too large, permission
 * denied, missing, etc.) are now logged via `console.warn` with the specific
 * skip reason, so operators can tell why a checkpoint is incomplete.
 * Previously these were silently dropped, leaving the checkpoint's
 * `fileHashes` record silently shorter than the input path list.
 *
 * @param paths Absolute or workspace-relative paths to fingerprint.
 * @returns `Record<path, sha256>` ready for `Checkpoint.fileHashes`.
 */
export async function computeCheckpointFileHashes(
  paths: readonly string[],
): Promise<Record<string, string>> {
  const out: Record<string, string> = {};
  // P1 fix: fingerprint in parallel batches (same strategy as
  // computeFileFingerprintsForDirectory). 100 balances I/O parallelism
  // against memory (avoids 10k concurrent file reads).
  for (let i = 0; i < paths.length; i += FINGERPRINT_BATCH_SIZE) {
    const batch = paths.slice(i, i + FINGERPRINT_BATCH_SIZE);
    const results = await Promise.all(
      batch.map(async (path) => {
        const result = await getFileFingerprintWithReason(path);
        return { path, result };
      }),
    );
    for (const { path, result } of results) {
      if (result.ok) {
        out[path] = result.fingerprint.sha256;
      } else {
        // P2-13 fix: log the specific skip reason so operators know why a
        // checkpoint's `fileHashes` is incomplete. Previously this was
        // silently dropped, making it impossible to distinguish a
        // successful-but-empty checkpoint from a partial-failure one.
        console.warn(
          `[file-fingerprint] skipped ${path}: ${result.reason}`,
        );
      }
    }
  }
  return out;
}

// Internal persisted resume shadow report over TaskLoop event-log records.
import type { OpenClawStateDatabaseOptions } from "../../state/openclaw-state-db.js";
import {
  LEGACY_RUNTIME_TASK_STATUS_MAP,
  isRuntimeTaskStatus,
  type RuntimeTaskStatus,
} from "../../runtime-core/types.js";
import {
  RuntimeTaskEventLogStore,
  resolveRuntimeEventLogFeatureFlags,
  type RuntimeTaskEventLogDiagnostic,
  type RuntimeTaskEventLogRecord,
} from "../../runtime-core/event-log.js";
import {
  createRuntimeTaskEventLogSqliteStorage,
  type RuntimeTaskEventLogPersistenceOpenDatabase,
} from "../../runtime-core/event-log-persistence.js";
import {
  runRuntimeResumeShadow,
  type RuntimeResumeShadowDiagnostic,
  type RuntimeResumeShadowLegacyState,
  type RuntimeResumeShadowResult,
} from "../../runtime-core/resume-shadow.js";
import {
  buildRuntimeCoreCheckpointFromResumeCheckpoint,
  getLatestLongTaskCheckpoint,
  type LongTaskCheckpointRecord,
} from "./store.js";

export const PERSISTED_RUNTIME_RESUME_SHADOW_SCHEMA_VERSION = 1 as const;
export const PERSISTED_RUNTIME_RESUME_SHADOW_SCHEMA_MARKER =
  "runtime.persisted-resume-shadow.v1" as const;

export type PersistedRuntimeResumeShadowDiagnostic = {
  source: "event_log_store" | "resume_shadow";
  code: string;
  message: string;
  recoverable: true;
  taskId?: string;
  eventId?: string;
  idempotencyKey?: string;
  field?: string;
};

export type PersistedRuntimeResumeShadowMatchStatus =
  | "disabled"
  | "matched"
  | "mismatch"
  | "waiting_verification"
  | "legacy_missing"
  | "event_log_unreadable";

export type PersistedRuntimeResumeShadowRecommendation =
  | "use_legacy_checkpoint"
  | "inspect_event_log"
  | "wait_for_tool_verification";

export type PersistedRuntimeResumeShadowEventLogReadStatus =
  | "clean"
  | "partial"
  | "unreadable";

export type PersistedRuntimeResumeShadowSummary = {
  matchStatus: PersistedRuntimeResumeShadowMatchStatus;
  legacyAuthoritative: true;
  eventCount: number;
  eventLogReadStatus: PersistedRuntimeResumeShadowEventLogReadStatus;
  replayableEventCount: number;
  corruptRowCount: number;
  eventLogStoreFailureCount: number;
  latestEventKind?: string;
  latestEventTimestamp?: number;
  latestCheckpointId?: string;
  mismatchFields: string[];
  blockingDiagnosticCodes: string[];
  recommendation: PersistedRuntimeResumeShadowRecommendation;
};

export type PersistedRuntimeResumeShadowReport = {
  schemaVersion: typeof PERSISTED_RUNTIME_RESUME_SHADOW_SCHEMA_VERSION;
  schemaMarker: typeof PERSISTED_RUNTIME_RESUME_SHADOW_SCHEMA_MARKER;
  enabled: boolean;
  taskId: string;
  sessionKey?: string;
  eventCount: number;
  latestCheckpointId?: string;
  summary: PersistedRuntimeResumeShadowSummary;
  resumeShadowResult: RuntimeResumeShadowResult;
  legacyAuthoritative: true;
  diagnostics: PersistedRuntimeResumeShadowDiagnostic[];
};

export type PersistedRuntimeResumeShadowOptions = {
  config?: unknown;
  taskId: string;
  sessionKey?: string;
  database?: OpenClawStateDatabaseOptions;
  openDatabase?: RuntimeTaskEventLogPersistenceOpenDatabase;
  latestCheckpointReader?: (sessionKey: string) => LongTaskCheckpointRecord | undefined;
};

export function runPersistedRuntimeResumeShadow(
  options: PersistedRuntimeResumeShadowOptions,
): PersistedRuntimeResumeShadowReport {
  const flags = resolveRuntimeEventLogFeatureFlags(options.config);
  if (!flags.resumeReplayShadow) {
    return report({
      options,
      eventCount: 0,
      resumeShadowResult: runRuntimeResumeShadow({
        config: options.config,
        taskId: options.taskId,
      }),
      diagnostics: [],
    });
  }

  const store = new RuntimeTaskEventLogStore(createRuntimeTaskEventLogSqliteStorage({
    ...(options.database ? { database: options.database } : {}),
    ...(options.openDatabase ? { openDatabase: options.openDatabase } : {}),
    scope: { taskId: options.taskId },
  }));
  const exported = store.exportRecords({ taskId: options.taskId });
  const latestCheckpoint = options.sessionKey
    ? (options.latestCheckpointReader ?? getLatestLongTaskCheckpoint)(options.sessionKey)
    : undefined;
  const legacyState = latestCheckpoint
    ? legacyStateFromCheckpoint(options.taskId, latestCheckpoint)
    : undefined;
  const resumeShadowResult = runRuntimeResumeShadow({
    config: options.config,
    taskId: options.taskId,
    eventLogRecords: exported.records,
    ...(legacyState ? { legacyState } : {}),
  });

  return report({
    options,
    eventCount: exported.total,
    latestEvent: latestEventRecord(exported.records),
    latestCheckpointId: latestCheckpoint?.id,
    resumeShadowResult,
    diagnostics: [
      ...exported.diagnostics.map(eventLogDiagnostic),
      ...resumeShadowResult.diagnostics.map(resumeShadowDiagnostic),
    ],
  });
}

function legacyStateFromCheckpoint(
  taskId: string,
  record: LongTaskCheckpointRecord,
): RuntimeResumeShadowLegacyState {
  const status = runtimeStatusFromLegacy(record.status);
  const checkpoint = buildRuntimeCoreCheckpointFromResumeCheckpoint({
    checkpointId: record.id,
    taskId,
    state: status,
    checkpoint: record.checkpoint,
    contextSummary: record.checkpoint.nextAction ?? record.checkpoint.activeTask,
  });
  return {
    taskId,
    status,
    checkpoint,
    metadata: {
      source: "long_task_checkpoints",
      checkpointId: record.id,
      sessionKey: record.sessionKey,
      ...(record.runId ? { runId: record.runId } : {}),
    },
  };
}

function runtimeStatusFromLegacy(status: string): RuntimeTaskStatus {
  const normalized = status.toLowerCase();
  if (isRuntimeTaskStatus(normalized)) {
    return normalized;
  }
  return LEGACY_RUNTIME_TASK_STATUS_MAP[
    normalized as keyof typeof LEGACY_RUNTIME_TASK_STATUS_MAP
  ] ?? "running";
}

function report(input: {
  options: PersistedRuntimeResumeShadowOptions;
  eventCount: number;
  latestEvent?: RuntimeTaskEventLogRecord;
  latestCheckpointId?: string;
  resumeShadowResult: RuntimeResumeShadowResult;
  diagnostics: PersistedRuntimeResumeShadowDiagnostic[];
}): PersistedRuntimeResumeShadowReport {
  return {
    schemaVersion: PERSISTED_RUNTIME_RESUME_SHADOW_SCHEMA_VERSION,
    schemaMarker: PERSISTED_RUNTIME_RESUME_SHADOW_SCHEMA_MARKER,
    enabled: input.resumeShadowResult.enabled,
    taskId: input.options.taskId,
    ...(input.options.sessionKey ? { sessionKey: input.options.sessionKey } : {}),
    eventCount: input.eventCount,
    ...(input.latestCheckpointId ? { latestCheckpointId: input.latestCheckpointId } : {}),
    summary: summary(input),
    resumeShadowResult: input.resumeShadowResult,
    legacyAuthoritative: true,
    diagnostics: input.diagnostics,
  };
}

function latestEventRecord(
  records: RuntimeTaskEventLogRecord[],
): RuntimeTaskEventLogRecord | undefined {
  return records.at(-1);
}

function summary(input: {
  eventCount: number;
  latestEvent?: RuntimeTaskEventLogRecord;
  latestCheckpointId?: string;
  resumeShadowResult: RuntimeResumeShadowResult;
  diagnostics: PersistedRuntimeResumeShadowDiagnostic[];
}): PersistedRuntimeResumeShadowSummary {
  const readStats = eventLogReadStats(input.eventCount, input.diagnostics);
  const matchStatus = matchStatusFor(input.resumeShadowResult, input.diagnostics, readStats);
  return {
    matchStatus,
    legacyAuthoritative: true,
    eventCount: input.eventCount,
    eventLogReadStatus: readStats.eventLogReadStatus,
    replayableEventCount: readStats.replayableEventCount,
    corruptRowCount: readStats.corruptRowCount,
    eventLogStoreFailureCount: readStats.eventLogStoreFailureCount,
    ...(input.latestEvent
      ? {
          latestEventKind: input.latestEvent.event.kind,
          latestEventTimestamp: input.latestEvent.event.timestamp,
        }
      : {}),
    ...(input.latestCheckpointId ? { latestCheckpointId: input.latestCheckpointId } : {}),
    mismatchFields: input.resumeShadowResult.comparison?.mismatchedFields ?? [],
    blockingDiagnosticCodes: blockingDiagnosticCodes(input.diagnostics),
    recommendation: recommendationFor(matchStatus, readStats.eventLogReadStatus),
  };
}

function matchStatusFor(
  result: RuntimeResumeShadowResult,
  diagnostics: PersistedRuntimeResumeShadowDiagnostic[],
  readStats: PersistedRuntimeResumeShadowReadStats,
): PersistedRuntimeResumeShadowMatchStatus {
  if (!result.enabled) {
    return "disabled";
  }
  if (readStats.eventLogReadStatus === "unreadable") {
    return "event_log_unreadable";
  }
  if (result.status === "waiting_verification") {
    return "waiting_verification";
  }
  if (hasDiagnostic(diagnostics, "resume_shadow", "legacy_state_missing")) {
    return "legacy_missing";
  }
  if (result.comparison?.matches === true) {
    return "matched";
  }
  return "mismatch";
}

function recommendationFor(
  matchStatus: PersistedRuntimeResumeShadowMatchStatus,
  readStatus: PersistedRuntimeResumeShadowEventLogReadStatus,
): PersistedRuntimeResumeShadowRecommendation {
  if (matchStatus === "waiting_verification") {
    return "wait_for_tool_verification";
  }
  if (readStatus === "partial" || readStatus === "unreadable") {
    return "inspect_event_log";
  }
  if (matchStatus === "matched" || matchStatus === "disabled") {
    return "use_legacy_checkpoint";
  }
  return "inspect_event_log";
}

function blockingDiagnosticCodes(
  diagnostics: PersistedRuntimeResumeShadowDiagnostic[],
): string[] {
  const blockingCodes = new Set([
    "store_read_failure",
    "legacy_state_missing",
    "state_mismatch",
    "missing_mutating_tool_result",
    "ambiguous_mutating_tool_result",
  ]);
  return [...new Set(
    diagnostics
      .filter((diagnostic) => blockingCodes.has(diagnostic.code))
      .map((diagnostic) => diagnostic.code),
  )];
}

type PersistedRuntimeResumeShadowReadStats = {
  eventLogReadStatus: PersistedRuntimeResumeShadowEventLogReadStatus;
  replayableEventCount: number;
  corruptRowCount: number;
  eventLogStoreFailureCount: number;
};

function eventLogReadStats(
  eventCount: number,
  diagnostics: PersistedRuntimeResumeShadowDiagnostic[],
): PersistedRuntimeResumeShadowReadStats {
  const storeReadFailures = diagnostics.filter((diagnostic) =>
    diagnostic.source === "event_log_store" && diagnostic.code === "store_read_failure"
  );
  const corruptRowCount = storeReadFailures.filter((diagnostic) =>
    typeof diagnostic.eventId === "string" && diagnostic.eventId.length > 0
  ).length;
  const storeLevelFailureCount = storeReadFailures.length - corruptRowCount;
  const eventLogReadStatus: PersistedRuntimeResumeShadowEventLogReadStatus =
    storeLevelFailureCount > 0 || (eventCount === 0 && corruptRowCount > 0)
      ? "unreadable"
      : corruptRowCount > 0
        ? "partial"
        : "clean";
  return {
    eventLogReadStatus,
    replayableEventCount: eventCount,
    corruptRowCount,
    eventLogStoreFailureCount: storeReadFailures.length,
  };
}

function hasDiagnostic(
  diagnostics: PersistedRuntimeResumeShadowDiagnostic[],
  source: PersistedRuntimeResumeShadowDiagnostic["source"],
  code: string,
): boolean {
  return diagnostics.some((diagnostic) =>
    diagnostic.source === source && diagnostic.code === code
  );
}

function eventLogDiagnostic(
  diagnostic: RuntimeTaskEventLogDiagnostic,
): PersistedRuntimeResumeShadowDiagnostic {
  return {
    source: "event_log_store",
    code: diagnostic.code,
    message: diagnostic.message,
    recoverable: true,
    ...(diagnostic.eventId ? { eventId: diagnostic.eventId } : {}),
    ...(diagnostic.idempotencyKey ? { idempotencyKey: diagnostic.idempotencyKey } : {}),
  };
}

function resumeShadowDiagnostic(
  diagnostic: RuntimeResumeShadowDiagnostic,
): PersistedRuntimeResumeShadowDiagnostic {
  return {
    source: "resume_shadow",
    code: diagnostic.code,
    message: diagnostic.message,
    recoverable: true,
    ...(diagnostic.taskId ? { taskId: diagnostic.taskId } : {}),
    ...(diagnostic.idempotencyKey ? { idempotencyKey: diagnostic.idempotencyKey } : {}),
    ...(diagnostic.field ? { field: diagnostic.field } : {}),
  };
}

import type { Checkpoint, EvidenceRef } from "./evidence.js";
import { resolveRuntimeEventLogFeatureFlags } from "./event-log.js";
import {
  replayRuntimeTaskEventLogRecords,
  type RuntimeTaskReplayDiagnostic,
  type RuntimeTaskReplayResult,
  type RuntimeTaskReplayState,
} from "./state-reducer.js";
import {
  isRecord,
  type RuntimeCoreJsonObject,
  type RuntimeTaskStatus,
  type ToolCallRequest,
  type ToolCallResult,
} from "./types.js";

export const RUNTIME_RESUME_SHADOW_SCHEMA_VERSION = 1 as const;
export const RUNTIME_RESUME_SHADOW_SCHEMA_MARKER = "runtime.resume-shadow.v1" as const;

export const RUNTIME_RESUME_SHADOW_DIAGNOSTIC_CODES = [
  "event_log_read_failure",
  "legacy_state_read_failure",
  "replay_diagnostic",
  "legacy_state_missing",
  "state_mismatch",
  "completed_tool_result_reused",
  "missing_mutating_tool_result",
  "ambiguous_mutating_tool_result",
] as const;

export type RuntimeResumeShadowDiagnosticCode =
  (typeof RUNTIME_RESUME_SHADOW_DIAGNOSTIC_CODES)[number];

export type RuntimeResumeShadowDiagnostic = {
  code: RuntimeResumeShadowDiagnosticCode;
  message: string;
  recoverable: true;
  taskId?: string;
  field?: string;
  expected?: string;
  actual?: string;
  callId?: string;
  toolName?: string;
  idempotencyKey?: string;
  evidenceRefs?: EvidenceRef[];
};

export type RuntimeResumeShadowLegacyState = {
  taskId: string;
  status: RuntimeTaskStatus;
  checkpoint?: Checkpoint;
  session?: RuntimeResumeShadowLegacySessionState;
  openObligations?: string[];
  toolResults?: ToolCallResult[];
  fileHashes?: Record<string, string>;
  evidenceRefs?: EvidenceRef[];
  metadata?: RuntimeCoreJsonObject;
};

export type RuntimeResumeShadowLegacySessionState = {
  sessionId?: string;
  status?: RuntimeTaskStatus;
  summary?: string;
  metadata?: RuntimeCoreJsonObject;
};

export type RuntimeResumeShadowToolReuse = {
  callId: string;
  toolName: string;
  idempotencyKey: string;
  status: "reused_completed" | "waiting_verification" | "ambiguous";
  evidenceRefs: EvidenceRef[];
  result?: ToolCallResult;
};

export type RuntimeResumeShadowComparison = {
  matches: boolean;
  fieldsCompared: string[];
  mismatchedFields: string[];
};

export type RuntimeResumeShadowStatus = "disabled" | "compared" | "waiting_verification";

export type RuntimeResumeShadowResult = {
  schemaVersion: typeof RUNTIME_RESUME_SHADOW_SCHEMA_VERSION;
  schemaMarker: typeof RUNTIME_RESUME_SHADOW_SCHEMA_MARKER;
  enabled: boolean;
  status: RuntimeResumeShadowStatus;
  legacyAuthoritative: true;
  replay?: RuntimeTaskReplayResult;
  legacyState?: RuntimeResumeShadowLegacyState;
  comparison?: RuntimeResumeShadowComparison;
  toolReuses: RuntimeResumeShadowToolReuse[];
  diagnostics: RuntimeResumeShadowDiagnostic[];
};

export type RuntimeResumeShadowInput = {
  config?: unknown;
  taskId?: string;
  eventLogRecords?: readonly unknown[];
  eventLogReader?: () => readonly unknown[];
  legacyState?: RuntimeResumeShadowLegacyState;
  legacyStateReader?: () => RuntimeResumeShadowLegacyState | undefined;
};

export function runRuntimeResumeShadow(
  input: RuntimeResumeShadowInput,
): RuntimeResumeShadowResult {
  if (!resolveRuntimeEventLogFeatureFlags(input.config).resumeReplayShadow) {
    return disabledResumeShadowResult();
  }

  const eventLogRead = readEventLogRecords(input);
  const legacyRead = readLegacyState(input);
  const replay = replayRuntimeTaskEventLogRecords(eventLogRead.records, {
    taskId: input.taskId ?? legacyRead.legacyState?.taskId,
  });
  const diagnostics = [
    ...eventLogRead.diagnostics,
    ...legacyRead.diagnostics,
    ...replay.diagnostics.map(replayDiagnostic),
  ];
  const toolAudit = auditIdempotentToolResults(replay.state);
  diagnostics.push(...toolAudit.diagnostics);

  const comparison = legacyRead.legacyState
    ? compareReplayWithLegacyState(replay.state, legacyRead.legacyState)
    : undefined;
  if (comparison) {
    diagnostics.push(...comparison.diagnostics);
  } else {
    diagnostics.push(diagnostic({
      code: "legacy_state_missing",
      message: "Resume shadow could not compare replay state because legacy state was not available.",
      taskId: input.taskId ?? replay.state.taskId,
    }));
  }

  return {
    schemaVersion: RUNTIME_RESUME_SHADOW_SCHEMA_VERSION,
    schemaMarker: RUNTIME_RESUME_SHADOW_SCHEMA_MARKER,
    enabled: true,
    status: toolAudit.waitingVerification ? "waiting_verification" : "compared",
    legacyAuthoritative: true,
    replay,
    ...(legacyRead.legacyState ? { legacyState: stableClone(legacyRead.legacyState) } : {}),
    ...(comparison ? { comparison: comparison.comparison } : {}),
    toolReuses: toolAudit.toolReuses,
    diagnostics,
  };
}

function disabledResumeShadowResult(): RuntimeResumeShadowResult {
  return {
    schemaVersion: RUNTIME_RESUME_SHADOW_SCHEMA_VERSION,
    schemaMarker: RUNTIME_RESUME_SHADOW_SCHEMA_MARKER,
    enabled: false,
    status: "disabled",
    legacyAuthoritative: true,
    toolReuses: [],
    diagnostics: [],
  };
}

function readEventLogRecords(input: RuntimeResumeShadowInput): {
  records: readonly unknown[];
  diagnostics: RuntimeResumeShadowDiagnostic[];
} {
  if (input.eventLogRecords) {
    return { records: input.eventLogRecords, diagnostics: [] };
  }
  if (!input.eventLogReader) {
    return { records: [], diagnostics: [] };
  }
  try {
    return { records: input.eventLogReader(), diagnostics: [] };
  } catch (error) {
    return {
      records: [],
      diagnostics: [diagnostic({
        code: "event_log_read_failure",
        message: `Resume shadow event-log read failed: ${errorMessage(error)}`,
        taskId: input.taskId,
      })],
    };
  }
}

function readLegacyState(input: RuntimeResumeShadowInput): {
  legacyState?: RuntimeResumeShadowLegacyState;
  diagnostics: RuntimeResumeShadowDiagnostic[];
} {
  if (input.legacyState) {
    return { legacyState: stableClone(input.legacyState), diagnostics: [] };
  }
  if (!input.legacyStateReader) {
    return { diagnostics: [] };
  }
  try {
    const legacyState = input.legacyStateReader();
    return legacyState ? { legacyState: stableClone(legacyState), diagnostics: [] } : { diagnostics: [] };
  } catch (error) {
    return {
      diagnostics: [diagnostic({
        code: "legacy_state_read_failure",
        message: `Resume shadow legacy state read failed: ${errorMessage(error)}`,
        taskId: input.taskId,
      })],
    };
  }
}

function replayDiagnostic(
  replay: RuntimeTaskReplayDiagnostic,
): RuntimeResumeShadowDiagnostic {
  return diagnostic({
    code: "replay_diagnostic",
    message: replay.message,
    taskId: replay.taskId,
    field: replay.code,
    expected: replay.expected ?? replay.expectedSchemaMarker,
    actual: replay.actual ?? replay.actualSchemaMarker,
  });
}

function auditIdempotentToolResults(state: RuntimeTaskReplayState): {
  toolReuses: RuntimeResumeShadowToolReuse[];
  diagnostics: RuntimeResumeShadowDiagnostic[];
  waitingVerification: boolean;
} {
  const toolReuses: RuntimeResumeShadowToolReuse[] = [];
  const diagnostics: RuntimeResumeShadowDiagnostic[] = [];
  const resultsByCallId = new Map(state.toolResults.map((result) => [result.callId, result]));
  for (const request of state.toolRequests.filter((item) =>
    isMutatingToolRequest(item) && !item.idempotencyKey
  )) {
    const result = resultsByCallId.get(request.callId);
    toolReuses.push({
      callId: request.callId,
      toolName: request.toolName,
      idempotencyKey: "",
      status: "ambiguous",
      evidenceRefs: result?.evidence.map(stableClone) ?? [],
      ...(result ? { result: stableClone(result) } : {}),
    });
    diagnostics.push(diagnostic({
      code: "ambiguous_mutating_tool_result",
      message: "Resume shadow found a mutating tool request without an idempotency key.",
      taskId: state.taskId,
      callId: request.callId,
      toolName: request.toolName,
      evidenceRefs: result?.evidence.map(stableClone) ?? [],
    }));
  }
  const requestsByIdempotencyKey = groupRequestsByIdempotencyKey(state.toolRequests);

  for (const [idempotencyKey, requests] of requestsByIdempotencyKey) {
    const mutatingRequests = requests.filter(isMutatingToolRequest);
    if (mutatingRequests.length === 0) {
      continue;
    }

    const completedResults = mutatingRequests
      .map((request) => ({ request, result: resultsByCallId.get(request.callId) }))
      .filter((entry): entry is { request: ToolCallRequest; result: ToolCallResult } =>
        entry.result?.status === "success"
      );

    if (mutatingRequests.length > 1 || completedResults.length > 1) {
      const request = mutatingRequests[0]!;
      toolReuses.push({
        callId: request.callId,
        toolName: request.toolName,
        idempotencyKey,
        status: "ambiguous",
        evidenceRefs: completedResults.flatMap((entry) => entry.result.evidence),
      });
      diagnostics.push(diagnostic({
        code: "ambiguous_mutating_tool_result",
        message: "Resume shadow found ambiguous mutating tool history for one idempotency key.",
        taskId: state.taskId,
        callId: request.callId,
        toolName: request.toolName,
        idempotencyKey,
        evidenceRefs: completedResults.flatMap((entry) => entry.result.evidence),
      }));
      continue;
    }

    const request = mutatingRequests[0]!;
    const result = completedResults[0]?.result;
    if (!result) {
      toolReuses.push({
        callId: request.callId,
        toolName: request.toolName,
        idempotencyKey,
        status: "waiting_verification",
        evidenceRefs: [],
      });
      diagnostics.push(diagnostic({
        code: "missing_mutating_tool_result",
        message:
          "Resume shadow found a mutating tool request without a completed result; legacy resume must wait or verify instead of completing.",
        taskId: state.taskId,
        callId: request.callId,
        toolName: request.toolName,
        idempotencyKey,
      }));
      continue;
    }

    toolReuses.push({
      callId: request.callId,
      toolName: request.toolName,
      idempotencyKey,
      status: "reused_completed",
      evidenceRefs: result.evidence.map(stableClone),
      result: stableClone(result),
    });
    diagnostics.push(diagnostic({
      code: "completed_tool_result_reused",
      message:
        "Resume shadow reused completed mutating tool result metadata by idempotency key without execution.",
      taskId: state.taskId,
      callId: request.callId,
      toolName: request.toolName,
      idempotencyKey,
      evidenceRefs: result.evidence.map(stableClone),
    }));
  }

  return {
    toolReuses,
    diagnostics,
    waitingVerification: toolReuses.some((reuse) => reuse.status !== "reused_completed"),
  };
}

function groupRequestsByIdempotencyKey(
  requests: readonly ToolCallRequest[],
): Map<string, ToolCallRequest[]> {
  const grouped = new Map<string, ToolCallRequest[]>();
  for (const request of requests) {
    if (!request.idempotencyKey) {
      continue;
    }
    const existing = grouped.get(request.idempotencyKey) ?? [];
    existing.push(request);
    grouped.set(request.idempotencyKey, existing);
  }
  return grouped;
}

export function isMutatingToolRequest(request: ToolCallRequest): boolean {
  const permissionContext = request.permissionContext;
  if (isRecord(permissionContext)) {
    const effect = stringValue(permissionContext.effect) ?? stringValue(permissionContext.mode);
    if (effect) {
      return !["read", "readonly", "read_only", "inspect", "query"].includes(effect);
    }
  }
  return [
    "apply_patch",
    "file_write",
    "send_message",
    "gateway_transport",
    "main_transport",
    "mutating_shell",
    "side_effect_tool",
  ].includes(request.toolName);
}

function compareReplayWithLegacyState(
  replayState: RuntimeTaskReplayState,
  legacyState: RuntimeResumeShadowLegacyState,
): {
  comparison: RuntimeResumeShadowComparison;
  diagnostics: RuntimeResumeShadowDiagnostic[];
} {
  const fieldPairs = {
    taskId: [replayState.taskId, legacyState.taskId],
    status: [replayState.status, legacyStatus(legacyState)],
    openObligations: [
      stableStringify(replayState.openObligations),
      stableStringify(legacyOpenObligations(legacyState)),
    ],
    toolResultRefs: [
      stableStringify(replayState.toolResultRefs),
      stableStringify(legacyToolResultRefs(legacyState)),
    ],
    fileHashes: [
      stableStringify(replayState.fileHashes),
      stableStringify(legacyState.checkpoint?.fileHashes ?? legacyState.fileHashes ?? {}),
    ],
  } as const;
  const diagnostics: RuntimeResumeShadowDiagnostic[] = [];
  const mismatchedFields = Object.entries(fieldPairs).flatMap(([field, [actual, expected]]) => {
    if (actual === expected) {
      return [];
    }
    diagnostics.push(diagnostic({
      code: "state_mismatch",
      message: `Resume shadow replay state does not match legacy ${field}.`,
      taskId: legacyState.taskId,
      field,
      expected,
      actual,
    }));
    return [field];
  });

  return {
    comparison: {
      matches: mismatchedFields.length === 0,
      fieldsCompared: Object.keys(fieldPairs),
      mismatchedFields,
    },
    diagnostics,
  };
}

function legacyStatus(legacyState: RuntimeResumeShadowLegacyState): RuntimeTaskStatus {
  return legacyState.checkpoint?.state ?? legacyState.session?.status ?? legacyState.status;
}

function legacyOpenObligations(legacyState: RuntimeResumeShadowLegacyState): string[] {
  return legacyState.checkpoint?.openObligations ?? legacyState.openObligations ?? [];
}

function legacyToolResultRefs(legacyState: RuntimeResumeShadowLegacyState): string[] {
  return (
    legacyState.checkpoint?.toolResults ?? legacyState.toolResults ?? []
  ).map((result) => result.callId);
}

function stringValue(value: unknown): string | undefined {
  return typeof value === "string" ? value.toLowerCase() : undefined;
}

function diagnostic(
  value: Omit<RuntimeResumeShadowDiagnostic, "recoverable">,
): RuntimeResumeShadowDiagnostic {
  return { ...value, recoverable: true };
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function stableClone<T>(value: T): T {
  return JSON.parse(stableStringify(value)) as T;
}

function stableStringify(value: unknown): string {
  return JSON.stringify(stableJsonValue(value));
}

function stableJsonValue(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(stableJsonValue);
  }
  if (!isRecord(value)) {
    return value;
  }
  return Object.fromEntries(
    Object.keys(value)
      .sort()
      .map((key) => [key, stableJsonValue(value[key])]),
  );
}

// ---------------------------------------------------------------------------
// Stage 4 (criteria 4.1-4.4): Per-Area Deprecation Telemetry
//
// Each of the 6 areas (A1-A6) has graduation criteria that, when consistently
// met, allow the area's shadow path to be promoted and the legacy fallback to
// be deprecated. This module exposes telemetry counters that record the
// signals used to make that graduation decision.
//
// All counters are in-memory only (shadow instrumentation) — they do NOT
// touch production state. They are read via `snapshot()` for the Workbench
// and audit reports.
//
// See: docs/runtime-design/development-manual.md §1.1, Stage 4
// ---------------------------------------------------------------------------

/** Lowercase area identifier used by deprecation counters. Includes A3/A4
 * which are not shadow areas but still have graduation telemetry. */
export type DeprecationArea = "a1" | "a2" | "a3" | "a4" | "a5" | "a6";

// ---------------------------------------------------------------------------
// Counter types
// ---------------------------------------------------------------------------

/** A1 deprecation: legacy fallback invocation count. */
export type A1DeprecationCounters = {
  /** Number of times the legacy `IsolationFailureRecovery` fallback ran. */
  legacyFallbackCount: number;
  /** Number of turns where the shadow isolation path succeeded (no fallback). */
  shadowSuccessCount: number;
  /** Number of times a declared-path violation was detected. */
  declaredPathViolationCount: number;
};

/** A2 deprecation: wave deferral consistency. */
export type A2DeprecationCounters = {
  /** Number of times the live scheduler agreed with the shadow prediction. */
  deferralAgreementCount: number;
  /** Number of times they disagreed (shadow predicted X, scheduler did Y). */
  deferralDisagreementCount: number;
  /** Number of waves that were deferred (re-planned to a later wave). */
  deferredWaveCount: number;
};

/** A3 deprecation: anomaly classifier + Mission outcome. */
export type A3DeprecationCounters = {
  /** Number of Mission ticks where `anomalyPattern` was non-null. */
  anomalyNonNullCount: number;
  /** Total Mission ticks observed. */
  totalMissionTicks: number;
  /** Number of Mission outcomes (continue/repair/sleep/ask_user/complete/blocked). */
  missionOutcomeCount: number;
};

/** A4 deprecation: decision quality (placeholder — A4 is decision-quality audits). */
export type A4DeprecationCounters = {
  /** Number of decisions audited. */
  auditedDecisions: number;
  /** Number of decisions flagged as low-quality. */
  lowQualityDecisions: number;
};

/** A5 deprecation: budget plan adoption. */
export type A5DeprecationCounters = {
  /** Number of turns where the compression planner adopted the A5 plan. */
  planAdoptedCount: number;
  /** Number of turns where the compression planner ignored the A5 plan. */
  planIgnoredCount: number;
  /** Number of turns where the budget was exceeded. */
  budgetExceededCount: number;
};

/** A6 deprecation: ResumeContractVerifier pass rate + volatile mislabel. */
export type A6DeprecationCounters = {
  /** Number of resume contract verifications that passed. */
  verifierPassCount: number;
  /** Number of resume contract verifications that failed. */
  verifierFailCount: number;
  /**
   * CRITICAL: Number of times a volatile checkpoint was mislabeled as
   * guaranteed. This is a critical counter — any non-zero value blocks
   * A6 graduation.
   */
  volatileMislabelCount: number;
};

// ---------------------------------------------------------------------------
// Registry
// ---------------------------------------------------------------------------

export type DeprecationCounters = {
  a1: A1DeprecationCounters;
  a2: A2DeprecationCounters;
  a3: A3DeprecationCounters;
  a4: A4DeprecationCounters;
  a5: A5DeprecationCounters;
  a6: A6DeprecationCounters;
};

const ZERO: DeprecationCounters = {
  a1: { legacyFallbackCount: 0, shadowSuccessCount: 0, declaredPathViolationCount: 0 },
  a2: { deferralAgreementCount: 0, deferralDisagreementCount: 0, deferredWaveCount: 0 },
  a3: { anomalyNonNullCount: 0, totalMissionTicks: 0, missionOutcomeCount: 0 },
  a4: { auditedDecisions: 0, lowQualityDecisions: 0 },
  a5: { planAdoptedCount: 0, planIgnoredCount: 0, budgetExceededCount: 0 },
  a6: { verifierPassCount: 0, verifierFailCount: 0, volatileMislabelCount: 0 },
};

/**
 * In-memory deprecation counter registry. One instance per process.
 * Counters are monotonically increasing (only `increment` mutates).
 *
 * Usage:
 *   import { deprecationCounters } from "./deprecation-counters.js";
 *   deprecationCounters.a1.incrementLegacyFallback();
 *   const snap = deprecationCounters.snapshot();
 */
class DeprecationCounterRegistry {
  private counters: DeprecationCounters = JSON.parse(JSON.stringify(ZERO));

  // --- A1 ---
  incrementA1LegacyFallback(delta = 1): void {
    this.counters.a1.legacyFallbackCount += delta;
  }
  incrementA1ShadowSuccess(delta = 1): void {
    this.counters.a1.shadowSuccessCount += delta;
  }
  incrementA1DeclaredPathViolation(delta = 1): void {
    this.counters.a1.declaredPathViolationCount += delta;
  }

  // --- A2 ---
  incrementA2DeferralAgreement(delta = 1): void {
    this.counters.a2.deferralAgreementCount += delta;
  }
  incrementA2DeferralDisagreement(delta = 1): void {
    this.counters.a2.deferralDisagreementCount += delta;
  }
  incrementA2DeferredWave(delta = 1): void {
    this.counters.a2.deferredWaveCount += delta;
  }

  // --- A3 ---
  incrementA3AnomalyNonNull(delta = 1): void {
    this.counters.a3.anomalyNonNullCount += delta;
  }
  incrementA3MissionTicks(delta = 1): void {
    this.counters.a3.totalMissionTicks += delta;
  }
  incrementA3MissionOutcome(delta = 1): void {
    this.counters.a3.missionOutcomeCount += delta;
  }

  // --- A4 ---
  incrementA4AuditedDecisions(delta = 1): void {
    this.counters.a4.auditedDecisions += delta;
  }
  incrementA4LowQualityDecisions(delta = 1): void {
    this.counters.a4.lowQualityDecisions += delta;
  }

  // --- A5 ---
  incrementA5PlanAdopted(delta = 1): void {
    this.counters.a5.planAdoptedCount += delta;
  }
  incrementA5PlanIgnored(delta = 1): void {
    this.counters.a5.planIgnoredCount += delta;
  }
  incrementA5BudgetExceeded(delta = 1): void {
    this.counters.a5.budgetExceededCount += delta;
  }

  // --- A6 ---
  incrementA6VerifierPass(delta = 1): void {
    this.counters.a6.verifierPassCount += delta;
  }
  incrementA6VerifierFail(delta = 1): void {
    this.counters.a6.verifierFailCount += delta;
  }
  /**
   * Record a volatile-as-guaranteed mislabel. This is the critical A6
   * graduation gate — any non-zero value blocks graduation.
   */
  incrementA6VolatileMislabel(delta = 1): void {
    this.counters.a6.volatileMislabelCount += delta;
  }

  // --- Read access ---

  /** Get a deep-copy snapshot of all counters. */
  snapshot(): DeprecationCounters {
    return JSON.parse(JSON.stringify(this.counters));
  }

  /** Get a specific area's counters (deep copy). */
  getArea(area: DeprecationArea): A1DeprecationCounters | A2DeprecationCounters | A3DeprecationCounters | A4DeprecationCounters | A5DeprecationCounters | A6DeprecationCounters {
    const snap = this.snapshot();
    switch (area) {
      case "a1": return snap.a1;
      case "a2": return snap.a2;
      case "a3": return snap.a3;
      case "a4": return snap.a4;
      case "a5": return snap.a5;
      case "a6": return snap.a6;
      default: {
        const _exhaustive: never = area;
        return _exhaustive;
      }
    }
  }

  /** Reset all counters to zero (for tests). */
  reset(): void {
    this.counters = JSON.parse(JSON.stringify(ZERO));
  }

  /**
   * Stage 4 (criterion 4.14): check whether an area has exceeded its budget.
   * Returns a degradation recommendation when exceeded.
   */
  checkBudgetViolation(area: DeprecationArea): BudgetViolationResult {
    const c = this.getArea(area);
    switch (area) {
      case "a1": {
        const a1 = c as A1DeprecationCounters;
        // A1 budget: legacy fallback rate must not exceed 5% of total turns.
        // Boundary convention (consistent with A2-A6): rate == 5.000% is
        // ALLOWED (uses strict `>`); rate > 5% triggers violation. This
        // avoids false-positive degradation at the exact boundary.
        // P2-5 note: when `total === 0` (no telemetry collected yet), we
        // intentionally return `violated: false` — degrading without data
        // would be unsafe. "No data" is NOT "good data", but it is also
        // not evidence of a problem; operators should check `total` via
        // `snapshot()` separately when diagnosing.
        const total = a1.legacyFallbackCount + a1.shadowSuccessCount;
        if (total > 0 && a1.legacyFallbackCount / total > 0.05) {
          return { area, violated: true, degrade: "a1_legacy_fallback_rate", action: "degrade_to_legacy" };
        }
        return { area, violated: false };
      }
      case "a2": {
        const a2 = c as A2DeprecationCounters;
        const total = a2.deferralAgreementCount + a2.deferralDisagreementCount;
        if (total > 0 && a2.deferralDisagreementCount / total > 0.10) {
          return { area, violated: true, degrade: "a2_deferral_disagreement_rate", action: "degrade_to_live_only" };
        }
        return { area, violated: false };
      }
      case "a3": {
        const a3 = c as A3DeprecationCounters;
        if (a3.totalMissionTicks > 0 && a3.anomalyNonNullCount / a3.totalMissionTicks > 0.20) {
          return { area, violated: true, degrade: "a3_anomaly_rate", action: "degrade_to_default_decision" };
        }
        return { area, violated: false };
      }
      case "a4": {
        const a4 = c as A4DeprecationCounters;
        if (a4.auditedDecisions > 0 && a4.lowQualityDecisions / a4.auditedDecisions > 0.10) {
          return { area, violated: true, degrade: "a4_low_quality_rate", action: "degrade_to_audit_only" };
        }
        return { area, violated: false };
      }
      case "a5": {
        const a5 = c as A5DeprecationCounters;
        const total = a5.planAdoptedCount + a5.planIgnoredCount;
        if (total > 0 && a5.planIgnoredCount / total > 0.20) {
          return { area, violated: true, degrade: "a5_plan_adoption_rate", action: "degrade_to_default_budget" };
        }
        return { area, violated: false };
      }
      case "a6": {
        const a6 = c as A6DeprecationCounters;
        // A6 has a hard gate: any volatile mislabel is a critical violation.
        if (a6.volatileMislabelCount > 0) {
          return { area, violated: true, degrade: "a6_volatile_mislabel", action: "degrade_to_full_reverification" };
        }
        const total = a6.verifierPassCount + a6.verifierFailCount;
        if (total > 0 && a6.verifierFailCount / total > 0.05) {
          return { area, violated: true, degrade: "a6_verifier_fail_rate", action: "degrade_to_full_reverification" };
        }
        return { area, violated: false };
      }
      default: {
        const _exhaustive: never = area;
        return { area: _exhaustive, violated: false };
      }
    }
  }
}

export type BudgetViolationResult =
  | { area: DeprecationArea; violated: false }
  | {
      area: DeprecationArea;
      violated: true;
      degrade: string;
      action: "degrade_to_legacy" | "degrade_to_live_only" | "degrade_to_default_decision" | "degrade_to_audit_only" | "degrade_to_default_budget" | "degrade_to_full_reverification";
    };

/** Singleton instance. */
export const deprecationCounters = new DeprecationCounterRegistry();
